# Reference au bot Discord pour resolver les usernames depuis user_id
_BOT_REF = None


def set_bot_ref(bot):
    """Appelé depuis main.py pour que le site web puisse lookup les users."""
    global _BOT_REF
    _BOT_REF = bot


def _resolve_user_obj(user_id):
    """Retourne l'objet User Discord depuis l'ID, ou None si pas trouvé."""
    if _BOT_REF is None:
        return None
    try:
        uid_int = int(user_id)
    except Exception:
        return None
    try:
        u = _BOT_REF.get_user(uid_int)
        if u:
            return u
    except Exception:
        pass
    try:
        for g in _BOT_REF.guilds:
            m = g.get_member(uid_int)
            if m:
                return m
    except Exception:
        pass
    return None


def _avatar_petit(url: str) -> str:
    """Redimensionne une URL d'avatar Discord pour l'usage reel du site.

    discord.py construit TOUTES ses URLs en « ?size=1024 ». Le site n'affiche
    ces avatars qu'en pastilles de 26 a 46 px : chaque image pesait donc
    1024x1024x4 = 4 Mo une fois decodee, et il y en a une vingtaine par page.
    128 px couvre encore les ecrans 2x. Un seul endroit decide, sinon les deux
    appels divergent au premier oubli.
    """
    u = str(url or "")
    if not u:
        return ""
    return re.sub(r"([?&]size=)\d+", r"\g<1>128", u) if "size=" in u else u


def _resolve_avatar_url(user_id) -> str:
    """Retourne l'URL de la PP Discord d'un user, ou empty string si introuvable."""
    u = _resolve_user_obj(user_id)
    if not u:
        return ""
    try:
        return _avatar_petit(str(u.display_avatar.url))
    except Exception:
        try:
            return _avatar_petit(str(u.avatar.url)) if u.avatar else ""
        except Exception:
            return ""


def _resolve_username(user_id) -> str:
    """Retourne le username Discord depuis l'ID, ou l'ID si pas trouvé.

    Essaie d'abord le cache global, puis tous les members des guildes.
    Pour les VAs manuels (uid 'manual_*'), retourne le display_name stocke.
    """
    uid_str = str(user_id)
    # VA manuel : on lit le display_name dans users.json
    if uid_str.startswith("manual_"):
        try:
            users = json.loads(USERS_FILE.read_text(encoding="utf-8")) if USERS_FILE.exists() else {}
            entry = users.get(uid_str)
            if isinstance(entry, dict):
                nm = entry.get("display_name") or entry.get("username") or ""
                if nm:
                    return nm
        except Exception:
            pass
        return uid_str
    if _BOT_REF is None:
        return uid_str
    try:
        uid_int = int(user_id)
    except Exception:
        return str(user_id)
    # 1) Cache global (bot.get_user)
    try:
        u = _BOT_REF.get_user(uid_int)
        if u:
            return getattr(u, "name", None) or getattr(u, "display_name", None) or str(user_id)
    except Exception:
        pass
    # 2) Iterer les guildes et chercher dans members (cache populé par intents.members)
    try:
        for g in _BOT_REF.guilds:
            m = g.get_member(uid_int)
            if m:
                return getattr(m, "name", None) or getattr(m, "display_name", None) or str(user_id)
    except Exception:
        pass
    return str(user_id)


# Cache memoize des resolutions Discord (handle_lc -> result|None) avec TTL.
# La page Jailbreak appelle cette fonction pour CHAQUE VA, et chaque appel
# scanne TOUS les membres de TOUTES les guilds -> tres couteux avec bcp de VAs.
# Les noms/avatars Discord changent rarement : un cache 120s est sans risque.
_DISCORD_RESOLVE_CACHE = {}


def _norm_handle(s: str) -> str:
    """Normalise un pseudo pour comparaison : minuscules, sans ponctuation/espaces."""
    return re.sub(r"[^a-z0-9]", "", (s or "").lower())


def _resolve_discord_user_by_handle(handle: str):
    """Cherche un user Discord par username/handle (ex: 'safidy0356_08105' ou 'safidy').

    Retourne un dict {id, username, display_name, avatar_url} si trouve, sinon None.
    Match case-insensitive contre user.name, user.global_name et member.display_name
    dans toutes les guilds connues du bot.
    """
    if not handle or _BOT_REF is None:
        return None
    handle_lc = str(handle).strip().lower().lstrip("@")
    if not handle_lc:
        return None
    # Cache hit (TTL 120s)
    import time as _t_dr
    _now_dr = _t_dr.time()
    _hit = _DISCORD_RESOLVE_CACHE.get(handle_lc)
    if _hit is not None and (_now_dr - _hit[0]) < 120:
        return _hit[1]
    def _scan(target: str):
        """Cherche un membre dont un des pseudos correspond à `target`
        (exact, ou en ignorant ponctuation/espaces)."""
        tn = _norm_handle(target)
        seen_ids = set()
        try:
            for g in _BOT_REF.guilds:
                try:
                    for m in g.members:
                        if m.id in seen_ids:
                            continue
                        seen_ids.add(m.id)
                        _cands = (
                            (getattr(m, "name", "") or "").lower(),
                            (getattr(m, "global_name", "") or "").lower(),
                            (getattr(m, "display_name", "") or "").lower(),
                            (getattr(m, "nick", "") or "").lower(),
                        )
                        if target in _cands or (
                                tn and tn in {_norm_handle(c) for c in _cands if c}):
                            try:
                                avatar_url = _avatar_petit(str(m.display_avatar.url))
                            except Exception:
                                avatar_url = ""
                            return {
                                "id": str(m.id),
                                "username": getattr(m, "name", "") or "",
                                "display_name": getattr(m, "display_name", "") or getattr(m, "name", ""),
                                "avatar_url": avatar_url,
                            }
                except Exception:
                    continue
        except Exception:
            pass
        return None

    _result = _scan(handle_lc)
    # 2e passe : les pseudos enregistrés traînent souvent un suffixe numérique en
    # trop (« priscah0908_23400 » alors que le vrai pseudo est « priscah0908 »).
    # On retente une fois sans ce suffixe -> corrige tous les VA d'un coup.
    if _result is None:
        _base = re.sub(r"[_\-. ]?\d+$", "", handle_lc)
        if _base and _base != handle_lc and len(_base) >= 3:
            _result = _scan(_base)
    # Memoize (succes ET echec) pour 120s
    try:
        _DISCORD_RESOLVE_CACHE[handle_lc] = (_now_dr, _result)
        if len(_DISCORD_RESOLVE_CACHE) > 512:
            _DISCORD_RESOLVE_CACHE.clear()
    except Exception:
        pass
    return _result


def _find_identity_category(guild, identity: str):
    """Trouve la categorie portant le nom de l'identite (case-insensitive)."""
    target = identity.lower().strip()
    for cat in guild.categories:
        if cat.name.lower().strip() == target:
            return cat
    return None


def _move_channel_to_identity(channel_id: int, new_identity: str):
    """Déplace le salon <channel_id> dans la catégorie de <new_identity>.

    Tourne dans le thread Flask, mais l'action Discord doit etre dans le loop asyncio.
    Retourne (success: bool, info: str).
    """
    import asyncio
    if _BOT_REF is None:
        return False, "bot pas initialisé"
    if not channel_id:
        return False, "channel_id vide"
    loop = getattr(_BOT_REF, "loop", None)
    if loop is None or not loop.is_running():
        return False, "loop bot non actif"

    async def _do_move():
        for guild in _BOT_REF.guilds:
            channel = guild.get_channel(int(channel_id))
            if channel is None:
                continue
            category = _find_identity_category(guild, new_identity)
            if category is None:
                return False, f"pas de catégorie nommée '{new_identity}' sur le serveur"
            if channel.category and channel.category.id == category.id:
                return True, "déjà dans la bonne catégorie"
            try:
                await channel.edit(category=category, reason="Web: changement identité VA")
                return True, "ok"
            except Exception as e:
                return False, f"erreur edit: {e}"
        return False, f"salon {channel_id} introuvable"

    try:
        fut = asyncio.run_coroutine_threadsafe(_do_move(), loop)
        ok, info = fut.result(timeout=10)
        return ok, info
    except Exception as e:
        return False, f"timeout / erreur: {e}"


def _send_video_to_banger_channel(identity: str, video_bytes: bytes,
                                  filename: str = "banger.mp4",
                                  caption: str = "") -> tuple:
    """Envoie une video (bytes) dans le salon 'banger-{identity}' via le bot.

    Cherche, dans la categorie de l'identite, un salon texte dont le nom contient
    'banger' (priorite a celui qui contient aussi le nom de l'identite). Tourne
    dans le thread Flask -> l'action Discord passe par le loop asyncio du bot.
    Retourne (success: bool, info: str).
    """
    import asyncio
    import io
    if _BOT_REF is None:
        return False, "bot pas initialise"
    if not video_bytes:
        return False, "video vide"
    loop = getattr(_BOT_REF, "loop", None)
    if loop is None or not loop.is_running():
        return False, "loop bot non actif"
    ident = (identity or "").strip()
    if not ident:
        return False, "identite vide"

    async def _do_send():
        import discord
        ident_low = ident.lower()
        found_category = False
        for guild in _BOT_REF.guilds:
            cat = _find_identity_category(guild, ident)
            if cat is None:
                continue  # pas de categorie pour cette identite sur ce serveur
            found_category = True
            # On cherche UNIQUEMENT dans la categorie de l'identite -> jamais le
            # mauvais salon banger d'une autre identite.
            cands = [c for c in cat.channels
                     if isinstance(c, discord.TextChannel) and "banger" in c.name.lower()]
            if not cands:
                return False, f"pas de salon 'banger' dans la categorie '{ident}'"
            # Priorite au salon qui se termine par '-{identite}' (ex '💥・banger-amelia')
            banger = None
            for c in cands:
                n = c.name.lower()
                if n.endswith("banger-" + ident_low) or n.endswith("-" + ident_low) or n == "banger-" + ident_low:
                    banger = c
                    break
            banger = banger or cands[0]
            limit = getattr(guild, "filesize_limit", 26214400) or 26214400
            if len(video_bytes) > limit:
                return (False, f"video {len(video_bytes)//(1024*1024)} Mo > limite Discord "
                               f"({limit//(1024*1024)} Mo) — serveur non boost ?")
            try:
                f = discord.File(io.BytesIO(video_bytes), filename=filename or "banger.mp4")
                await banger.send(content=(caption or "")[:1900], file=f)
                return True, f"#{banger.name}"
            except Exception as e:
                return False, f"erreur envoi Discord: {e}"
        if not found_category:
            return False, f"pas de catégorie nommée '{ident}' sur le serveur Discord"
        return False, f"pas de salon 'banger' dans la categorie '{ident}'"

    try:
        fut = asyncio.run_coroutine_threadsafe(_do_send(), loop)
        return fut.result(timeout=90)
    except Exception as e:
        return False, f"timeout / erreur: {e}"


def _send_reel_to_banger_channel(identity: str, video_path) -> tuple:
    """Envoie un REEL de la Bibliothèque dans banger-{identity} au FORMAT COMPLET
    (identique au bot quand il envoie un reel a un VA) : vidéo CLEAN + EXEMPLE
    + message CAPTION + message DESCRIPTION.

    `video_path` = chemin du fichier video CLEAN. caption/description/exemple sont
    deduits par convention de nommage (meme que cogs/autopost.random_reel_data) :
    <stem>.txt, <stem>.desc.txt, <stem>.example.<ext>.
    Retourne (ok, info_str, meta) ; meta={guild_id,channel_id,message_ids} ou None.
    """
    import asyncio
    from pathlib import Path as _P
    if _BOT_REF is None:
        return False, "bot pas initialise", None
    loop = getattr(_BOT_REF, "loop", None)
    if loop is None or not loop.is_running():
        return False, "loop bot non actif", None
    ident = (identity or "").strip()
    if not ident:
        return False, "identite vide", None
    video_path = _P(video_path)
    if not video_path.exists() or not video_path.is_file():
        return False, "fichier introuvable", None

    def _unesc(s):
        return s.replace("\\n", "\n") if s else s
    caption = ""
    description = ""
    try:
        cap_p = video_path.with_suffix(".txt")
        if cap_p.exists():
            caption = _unesc(cap_p.read_text(encoding="utf-8").strip())
    except Exception:
        pass
    try:
        desc_p = video_path.with_suffix(".desc.txt")
        if desc_p.exists():
            description = _unesc(desc_p.read_text(encoding="utf-8").strip())
    except Exception:
        pass
    example = None
    for ext in VIDEO_EXTS:
        c = video_path.parent / f"{video_path.stem}.example{ext}"
        if c.exists():
            example = c
            break

    async def _do_send():
        import discord
        ident_low = ident.lower()
        found_category = False
        for guild in _BOT_REF.guilds:
            cat = _find_identity_category(guild, ident)
            if cat is None:
                continue
            found_category = True
            cands = [c for c in cat.channels
                     if isinstance(c, discord.TextChannel) and "banger" in c.name.lower()]
            if not cands:
                return False, f"pas de salon 'banger' dans la categorie '{ident}'", None
            banger = None
            for c in cands:
                n = c.name.lower()
                if n.endswith("banger-" + ident_low) or n.endswith("-" + ident_low) or n == "banger-" + ident_low:
                    banger = c
                    break
            banger = banger or cands[0]
            limit = getattr(guild, "filesize_limit", 26214400) or 26214400
            if video_path.stat().st_size > limit:
                return (False, f"video {video_path.stat().st_size//(1024*1024)} Mo > limite Discord "
                               f"({limit//(1024*1024)} Mo) — serveur non boost ?", None)
            intro = f"▶ **REEL — identité `{ident}`**\n↓ Télécharge la vidéo CLEAN."
            if example:
                intro += "\n👁️ La 2e pièce jointe est l'EXEMPLE — NE PAS la télécharger."
            files = [discord.File(str(video_path), filename=video_path.name)]
            if example:
                files.append(discord.File(str(example), filename=f"EXEMPLE_{example.name}"))
            sent_ids = []  # on garde tous les message_id pour pouvoir les supprimer plus tard
            try:
                m = await banger.send(content=intro, files=files)
                sent_ids.append(m.id)
            except discord.HTTPException:
                try:
                    m = await banger.send(content=intro, file=discord.File(str(video_path), filename=video_path.name))
                    sent_ids.append(m.id)
                except discord.HTTPException as e:
                    return False, f"erreur envoi Discord: {e}", None
            if caption:
                m = await banger.send("📝 **CAPTION** (à mettre **PAR-DESSUS la vidéo** dans l'éditeur Insta) :")
                sent_ids.append(m.id)
                m = await banger.send(caption[:1990])
                sent_ids.append(m.id)
            if description:
                m = await banger.send("📄 **DESCRIPTION** (à coller dans le **champ légende** du post) :")
                sent_ids.append(m.id)
                # Discord cap 2000 car/message -> on decoupe les longues descriptions
                for i in range(0, len(description), 1990):
                    m = await banger.send(description[i:i + 1990])
                    sent_ids.append(m.id)
            meta = {"guild_id": guild.id, "channel_id": banger.id, "message_ids": sent_ids}
            return True, f"#{banger.name}", meta
        if not found_category:
            return False, f"pas de catégorie nommée '{ident}' sur le serveur Discord", None
        return False, f"pas de salon 'banger' dans la categorie '{ident}'", None

    try:
        fut = asyncio.run_coroutine_threadsafe(_do_send(), loop)
        return fut.result(timeout=120)
    except Exception as e:
        return False, f"timeout / erreur: {e}", None


# ===== Marquage "banger" (etoile jaune) : persiste file_id -> infos d'envoi =====
# Format : { file_id: {"guild_id": int, "channel_id": int, "message_ids": [int,...]} }
# (ancien format = simple liste de file_ids -> migré automatiquement en dict).
# La membership `file_id in marks` marche pareil (clés du dict).
def _load_banger_marks() -> dict:
    # PERF : cache par mtime (_cached_json_load) -> re-parse seulement si le
    # fichier a change. Copie superficielle : les mutateurs (set/pop) modifient
    # leur copie puis sauvent (le save change le mtime -> invalide le cache).
    try:
        data = _cached_json_load(BANGER_MARKS_FILE)
        if isinstance(data, dict):
            return dict(data)
        if isinstance(data, list):
            return {fid: {} for fid in data}
    except Exception:
        pass
    return {}


def _save_banger_marks(marks: dict) -> None:
    try:
        BANGER_MARKS_FILE.parent.mkdir(parents=True, exist_ok=True)
        safe_json.write_text(BANGER_MARKS_FILE, json.dumps(marks, ensure_ascii=False))
    except Exception:
        pass


def _set_banger_mark(file_id: str, info: dict) -> None:
    m = _load_banger_marks()
    m[file_id] = info or {}
    _save_banger_marks(m)


def _pop_banger_mark(file_id: str) -> dict:
    """Retire le marquage et retourne ses infos d'envoi ({} si aucune)."""
    m = _load_banger_marks()
    info = m.pop(file_id, None)
    if info is not None:
        _save_banger_marks(m)
    return info or {}


# ---- Reels désactivés (grisés pour montrer qu'ils ne sont plus à utiliser) ----
DISABLED_REELS_FILE = DATA_DIR / "disabled_reels.json"


def _load_disabled_reels() -> set:
    # PERF : cache par mtime -> re-parse seulement si le fichier a change.
    try:
        data = _cached_json_load(DISABLED_REELS_FILE)
        if isinstance(data, list):
            return set(data)
        if isinstance(data, dict):
            return set(data.keys())
    except Exception:
        pass
    return set()


def _toggle_disabled_reel(file_id: str) -> bool:
    """Bascule l'état désactivé d'un reel. Retourne True si désormais désactivé."""
    s = _load_disabled_reels()
    now_off = file_id not in s
    if now_off:
        s.add(file_id)
    else:
        s.discard(file_id)
    try:
        DISABLED_REELS_FILE.parent.mkdir(parents=True, exist_ok=True)
        safe_json.write_text(DISABLED_REELS_FILE, json.dumps(sorted(s), ensure_ascii=False))
    except Exception:
        pass
    return now_off


# ---- Rushs bruts favoris (⭐) : un VRAI favori, local, sans Discord ----------
#
# À ne pas confondre avec banger_marks.json, qui porte le même symbole mais ne
# fait pas la même chose : l'étoile « banger » d'un reel POSTE la vidéo dans
# banger-{identité} et stocke un accusé de réception. Ici, l'étoile ne fait
# que marquer ; rien n'est envoyé au clic, le VA vient chercher quand il veut.
#
# Et surtout : partager banger_marks.json aurait été un piège.
# _clear_banger_marks_for_identity purge par identité SANS regarder le
# sous-dossier — un clic sur « ⌫ Vider le salon banger » depuis la galerie des
# reels aurait effacé toutes les étoiles de brutes de l'identité.
# Le nom du fichier est historique : il ne portait que les rushs bruts, il
# porte aussi les templates de montage depuis le 22/08. On ne le renomme
# PAS — les etoiles deja posees vivent dedans, et un renommage sans
# migration les perdrait toutes en silence. La cle porte de toute facon le
# sous-dossier (« identite|brutes|... », « identite|templates|... »), donc
# rien n'est ambigu a la lecture.
FAV_BRUTES_FILE = DATA_DIR / "fav_brutes.json"


def _load_fav_brutes() -> set:
    # Même cache par mtime que les reels désactivés : re-parse seulement si le
    # fichier a changé. Tolère la liste et le dict, comme son modèle.
    try:
        data = _cached_json_load(FAV_BRUTES_FILE)
        if isinstance(data, list):
            return set(data)
        if isinstance(data, dict):
            return set(data.keys())
    except Exception:
        pass
    return set()


def _toggle_fav_brute(file_id: str) -> bool:
    """Bascule l'étoile d'une brute. Retourne True si désormais favorite."""
    s = _load_fav_brutes()
    now_on = file_id not in s
    if now_on:
        s.add(file_id)
    else:
        s.discard(file_id)
    try:
        FAV_BRUTES_FILE.parent.mkdir(parents=True, exist_ok=True)
        safe_json.write_text(FAV_BRUTES_FILE, json.dumps(sorted(s), ensure_ascii=False))
    except Exception:
        pass
    return now_on


def _pop_fav_brute(file_id: str) -> None:
    """Retire l'étoile d'une brute supprimée.

    Sans ça, un nouveau fichier portant le même nom hériterait de l'étoile de
    l'ancien — la clé est « identité|brutes|nom ». C'est exactement la raison
    pour laquelle /cloud/delete purge déjà la marque banger.
    """
    s = _load_fav_brutes()
    if file_id not in s:
        return
    s.discard(file_id)
    try:
        safe_json.write_text(FAV_BRUTES_FILE, json.dumps(sorted(s), ensure_ascii=False))
    except Exception:
        pass


def _delete_banger_messages(info: dict) -> tuple:
    """Supprime du salon Discord les messages envoyés pour ce reel (via le bot)."""
    import asyncio
    if not isinstance(info, dict):
        return True, "rien à supprimer"
    channel_id = info.get("channel_id")
    msg_ids = info.get("message_ids") or []
    if not channel_id or not msg_ids:
        return True, "rien à supprimer"
    if _BOT_REF is None:
        return False, "bot pas initialise"
    loop = getattr(_BOT_REF, "loop", None)
    if loop is None or not loop.is_running():
        return False, "loop bot non actif"

    async def _do_del():
        chan = _BOT_REF.get_channel(int(channel_id))
        if chan is None:
            return False, "salon Discord introuvable"
        deleted = 0
        for mid in msg_ids:
            try:
                m = await chan.fetch_message(int(mid))
                await m.delete()
                deleted += 1
            except Exception:
                pass  # deja supprime / introuvable -> on continue
        return True, f"{deleted} message(s) supprimé(s)"

    try:
        fut = asyncio.run_coroutine_threadsafe(_do_del(), loop)
        return fut.result(timeout=60)
    except Exception as e:
        return False, f"timeout / erreur: {e}"


def _clear_banger_marks_for_identity(identity: str) -> None:
    """Retire tous les marquages banger d'une identité (file_id 'identite|...')."""
    ident = (identity or "").strip().lower()
    if not ident:
        return
    m = _load_banger_marks()
    keys = [k for k in list(m.keys()) if k.split("|", 1)[0].lower() == ident]
    if keys:
        for k in keys:
            m.pop(k, None)
        _save_banger_marks(m)


def _purge_banger_channel(identity: str) -> tuple:
    """Supprime TOUS les messages postés par le bot dans le salon banger-{identity}.
    Suppression individuelle (message.delete) -> pas besoin de Manage Messages pour
    ses propres messages. Retourne (ok, info, count)."""
    import asyncio
    if _BOT_REF is None:
        return False, "bot pas initialise", 0
    loop = getattr(_BOT_REF, "loop", None)
    if loop is None or not loop.is_running():
        return False, "loop bot non actif", 0
    ident = (identity or "").strip()
    if not ident:
        return False, "identite vide", 0

    async def _do_purge():
        import discord
        ident_low = ident.lower()
        me_id = _BOT_REF.user.id if _BOT_REF.user else None
        if me_id is None:
            # Sécurité : sans identité du bot on NE supprime RIEN (sinon on risquerait
            # d'effacer les messages d'autres utilisateurs).
            return False, "bot non identifié (réessaie dans quelques secondes)", 0
        for guild in _BOT_REF.guilds:
            cat = _find_identity_category(guild, ident)
            if cat is None:
                continue
            cands = [c for c in cat.channels
                     if isinstance(c, discord.TextChannel) and "banger" in c.name.lower()]
            if not cands:
                return False, f"pas de salon 'banger' dans la categorie '{ident}'", 0
            banger = None
            for c in cands:
                n = c.name.lower()
                if n.endswith("banger-" + ident_low) or n.endswith("-" + ident_low) or n == "banger-" + ident_low:
                    banger = c
                    break
            banger = banger or cands[0]
            deleted = 0
            try:
                async for msg in banger.history(limit=1000):
                    # UNIQUEMENT les messages du bot (jamais ceux d'autres users)
                    if msg.author and msg.author.id == me_id:
                        try:
                            await msg.delete()
                            deleted += 1
                        except Exception:
                            pass
            except Exception as e:
                return False, f"erreur lecture historique: {e}", deleted
            return True, f"#{banger.name}", deleted
        return False, f"pas de catégorie nommée '{ident}' sur le serveur Discord", 0

    try:
        fut = asyncio.run_coroutine_threadsafe(_do_purge(), loop)
        return fut.result(timeout=180)
    except Exception as e:
        return False, f"timeout / erreur: {e}", 0


def _read_env_lines():
    """Lit .env en preservant les lignes (vide si fichier n'existe pas)."""
    if not ENV_FILE.exists():
        return []
    try:
        return ENV_FILE.read_text(encoding="utf-8").splitlines()
    except Exception:
        return []


def _write_env_var(key: str, value: str) -> bool:
    """Ecrit/remplace la variable <key>=<value> dans le .env. Retourne True si OK."""
    try:
        lines = _read_env_lines()
        found = False
        new_lines = []
        for line in lines:
            stripped = line.strip()
            if stripped.startswith(f"{key}=") or stripped.startswith(f"{key} ="):
                new_lines.append(f"{key}={value}")
                found = True
            else:
                new_lines.append(line)
        if not found:
            new_lines.append(f"{key}={value}")
        # Garantir un saut de ligne final
        content = "\n".join(new_lines).rstrip("\n") + "\n"
        ENV_FILE.write_text(content, encoding="utf-8")
        try:
            os.chmod(ENV_FILE, 0o600)
        except Exception:
            pass
        return True
    except Exception as e:
        log.error(f"Erreur ecriture .env: {e}")
        return False


def _schedule_restart(delay_sec: float = 2.0):
    """Exit le process apres <delay_sec> -> systemd auto-restart."""
    def _do_exit():
        time.sleep(delay_sec)
        log.warning("Exit demande via web UI - systemd va relancer le bot")
        os._exit(0)
    threading.Thread(target=_do_exit, daemon=True).start()

