def _preview_card(media_url: str, thumb_url: str, file_path, is_video: bool, file_id: str = "", example_url: str = "", deferred: bool = False, is_banger: bool = False, is_disabled: bool = False, is_va_ready: bool = False, can_montage: bool = None, a_approuver: bool = False, is_fav_brute: bool = False) -> str:
    """Carte preview style propre : juste un badge date en haut à gauche + thumbnail
    en grand. Plus de nom de fichier ni de taille en dessous (visible au hover via title).

    Si deferred=True, l img a data-src (pas src) et l IntersectionObserver
    se charge de la swap au moment ou la card devient visible.
    """
    name = file_path.name
    # can_montage non precise -> ancien comportement (= is_video)
    if can_montage is None:
        can_montage = is_video
    # Date upload courte format français (ex. "27 mai")
    try:
        import datetime as _dt_pc
        mtime = file_path.stat().st_mtime
        d = _dt_pc.date.fromtimestamp(mtime)
        fr_months = ["janv.", "févr.", "mars", "avr.", "mai", "juin",
                     "juil.", "août", "sept.", "oct.", "nov.", "déc."]
        date_short = f"{d.day} {fr_months[d.month - 1]}"
    except Exception:
        date_short = ""

    # Badge "play" superposé pour les vidéos
    play_badge = ""
    if is_video:
        play_badge = (
            "<div style='position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);"
            "width:44px;height:44px;background:rgba(0,0,0,.65);border-radius:50%;"
            "display:flex;align-items:center;justify-content:center;pointer-events:none'>"
            "<svg viewBox='0 0 24 24' width='22' height='22' fill='#fff'><polygon points='5 3 19 12 5 21'/></svg>"
            "</div>"
        )

    # Badge date en haut à GAUCHE — fond blanc frosted, texte foncé (lisible partout)
    date_badge = ""
    if date_short:
        date_badge = (
            f"<div class='card-date-badge' style='position:absolute;top:8px;left:8px;"
            f"background:rgba(255,255,255,.92);color:#1a1a1a;font-size:11px;font-weight:700;"
            f"padding:4px 10px;border-radius:6px;backdrop-filter:blur(8px);"
            f"letter-spacing:.01em;pointer-events:none;z-index:4;"
            f"box-shadow:0 2px 8px rgba(0,0,0,.2),0 0 0 1px rgba(255,255,255,.4) inset'>{date_short}</div>"
        )

    _va_cls = " va-ready" if is_va_ready else ""   # filigrane « DISPO VA » via CSS (togglable live)
    # Description reprise du post et pas encore relue : meme mecanique,
    # en ambre. Le proprietaire doit le voir SANS ouvrir la carte.
    _va_cls += " a-approuver" if a_approuver else ""
    is_video_js = "true" if is_video else "false"
    fid_safe = file_id.replace("'", "\\'") if file_id else ""
    example_safe = example_url.replace("'", "\\'") if example_url else ""
    # Pour le montage : URL de la vidéo EXEMPLE (media_url = l'exemple quand un exemple existe)
    montage_ex_safe = media_url.replace("'", "\\'") if example_url else ""
    # Skeleton placeholder + lazy image fade-in
    if deferred:
        img_tag = (
            f"<img data-src='{thumb_url}' class='vault-defer-img vault-img-load' loading='lazy' "
            f"src='data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSIxIiBoZWlnaHQ9IjEiPjwvc3ZnPg==' "
            f"style='width:100%;height:100%;object-fit:cover;display:block'>"
        )
    else:
        img_tag = (
            # onerror autant que onload : l image demarre a opacity:0 et n
            # apparait qu au chargement. Sans onerror, une vignette qui echoue
            # laissait une carte NOIRE pour toujours — impossible a distinguer
            # d un chargement en cours, et c est ce qui faisait croire a un
            # bug d affichage alors que la vignette n existait simplement pas.
            f"<img src='{thumb_url}' loading='lazy' class='vault-img-load' "
            f"onload='this.style.opacity=1' onerror='this.style.opacity=1' "
            f"style='width:100%;height:100%;object-fit:cover;display:block'>"
        )
    media_html = (
        f"<div onclick='openLightbox(\"{media_url}\",{is_video_js},\"{name}\",\"{fid_safe}\",\"{example_safe}\")' "
        f"title='{name}' class='vault-card-bg{_va_cls}' data-fid='{fid_safe}' "
        f"style='cursor:pointer;position:relative;width:100%;aspect-ratio:1;border-radius:10px;overflow:hidden'>"
        f"{img_tag}"
        f"{play_badge}"
        f"{date_badge}"
        f"</div>"
    )

    # Crayon (Edit) UNIQUEMENT pour les Reels (file_id contient |videos|).
    # Posts / Stories / Story CTA / PPs n'ont pas de caption/description à éditer.
    show_edit = "|videos|" in (file_id or "")
    actions_html = ""
    if file_id:
        # ★ Banger : envoie cette video dans le salon banger-{identite}. RESERVE
        # aux Reels : un rush brut ou un template n'a rien a y faire.
        banger_btn = ""
        if "|videos|" in (file_id or ""):
            _on = bool(is_banger)
            _scol = "#ffd54a" if _on else "#9aa0a6"        # jaune si marqué, gris sinon
            _sfill = "#ffd54a" if _on else "none"          # rempli si marqué, contour sinon
            _sstroke = "none" if _on else "#9aa0a6"
            _sw = "0" if _on else "2"
            _cls = "card-edit-btn banger-star" + (" is-banger" if _on else "")
            banger_btn = (
                f"<button class='{_cls}' onclick='event.stopPropagation();toggleBanger(this, \"{fid_safe}\")' "
                f"title='Marquer comme banger — envoie le reel dans le salon banger de l identité' style='color:{_scol}'>"
                f"<svg viewBox='0 0 24 24' width='14' height='14' fill='{_sfill}' stroke='{_sstroke}' stroke-width='{_sw}'><polygon points='12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2'/></svg>"
                f"</button>"
            )
        # ⭐ Favori : rushs bruts ET templates de montage. Rien n'est envoye au
        # clic — contrairement a l'etoile banger juste au-dessus, qui poste dans
        # Discord. Celle-ci ne fait que marquer.
        #
        # Sur les brutes elle alimente le bouton « Montage Banger » du menu VA.
        # Sur les templates elle ne sert (pour l'instant) qu'a retrouver les
        # bons d'un coup d'oeil dans l'editeur : elle ne change pas ce que le
        # VA recoit. Dire lequel des deux fait quoi evite de croire qu'etoiler
        # un template le mettra entre les mains des VA.
        fav_brute_btn = ""
        if "|brutes|" in (file_id or "") or "|templates|" in (file_id or ""):
            _fon = bool(is_fav_brute)
            _fcol = "#ffd54a" if _fon else "#9aa0a6"
            _ffill = "#ffd54a" if _fon else "none"
            _fstroke = "none" if _fon else "#9aa0a6"
            _fsw = "0" if _fon else "2"
            _fcls = "card-edit-btn fav-brute-star" + (" is-fav" if _fon else "")
            fav_brute_btn = (
                f"<button class='{_fcls}' onclick='event.stopPropagation();toggleFavBrute(this, \"{fid_safe}\")' "
                f"title='Favori — cette brute servira aux montages du bouton « Montage Banger »' style='color:{_fcol}'>"
                f"<svg viewBox='0 0 24 24' width='14' height='14' fill='{_ffill}' stroke='{_fstroke}' stroke-width='{_fsw}'><polygon points='12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2'/></svg>"
                f"</button>"
            )
        montage_btn = ""
        if can_montage:
            montage_btn = (
                f"<button class='card-edit-btn' onclick='event.stopPropagation();nxMontageOpen(\"{fid_safe}\", \"{montage_ex_safe}\")' "
                f"title='▶ Montage : générer des variations de ce reel' style='color:#a855f7'>"
                f"<svg viewBox='0 0 24 24' width='13' height='13' fill='currentColor'><polygon points='5 3 19 12 5 21 5 3'/></svg>"
                f"</button>"
            )
        edit_btn = ""
        if show_edit:
            edit_btn = (
                f"<button class='card-edit-btn' onclick='event.stopPropagation();openCaptionEditor(\"{fid_safe}\")' "
                f"title='Modifier caption / description'>"
                f"<svg viewBox='0 0 24 24' width='13' height='13' fill='none' stroke='currentColor' stroke-width='2.2'><path d='M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7'/><path d='M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z'/></svg>"
                f"</button>"
            )
        # ⊘ Désactiver : grise le reel pour montrer qu'il n'est plus à utiliser
        _doff = bool(is_disabled)
        _dcol = "#ef4444" if _doff else "#9aa0a6"
        disable_btn = (
            f"<button class='card-edit-btn reel-disable{(' is-off' if _doff else '')}' "
            f"onclick='event.stopPropagation();toggleReelDisabled(this, \"{fid_safe}\")' "
            f"title='Désactiver / réactiver ce reel (grise pour montrer qu il est désactivé)' style='color:{_dcol}'>"
            f"<svg viewBox='0 0 24 24' width='13' height='13' fill='none' stroke='currentColor' stroke-width='2.2'><circle cx='12' cy='12' r='9'/><line x1='5.6' y1='5.6' x2='18.4' y2='18.4'/></svg>"
            f"</button>"
        )
        actions_html = (
            f"<div class='card-actions' style='position:absolute;top:8px;right:8px;display:flex;gap:6px;align-items:center;z-index:5'>"
            f"{banger_btn}"
            f"{fav_brute_btn}"
            f"{montage_btn}"
            f"{edit_btn}"
            f"{disable_btn}"
            f"<label class='sel-circle-wrap' onclick='event.stopPropagation()' style='cursor:pointer;display:block'>"
            f"<input type='checkbox' class='sel-cb' "
            f"onchange='toggleSelect(\"{file_id}\", this.checked)' "
            f"style='position:absolute;opacity:0;pointer-events:none'>"
            f"<span class='sel-circle'></span>"
            f"</label>"
            f"</div>"
        )

    return (
        f"<div class='cloud-card{(' is-reel-off' if is_disabled else '')}' style='background:transparent;border:0;border-radius:10px;position:relative'>"
        f"{actions_html}"
        f"{media_html}"
        f"</div>"
    )


@ttl_cache(seconds=30)
def _cloud_ident_stats_cached(subdir: str, exts_t: tuple, idents_t: tuple) -> dict:
    """Stats sidebar (counts + tailles) par identité pour une galerie. PERF :
    memoize 30s (scan de TOUTES les identités × fichiers avec stat() à chaque
    affichage sinon) ; invalidé sur mutation via _success."""
    exts = set(exts_t)
    ident_stats = {}
    for ident in idents_t:
        folder = IDENTITIES_DIR / ident / subdir
        n_files = 0
        n_videos = 0
        n_images = 0
        size_mb = 0.0
        if folder.exists():
            for p in folder.iterdir():
                if not p.is_file():
                    continue
                if p.suffix.lower() not in exts or ".example" in p.name:
                    continue
                n_files += 1
                if p.suffix.lower() in VIDEO_EXTS:
                    n_videos += 1
                else:
                    n_images += 1
                try:
                    size_mb += p.stat().st_size / (1024 * 1024)
                except Exception:
                    pass
        ident_stats[ident] = {
            "n_files": n_files, "n_videos": n_videos,
            "n_images": n_images, "size_mb": size_mb,
        }
    return ident_stats


# ===== Vault PRO : 2e bibliothèque, stockage 100% SÉPARÉ =====
# Même moteur que la Bibliothèque (galerie, lightbox, upload, Drive) mais rangé
# dans des dossiers « pro_* » de chaque identité — aucun fichier en commun avec
# la Bibliothèque. Gaté RBAC (clé « provault ») : invisible pour les rôles
# restreints tant qu'on ne coche pas la case dans Rôles & permissions.
PRO_VAULT_PREFIX = "pro_"
# base (Bibliothèque) -> jumeau PRO. Sert aux uploads (champ caché « vault »).
_PRO_SUBDIR_OF = {
    "videos": "pro_videos",
    "posts": "pro_posts",
    "stories": "pro_stories",
    "storyctas": "pro_storyctas",
    "profile_pics": "pro_profile_pics",
    # Rushs et modèles de montage : sans ces deux lignes, un upload « vault=pro »
    # retombait SILENCIEUSEMENT dans la Bibliothèque (Reel montage).
    "brutes": "pro_brutes",
    "templates": "pro_templates",
}
# Source de vérité des dossiers servables/supprimables : les 5 routes qui
# validaient un set en dur divergeaient dès qu'on ajoutait un dossier.
def _cloud_media_path(identity: str, subdir: str, filename: str):
    """Chemin d'un media de la bibliotheque, ou (None, code, message).

    UN SEUL endroit decide : le dashboard et l'API du rig s'en servent tous
    les deux. Les controles sont dans l'ordre ou ils comptent — dossier
    connu, identite connue, puis remontee d'arborescence.
    """
    if subdir not in CLOUD_SUBDIRS:
        return None, 404, "sous-dossier inconnu"
    ident = (identity or "").lower().strip()
    if ident not in _list_identities():
        return None, 404, "identite inconnue"
    nom = filename or ""
    # « .. » etait refuse PARTOUT dans le nom, et pas seulement comme
    # segment de remontee. Or les captions Instagram sont pleines de
    # points de suspension — « trop bien... #ootd.mp4 » recevait donc un
    # 403 sur la miniature, sur la lecture, ET sur le telechargement par
    # le rig. Meme population de noms que le « # » deja corrige : c est la
    # seconde moitie du meme probleme.
    # Ce qui protege vraiment, ce n est pas ce test de sous-chaine mais la
    # VERIFICATION D APPARTENANCE ci-dessous : on resout le chemin et on
    # exige qu il reste sous le dossier de l identite. Un « .. » isole ne
    # peut donc rien, et un nom legitime passe.
    if "/" in nom or "\\" in nom or nom in ("..", ".") or not nom:
        return None, 403, "chemin invalide"
    base = (IDENTITIES_DIR / ident / subdir).resolve()
    try:
        chemin = (base / nom).resolve()
        chemin.relative_to(base)          # leve si on est sorti du dossier
    except (ValueError, OSError):
        return None, 403, "chemin invalide"
    if not chemin.exists() or not chemin.is_file():
        return None, 404, "fichier absent"
    return chemin, 200, ""


CLOUD_SUBDIRS = frozenset(
    {"videos", "posts", "stories", "storyctas", "profile_pics",
     "brutes", "templates"} | set(_PRO_SUBDIR_OF.values())
)


def _vault_subdir(base: str, form=None) -> str:
    """Dossier de destination d'un upload selon le vault d'où il part.

    Les 2 bibliothèques partagent les mêmes panneaux d'upload : c'est le champ
    caché « vault » du formulaire qui tranche. Absent/vide -> Bibliothèque
    (comportement historique), « pro » -> Vault PRO."""
    try:
        from flask import request as _rq
        val = (form if form is not None else _rq.form).get("vault", "")
    except Exception:
        val = ""
    if str(val or "").strip().lower() == "pro":
        return _PRO_SUBDIR_OF.get(base, base)
    return base


