        "      clearInterval(iv); done(); if(box){ box.innerHTML=''; box.style.display='none'; }"
        "      if(typeof loadSfsPushes==='function') loadSfsPushes(true);"
        "      if(typeof loadSfsInbox==='function') loadSfsInbox(true);"
