        "async function loadSfsInbox(force){"
        "  var box=document.getElementById('sfs-inbox-list'); if(!box) return;"
        "  if(!window.__sfsInbox){ box.innerHTML='◌ Synchro des messages entrants…'; }"
        "  try{"
        "    var r=await fetch('/sfssetup/sfs_inbox'+(force?'?refresh=1':'')); var j=await r.json();"
        "    if(!j.ok){ var w1=document.getElementById('sfs-inbox-wrap'); if(w1)w1.style.display=''; box.innerHTML='✕ '+(j.error||'API indisponible'); return; }"
        "    window.__sfsInbox=j.items||[];"
        "    renderSfsInbox();"
        "  }catch(e){ var w2=document.getElementById('sfs-inbox-wrap'); if(w2)w2.style.display=''; box.innerHTML='✕ '+e; }"
        "}"
        "function renderSfsInbox(){"
        "  var box=document.getElementById('sfs-inbox-list'); if(!box) return;"
        "  if(sfsInboxClosed()){ var wc=document.getElementById('sfs-inbox-wrap'); if(wc) wc.style.display='none'; return; }"
        "  if(!window.__sfsInbox){ window.__sfsInbox=[]; }"
        "  var plat=(window.__currentSfsPlatform==='MYM')?'mym':'onlyfans';"
        "  var items=[], hidden=0;"
        "  window.__sfsInbox.forEach(function(it){"
        "    if((it.platform||'')!==plat) return;"
        "    if(!window.__sfsShowAll && !isSfsPush(it.content)){ hidden++; return; }"
        "    items.push(it);"
        "  });"
        # rien à montrer -> la section entière se replie (pas de phrase moche)
        "  var wrap=document.getElementById('sfs-inbox-wrap');"
        "  if(!items.length){"
        "    if(window.__sfsInboxForceShow){ if(wrap) wrap.style.display=''; box.style.display=''; box.innerHTML='Aucun SFS reçu pour le moment.'; }"
        "    else { if(wrap) wrap.style.display='none'; box.innerHTML=''; }"
        "    return;"
        "  }"
        "  box.style.display='';"
        "  if(wrap) wrap.style.display='';"
        "  var h='';"
        "  items.slice(0,40).forEach(function(it){"
        "    var d=(it.at||'').replace('T',' ').slice(0,16);"
        "    h+='<div style=\"background:#101623;border-left:3px solid #e879f9;border-radius:6px;padding:7px 10px;margin-top:6px;font-size:12px\">'"
        "      +'<div style=\"display:flex;gap:8px;font-weight:700;font-size:11px;flex-wrap:wrap\"><span style=\"color:#e879f9\">'+sfsEsc(it.creator)+'</span>'"
        "      +'<span style=\"color:#667\">←</span><span style=\"color:#a5b4fc\">'+sfsEsc(it.fan_name||('fan #'+it.fan_id))+'</span>'"
        "      +(it.unread_count>1?('<span style=\"color:#f59e0b\">('+it.unread_count+' non lus)</span>'):'')"
        "      +'<span style=\"margin-left:auto;color:#556;font-weight:500\">'+sfsEsc(d)+'</span></div>'"
        "      +'<div style=\"color:#cdd3e1;margin-top:3px;white-space:pre-wrap\">'+sfsEsc(it.content)+'</div></div>';"
        "  });"
        "  if(hidden){ h+='<div style=\"color:#889;font-size:11px;margin-top:6px\">'+hidden+' message(s) hors-SFS masqué(s) — coche la case pour les voir.</div>'; }"
        "  if(items.length>40){ h+='<div style=\"color:#889;font-size:11px;margin-top:4px\">Affichage limité aux 40 plus récents ('+items.length+' au total).</div>'; }"
        "  box.innerHTML=h;"
        "}"
        "function renderSfsPushes(){"
        "  document.querySelectorAll('.sfs-push-bar').forEach(function(el){ el.remove(); });"
        "  var panel=document.getElementById('sfs-pushs-panel');"
        "  var plat=window.__currentSfsPlatform;"
        "  var onPlat=(plat==='MYM'||plat==='OF');"
        "  if(panel) panel.style.display=onPlat?'':'none';"
        "  if(typeof renderSfsInbox==='function') renderSfsInbox();"
        # titre fixe « SFS Planning » (plus de renommage par onglet)
        "  var bMym=document.getElementById('sfs-mym-sync'); var bOf=document.getElementById('sfs-of-import'); var bMaj=document.getElementById('sfs-maj-btn'); var bBil=document.getElementById('sfs-bilan-btn');"
        "  if(plat==='OF'){ if(bMym)bMym.style.display='none'; if(bMaj)bMaj.style.display='none'; if(bBil)bBil.style.display='none'; if(bOf)bOf.style.display='flex'; }"
        "  else if(plat==='MYM'){ if(bMym)bMym.style.display='flex'; if(bMaj)bMaj.style.display='flex'; if(bBil)bBil.style.display='flex'; if(bOf)bOf.style.display='none'; }"
        "  if(!onPlat) return;"
        "  if(plat==='OF'){ if(typeof renderOfPushes==='function') renderOfPushes(); return; }"
        "  const ps=window.__sfsPushCache; if(!ps) return;"
        "  const cells={};"
        "  document.querySelectorAll('.sfs-day').forEach(function(c){ cells[c.dataset.date]=c; });"
        "  const fIdent=window.__currentSfsIdent;"  # null = tous les modeles
        "  const fModel=(fIdent && window.__sfsIdentModel)?(window.__sfsIdentModel[String(fIdent).toLowerCase()]||''):'';"
        "  const fi=(fIdent||'').toLowerCase();"
        "  const byDate={}; let parseFail=0, nonSfs=0;"
        "  for(const p of ps){"
        "    if(fIdent){"
        "      const cre=(p.creator||'').toLowerCase();"
        "      const okId=(p.identity===fIdent);"
        "      const okM=(fModel && cre===String(fModel).toLowerCase());"
        "      const okFuzzy=(cre.indexOf(fi)===0 || cre.replace(/[^a-z0-9]/g,'').indexOf(fi.replace(/[^a-z0-9]/g,''))===0);"
        "      if(!okId && !okM && !okFuzzy) continue;"
        "    }"
        "    if(!window.__sfsShowAll && !isSfsPush(p.description)){ nonSfs++; continue; }"
        "    const parts=(p.sentAt||'').trim().split(/[ T]/);"
        "    const dmy=(parts[0]||'').split(/[\\/.-]/);"
        "    let iso=null;"
        "    if(dmy.length===3 && dmy[0].length===4){ iso=dmy[0]+'-'+dmy[1].padStart(2,'0')+'-'+dmy[2].padStart(2,'0'); }"
        "    else if(dmy.length===3){ iso=dmy[2]+'-'+dmy[1].padStart(2,'0')+'-'+dmy[0].padStart(2,'0'); }"
        "    if(!iso){ parseFail++; continue; }"
        "    (byDate[iso]=byDate[iso]||[]).push({creator:p.creator||'', time:parts[1]||'', desc:p.description||''});"
        "  }"
        # UNE barre compacte par jour (façon file d'attente MyM) : compteur +
        # barre pleine, sans pseudo répété. Clic = ouvre le panneau du jour
        # (les cartes y sont cliquables pour créer/modifier un SFS).
        "  for(const iso in byDate){"
        "    const cell=cells[iso]; if(!cell) continue;"
        "    const bars=cell.querySelector('.sfs-day-bars'); if(!bars) continue;"
        "    const list=byDate[iso];"
        "    const bar=document.createElement('div'); bar.className='sfs-push-bar';"
        "    bar.title=list.length+' push — '+list.map(function(x){ return (x.time||'')+' '+(x.creator||''); }).slice(0,5).join(' · ')+(list.length>5?' …':'');"
        "    bar.style.cssText='background:#f59e0b;color:#111;font-size:10px;font-weight:800;padding:2px 6px;border-radius:4px;display:flex;align-items:center;gap:5px;cursor:pointer';"
        "    const n=document.createElement('span');"
        "    n.style.cssText='background:rgba(0,0,0,.55);color:#fbbf24;border-radius:3px;padding:0 5px;line-height:14px';"
        "    n.textContent=list.length;"
        "    bar.appendChild(n);"
        "    bar.onclick=function(e){ e.stopPropagation(); if(typeof selectSfsDay==='function') selectSfsDay(iso); };"
        "    bars.appendChild(bar);"
        "  }"
        # plus de phrase de recap : la ligne de statut reste masquée hors synchro
        "  const box=document.getElementById('sfs-pushs-list');"
        "  if(box){ box.innerHTML=''; box.style.display='none'; }"
        "}"
        "function addSfsFromPush(date, creator, time){"
        "  if(typeof openSfsModal!=='function') return;"
        "  openSfsModal(date);"
        "  var f=document.getElementById('sfs-form');"
        "  if(f){ var t=f.querySelector('[name=time]'); if(t && time) t.value=time; }"
        "  var idSel=document.getElementById('sfs-modal-identity');"
        "  if(idSel && creator){"
        "    var cl=String(creator).toLowerCase();"
        "    for(var i=0;i<idSel.options.length;i++){ var ov=idSel.options[i].value.toLowerCase(); if(ov===cl || cl.indexOf(ov)===0 || ov.indexOf(cl)===0){ idSel.value=idSel.options[i].value; break; } }"
        "  }"
        "  var desc='', thumb='';"
        "  (window.__sfsPushCache||[]).forEach(function(p){"
        "    if(String(p.creator).toLowerCase()!==String(creator).toLowerCase()) return;"
        "    var parts=(p.sentAt||'').trim().split(/[ T]/);"
        "    if((parts[1]||'')!==time) return;"
        "    var dmy=(parts[0]||'').split(/[\\/.-]/);"
        "    var iso=(dmy.length===3)?(dmy[0].length===4?dmy[0]+'-'+dmy[1].padStart(2,'0')+'-'+dmy[2].padStart(2,'0'):dmy[2]+'-'+dmy[1].padStart(2,'0')+'-'+dmy[0].padStart(2,'0')):'';"
        "    if(iso===date){ desc=p.description||''; thumb=p.thumb||''; }"
        "  });"
        "  var ex=document.getElementById('sfs-modal-existing');"
        "  if(ex){"
        "    var bx=document.createElement('div'); bx.style.cssText='background:#1a1330;border:1px solid #a855f7;border-radius:10px;padding:12px;margin-bottom:8px;display:flex;gap:12px;align-items:flex-start';"
        "    var col=document.createElement('div'); col.style.cssText='flex:1;min-width:0';"
        "    var h=document.createElement('div'); h.style.cssText='color:#a855f7;font-weight:700;font-size:12px;margin-bottom:4px'; h.textContent='📨 Push '+creator+' · '+(time||''); col.appendChild(h);"
        "    var b=document.createElement('div'); b.style.cssText='font-size:12px;color:#ddd;white-space:pre-wrap'; b.textContent=desc; col.appendChild(b);"
        "    if(thumb){ var im=document.createElement('img'); im.src=thumb; im.style.cssText='width:90px;height:90px;object-fit:cover;border-radius:8px;flex-shrink:0;border:1px solid #2a2a2a'; im.onerror=function(){ this.remove(); }; bx.appendChild(im); }"
        "    bx.appendChild(col);"
        "    ex.insertBefore(bx, ex.firstChild);"
        "  }"
        "  var ttl=document.getElementById('sfs-modal-title'); if(ttl) ttl.textContent='Nouveau SFS lié au push — '+date;"
        "}"
        "function proofPreview(input){"
        "  if(!input || !input.files || !input.files[0]) return;"
        "  var zone=input.closest('.proof-zone'); if(!zone) return;"
        "  var img=zone.querySelector('.proof-preview');"
        "  if(img){ try{ img.src=URL.createObjectURL(input.files[0]); img.style.display='block'; }catch(e){} }"
        "  var hint=zone.querySelector('.proof-hint'); if(hint){ hint.textContent='✓ '+input.files[0].name; hint.style.color='#22c55e'; }"
        "  zone.classList.add('filled'); zone.style.borderColor='#22c55e';"
        "}"
        "async function loadSfsPushes(force){"
        "  const box=document.getElementById('sfs-pushs-list'); if(!box) return;"
        "  if(force){ box.style.display=''; box.innerHTML='◌ Synchro MyPuls…'; }"
        "  let subs=-1;"
