def _gmsdash_links_persist(team: str, links: list):
    """Sauve la dernière liste RÉUSSIE (champs minimaux) pour les pannes futures."""
    try:
        d = {}
        if GMSDASH_LINKS_FILE.exists():
            d = json.loads(GMSDASH_LINKS_FILE.read_text(encoding="utf-8")) or {}
        d[team] = [{"id": l.get("id"), "shortcode": l.get("shortcode") or "",
                    "display_name": l.get("display_name") or l.get("shortcode") or ""}
                   for l in links if l.get("id")]
        tmp = GMSDASH_LINKS_FILE.with_suffix(".json.tmp")
        safe_json.write_text(tmp, json.dumps(d, ensure_ascii=False))
        os.replace(str(tmp), str(GMSDASH_LINKS_FILE))
    except Exception:
        pass


def _gmsdash_links_fallback(team: str):
    """Liste de repli : dernière liste réussie (disque) sinon le seed embarqué."""
    try:
        if GMSDASH_LINKS_FILE.exists():
            d = json.loads(GMSDASH_LINKS_FILE.read_text(encoding="utf-8")) or {}
            if d.get(team):
                return d[team]
    except Exception:
        pass
    return GMSDASH_SEED_LINKS.get(team)
_GMSDASH_TTL = 45 * 60          # 45 min : le démon rafraîchit toutes les 30 min
_GMSDASH_WARM_PERIODS = ("today", "yesterday", "7", "q1", "q2")   # pré-calculées (dont quinzaines de paie)
_GMSDASH_LOCK = _threading_mod.Lock()
_GMSDASH_MEM: dict = {}         # "team|period" -> {ts, payload}
_GMSDASH_INFLIGHT: set = set()  # évite 2 calculs simultanés de la même clé
_GMSDASH_PROGRESS: dict = {}   # "team|period" -> {done,total,stage,error} (barre de progression)
_GMSDASH_LASTFAIL: dict = {}   # "team|period" -> {ts, error} : cooldown avant nouvelle tentative


def _gmsdash_load_disk():
    """Recharge le cache depuis le disque (survit à un redémarrage)."""
    global _GMSDASH_MEM
    try:
        if GMSDASH_CACHE_FILE.exists():
            d = json.loads(GMSDASH_CACHE_FILE.read_text(encoding="utf-8"))
            if isinstance(d, dict):
                _GMSDASH_MEM = d
    except Exception:
        _GMSDASH_MEM = {}


def _gmsdash_save_disk():
    try:
        DATA_DIR.mkdir(parents=True, exist_ok=True)
        tmp = GMSDASH_CACHE_FILE.with_suffix(".json.tmp")
        safe_json.write_text(tmp, json.dumps(_GMSDASH_MEM, ensure_ascii=False))
        os.replace(str(tmp), str(GMSDASH_CACHE_FILE))
    except Exception:
        pass


def _gmsdash_period_range(period: str):
    """(date_debut, date_fin, libellé) pour une période du sélecteur."""
    import datetime as _dt_p
    today = _dt_p.date.today()
    if period == "today":
        return today, today, "aujourd'hui"
    if period == "yesterday":
        y = today - _dt_p.timedelta(days=1)
        return y, y, "hier"
    if period == "30":
        return today - _dt_p.timedelta(days=29), today, "30 derniers jours"
    # Quinzaines de PAIE : q1 = 1-15, q2 = 16-fin. Si la quinzaine demandée n'a
    # pas commencé ce mois-ci, on montre celle du MOIS PRÉCÉDENT (la dernière payée).
    if period == "q1":
        start = today.replace(day=1)
        end = today if today.day <= 15 else today.replace(day=15)
        return start, end, f"quinzaine 1-15 ({start.strftime('%d/%m')} → {end.strftime('%d/%m')})"
    if period == "q2":
        if today.day >= 16:
            start, end = today.replace(day=16), today
        else:
            prev_end = today.replace(day=1) - _dt_p.timedelta(days=1)   # fin du mois précédent
            start, end = prev_end.replace(day=16), prev_end
        return start, end, f"quinzaine 16-fin ({start.strftime('%d/%m')} → {end.strftime('%d/%m')})"
    if period == "quinz":    # rétro-compat (ancien bouton)
        start = today.replace(day=1) if today.day <= 15 else today.replace(day=16)
        return start, today, ("quinzaine 1-15" if today.day <= 15 else "quinzaine 16-fin")
    return today - _dt_p.timedelta(days=6), today, "7 derniers jours"


def _gmsdash_compute(team: str, period: str, progress_key: str = None, store_cb=None,
                     force: bool = False) -> dict:
    """Calcule le détail par lien d'une catégorie (appel analytics par lien).
    Lent (~0.4 s/lien) — appelé par le démon, ou à la volée si le cache est vide."""
    from concurrent.futures import ThreadPoolExecutor
    import time as _t_c
    start, end, label = _gmsdash_period_range(period)
    s_iso, e_iso = start.isoformat(), end.isoformat()

    def _prog(inc=0, total=None, total_add=None, stage=None):
        """Alimente la barre de progression de la page (si progress_key)."""
        if not progress_key:
            return
        with _GMSDASH_LOCK:
            pr = _GMSDASH_PROGRESS.setdefault(progress_key,
                                              {"done": 0, "total": 0, "stage": "", "error": ""})
            if total is not None:
                pr["total"] = total
            if total_add:
                pr["total"] = pr.get("total", 0) + total_add
            if stage:
                pr["stage"] = stage
            if inc:
                pr["done"] = pr.get("done", 0) + inc
    try:
        import gms
        with gms.api_tag("dashboard"), gms.use_key(gms.next_dash_key()):
            # force (bouton ↻) : re-liste vraiment -> les RENOMMAGES de liens
            # apparaissent tout de suite (sinon cache de liste 15 min)
            _lr = gms.list_links_team(team, force_refresh=force) or {}
        if _lr.get("ok"):
            links = _lr.get("links") or []
            _gmsdash_links_persist(team, links)
        else:
            # Liste (REST) en échec -> on continue avec la DERNIÈRE liste connue
            # (disque, sinon seed embarqué) : les clics passent par MCP, un autre
            # serveur — on peut donc quand même afficher des résultats.
            links = _gmsdash_links_fallback(team)
            if not links:
                return {"ok": False, "error": f"liste des liens : {_lr.get('error') or '?'}"[:160]}
            print(f"[gmsdash] liste {team} en échec ({_lr.get('error')}) -> "
                  f"liste de secours ({len(links)} liens)", flush=True)
        _prog(total=len(links), stage="clics par lien")
    except Exception as e:
        return {"ok": False, "error": f"liste des liens : {e}"[:160]}

    # PHASE RAPIDE : le TOTAL de la catégorie coûte 1 appel par 20 liens (au lieu
    # d'1 par lien). Publié dans la progression -> la page affiche les cartes en
    # quelques secondes, pendant que le détail par lien se calcule derrière.
    if progress_key and links:
        _ids_all = [l.get("id") for l in links if l.get("id")]
        _nb = (len(_ids_all) + 19) // 20
        _prog(total_add=_nb, stage="total de la catégorie")
        q_tot, q_countries, q_ok = 0, {}, True
        for _i in range(0, len(_ids_all), 20):
            try:
                with gms.api_tag("dashboard"), gms.use_key(gms.next_dash_key()):
                    _res = gms.get_analytics_overview(s_iso, e_iso, link_ids=_ids_all[_i:_i + 20])
            except Exception:
                _res = {"ok": False}
            if _res.get("ok"):
                _d0 = _res.get("data") or {}
                q_tot += int(_d0.get("total_clicks") or 0)
                for _it in (_d0.get("top_countries") or []):
                    _cc = _it.get("country_code")
                    if _cc:
                        q_countries[_cc] = q_countries.get(_cc, 0) + int(_it.get("count") or 0)
            else:
                q_ok = False
            _prog(1)
        with _GMSDASH_LOCK:
            _pr = _GMSDASH_PROGRESS.get(progress_key)
            if _pr is not None:
                _pr["quick"] = {"total": q_tot, "us": q_countries.get("US", 0),
                                "fr": sum(int(q_countries.get(_c) or 0) for _c in GMSDASH_FR_COUNTRIES),
                                "countries": q_countries, "n_links": len(_ids_all),
                                "complete": q_ok}
        _prog(stage="clics par lien")

    _mmap_c = _gmsdash_model_map()

    def _model_of_sc(sc):
        sc = (sc or "").lower()
        return next((_mmap_c[suf] for suf in _mmap_c if sc.endswith(suf)), "autres")

    # Rattachement lien -> groupe GMS (« AMELIA JB TOKY ») : source de VÉRITÉ
    # quand le cookie marche — les noms de liens ne suffisent pas (ceux de toky
    # s'appellent juste « VA 1 »). Repli sur le nommage sinon.
    _grp_map = None
    try:
        _grp_map = gms.link_groups_map(team)
    except Exception:
        _grp_map = None
    import re as _re_bv
    _bare_va = _re_bv.compile(r"^va\s+\d+$")

    def _classify_jb(l):
        """(jb: bool, va: str) pour un lien."""
        dn = str(l.get("display_name") or "")
        g = str((_grp_map or {}).get(l.get("id")) or "").strip()
        if g and g.lower() != "ungrouped links":
            parts = [p for p in g.lower().split() if p != "jb"]
            if len(parts) >= 2:
                # Le VA = le mot qui n'est PAS une identité connue : l'ordre varie
                # selon les groupes (« ALICIA ANDRY » -> andry, « FANY EMMA » -> fany).
                _cand = [p for p in parts if p not in _mmap_c]
                return True, (_cand[-1] if _cand else parts[-1])
            return False, ""                        # groupe identité simple -> classique
        if _gmsdash_kind_is_jb(dn):
            return True, dn.lower().split()[0]
        if team == "tm_6a1ea410d882dd2173b8a315" and _bare_va.match(dn.lower().strip()):
            # marché FR : les liens « VA N » nus sont ceux des groupes JB TOKY
            # (vérifié sur le board — 34 liens = ses 3 groupes)
            return True, "toky"
        return False, ""

    def _one(l):
        lid = l.get("id")
        if not lid:
            return None
        try:
            with gms.api_tag("dashboard"), gms.use_key(gms.next_dash_key()):
                tot, ctry = gms.analytics_for_link(lid, s_iso, e_iso)
        except Exception:
            tot, ctry = None, None
        _jb, _va = _classify_jb(l)
        row = {"id": lid, "shortcode": l.get("shortcode") or "",
               "model": _model_of_sc(l.get("shortcode")),
               "jb": _jb, "va": _va,
               "name": l.get("display_name") or l.get("shortcode") or "",
               "clicks": tot,                 # None = lecture ratée (surtout pas 0)
               "us": (ctry or {}).get("US", 0),
               "fr": sum(int((ctry or {}).get(_c) or 0) for _c in GMSDASH_FR_COUNTRIES), "countries": ctry or {}}
        _prog(1)
        if progress_key:
            # rend ce lien visible dans la page PENDANT le calcul (tableau partiel)
            with _GMSDASH_LOCK:
                pr = _GMSDASH_PROGRESS.get(progress_key)
                if pr is not None:
                    pr.setdefault("rows", []).append(
                        {"id": lid, "shortcode": row["shortcode"], "name": row["name"],
                         "model": row["model"], "jb": row["jb"], "va": row["va"],
                         "clicks": tot or 0, "us": row["us"], "fr": row["fr"]})
        return row

    try:
        # bulk_mode : ce lot (des centaines d'appels) s'auto-freine, sans ralentir
        # les pages du site qui font aussi des appels GMS.
        with gms.bulk_mode(), ThreadPoolExecutor(max_workers=_gmsdash_workers()) as ex:
            rows = [r for r in ex.map(_one, links) if r]
    except Exception as e:
        return {"ok": False, "error": f"analytics : {e}"[:160]}
    # Rattrapage séquentiel des liens que le rate-limit a fait échouer.
    with gms.bulk_mode():
      for r in [x for x in rows if x["clicks"] is None]:
        _t_c.sleep(0.5)
        try:
            with gms.api_tag("dashboard"), gms.use_key(gms.next_dash_key()):
                tot2, ctry2 = gms.analytics_for_link(r["id"], s_iso, e_iso)
        except Exception:
            tot2, ctry2 = None, None
        if tot2 is not None:
            r["clicks"] = tot2
            r["us"] = (ctry2 or {}).get("US", 0)
            r["fr"] = sum(int((ctry2 or {}).get(_c) or 0) for _c in GMSDASH_FR_COUNTRIES)
            r["countries"] = ctry2 or {}
    failed = sum(1 for r in rows if r["clicks"] is None)
    countries: dict = {}
    for r in rows:
        for c, n in (r.get("countries") or {}).items():
            countries[c] = countries.get(c, 0) + int(n or 0)
        r.pop("countries", None)
        if r["clicks"] is None:
            r["clicks"] = 0                    # affichage seulement (cf. `failed`)
    # --- Courbe : clics JOUR PAR JOUR pour les meilleurs liens ---------------
    # L'analytics ne renvoie qu'un total par appel : une série coûte 1 appel par
    # lien ET par jour. On se limite donc aux N meilleurs liens sur 7 jours
    # (8 x 7 = 56 appels), ce qui suffit à voir qui génère quoi.
    _mods = sorted({r.get("model") for r in rows if r.get("model") and r.get("model") != "autres"})
    _avs = {}
    for _m in _mods:
        try:
            _avs[_m] = _identity_avatar_url(_m) or ""
        except Exception:
            _avs[_m] = ""
    base = {"ok": True, "team": team, "label": label, "start": s_iso, "end": e_iso,
            "links": rows, "countries": countries, "model_avatars": _avs,
            "failed": failed, "partial": failed > 0}
    if store_cb and rows:
        # Publie le tableau COMPLET tout de suite (la courbe suit) : la page passe
        # des liens partiels au tableau définitif sans attendre les 56 appels de série.
        try:
            store_cb(dict(base, series={"days": [], "links": []}))
        except Exception:
            pass
    base["series"] = _gmsdash_series(rows, days=7, top_n=8, prog=_prog)
    base["series_models"] = _gmsdash_series_models(rows, days=7, prog=_prog)
    base["series_vajb"] = _gmsdash_series_vajb(rows, days=7, prog=_prog)
    return base


def _gmsdash_series(rows: list, days: int = 7, top_n: int = 8, prog=None) -> dict:
    """Série quotidienne (clics + clics US) des `top_n` meilleurs liens : 1 appel
    par lien ET par jour — le seul moyen d'avoir le détail PAR PAYS jour par jour
    (get_time_series ne bucketise pas les pays, et l'utilisateur veut la courbe US).
    Coût 8×7=56 appels : absorbé par la clé dédiée + le démon (la page sert le cache)."""
    import datetime as _dt_se
    from concurrent.futures import ThreadPoolExecutor
    try:
        import gms
    except Exception:
        return {"days": [], "links": [], "us_available": False}
    top = sorted([r for r in rows if r.get("id")],
                 key=lambda r: -(r.get("clicks") or 0))[:top_n]
    if not top:
        return {"days": [], "links": [], "us_available": False}
    today = _dt_se.date.today()
    day_list = [(today - _dt_se.timedelta(days=i)).isoformat() for i in range(days - 1, -1, -1)]

    def _cell(job):
        lid, day = job
        try:
            with gms.api_tag("dashboard"), gms.use_key(gms.next_dash_key()):
                tot, ctry = gms.analytics_for_link(lid, day, day)
        except Exception:
            tot, ctry = None, None
        if prog:
            prog(1)
        return (lid, day, tot or 0, (ctry or {}).get("US", 0),
                sum(int((ctry or {}).get(_c) or 0) for _c in GMSDASH_FR_COUNTRIES))

    jobs = [(r["id"], d) for r in top for d in day_list]
    if prog:
        prog(total_add=len(jobs), stage="courbe des 7 jours (clics + US)")
    got: dict = {}
    try:
        with gms.bulk_mode(), ThreadPoolExecutor(max_workers=_gmsdash_workers()) as ex:
            for lid, day, tot, us, fr in ex.map(_cell, jobs):
                got[(lid, day)] = (tot, us, fr)
    except Exception:
        pass
    out = []
    for r in top:
        pts = [got.get((r["id"], d), (0, 0, 0))[0] for d in day_list]
        ups = [got.get((r["id"], d), (0, 0, 0))[1] for d in day_list]
        fps = [got.get((r["id"], d), (0, 0, 0))[2] for d in day_list]
        out.append({"id": r.get("id"), "name": r.get("name") or r.get("shortcode"),
                    "shortcode": r.get("shortcode"), "model": r.get("model") or "",
                    "jb": bool(r.get("jb")),
                    "points": pts, "us_points": ups, "fr_points": fps,
                    "total": sum(pts), "us_total": sum(ups), "fr_total": sum(fps)})
    return {"days": day_list, "links": out, "us_available": True}


def _gmsdash_workers() -> int:
    """Parallélisme des calculs : ~3 workers par clé dédiée (quota par clé)."""
    try:
        import gms
        n = max(1, len(gms.get_dash_keys()))
    except Exception:
        n = 1
    return min(12, 1 + 3 * n)


def _gmsdash_model_map() -> dict:
    """{suffixe_shortcode: modèle} trié du suffixe le plus long au plus court.
    Les shortcodes GMS finissent par le nom du modèle (xxxxlola, xxxxamelia…) ;
    exceptions connues : 'secret' -> hybride, 'jessy' -> jessye."""
    base = []
    try:
        import gms
        base += list(getattr(gms, "FR_MARKET_MODELS", []) or [])
    except Exception:
        pass
    try:
        base += list(_list_identities() or [])
    except Exception:
        pass
    m = {str(n).lower(): str(n).lower() for n in base if n}
    m.setdefault("jessye", "jessye")
    m["jessy"] = "jessye"
    m["secret"] = "hybride"
    return dict(sorted(m.items(), key=lambda kv: -len(kv[0])))


def _gmsdash_series_groups(rows: list, group_of, days: int = 7, prog=None,
                           stage: str = "courbe groupée", cap: int = 12) -> dict:
    """Courbes AGRÉGÉES : les liens sont groupés par group_of(row) (None = exclu),
    1 appel API par groupe (get_time_series en lot). us/fr = totaux de la période."""
    import datetime as _dt_sm
    from concurrent.futures import ThreadPoolExecutor
    try:
        import gms
    except Exception:
        return {"days": [], "links": [], "us_available": False}
    groups: dict = {}
    for r in rows:
        name = group_of(r)
        if not name:
            continue
        g = groups.setdefault(name, {"ids": [], "clicks": 0, "us": 0, "fr": 0})
        if r.get("id"):
            g["ids"].append(r["id"])
        g["clicks"] += r.get("clicks") or 0
        g["us"] += r.get("us") or 0
        g["fr"] += r.get("fr") or 0
    today = _dt_sm.date.today()
    day_list = [(today - _dt_sm.timedelta(days=i)).isoformat() for i in range(days - 1, -1, -1)]
    items = sorted([kv for kv in groups.items() if kv[1]["ids"]],
                   key=lambda kv: -kv[1]["clicks"])[:cap]
    if not items:
        return {"days": [], "links": [], "us_available": False}
    if prog:
        prog(total_add=len(items), stage=stage)

    def _one_grp(kv):
        name, g = kv
        try:
            with gms.api_tag("dashboard"), gms.use_key(gms.next_dash_key()):
                m = gms.time_series_for_links(g["ids"], day_list[0], day_list[-1])
        except Exception:
            m = None
        if prog:
            prog(1)
        return name, g, m          # None = LECTURE ECHOUEE (≠ 0 clic)

    out = []
    try:
        with gms.bulk_mode(), ThreadPoolExecutor(max_workers=_gmsdash_workers()) as ex:
            for name, g, m in ex.map(_one_grp, items):
                failed = m is None
                pts = [int((m or {}).get(d) or 0) for d in day_list]
                out.append({"name": f"{name} ({len(g['ids'])} liens)", "shortcode": "",
                            "model": name, "failed": failed,
                            "points": pts, "us_points": [], "fr_points": [],
                            # total connu par ailleurs (somme des liens) : on
                            # l'affiche même si la COURBE n'a pas pu être lue.
                            "total": (g["clicks"] if failed else sum(pts)),
                            "us_total": g["us"], "fr_total": g["fr"]})
    except Exception:
        pass
    out.sort(key=lambda x: -x["total"])
    return {"days": day_list, "links": out, "us_available": False}


def _gmsdash_series_models(rows: list, days: int = 7, prog=None) -> dict:
    """Courbes PAR MODÈLE, éclatées par TYPE (VA normaux / jailbreak) : une entrée
    par (modèle, type) — le front les somme ou les filtre selon le sélecteur
    « Tous / VA normaux / Jailbreak ». cap élargi (6 modèles × 2 types)."""
    mmap = _gmsdash_model_map()

    def _of(r):
        sc = (r.get("shortcode") or "").lower()
        model = next((mmap[suf] for suf in mmap if sc.endswith(suf)), "autres")
        return f"{model}⋄{'jb' if r.get('jb') else 'normal'}"

    se = _gmsdash_series_groups(rows, _of, days=days, prog=prog,
                                stage="courbe par modèle", cap=20)
    import re as _re_mk
    for e in (se.get("links") or []):
        raw = str(e.get("model") or "")
        model, _, kind = raw.partition("⋄")
        e["model"] = model
        e["jb"] = (kind == "jb")
        _mn = _re_mk.search(r"\((\d+) liens\)", str(e.get("name") or ""))
        e["n_links"] = int(_mn.group(1)) if _mn else 0
    return se


import re as _re_vajb
_VAJB_NAME = _re_vajb.compile(r"^\s*([a-z][a-z0-9_.]{1,20})\s+\d+\s*$")


def _gmsdash_kind_is_jb(display_name: str) -> bool:
    """True si le lien est un lien JAILBREAK (nommé « <va> N » : bo7 3, toky 5…).
    Les liens classiques sont « va_@handle » (ou tout autre nom)."""
    dn = str(display_name or "").lower()
    if dn.startswith("va_"):
        return False
    m = _VAJB_NAME.match(dn)
    return bool(m and m.group(1) not in ("va",))


def _gmsdash_series_vajb(rows: list, days: int = 7, prog=None) -> dict:
    """Courbes PAR VA JAILBREAK : les liens JB s'appellent « <va> N » (bo7 3,
    jaurel 10…) -> groupés par le nom du VA. Les liens classiques (va_@handle,
    VA N majuscule) sont exclus de cette vue."""
    def _of(r):
        return (r.get("va") or None) if r.get("jb") else None

    return _gmsdash_series_groups(rows, _of, days=days, prog=prog,
                                  stage="courbe par VA jailbreak", cap=12)


def _gmsdash_store(team: str, period: str, payload: dict):
    import time as _t_s
    if not payload.get("ok"):
        return
    payload["ver"] = GMSDASH_PAYLOAD_VER
    with _GMSDASH_LOCK:
        _GMSDASH_MEM[f"{team}|{period}"] = {"ts": int(_t_s.time()), "payload": payload}
        _gmsdash_save_disk()


def _gmsdash_kick(team: str, period: str, force: bool = False) -> bool:
    """Lance le calcul en ARRIÈRE-PLAN (1 seul à la fois par clé)."""
    key = f"{team}|{period}"
    import time as _t_k
    with _GMSDASH_LOCK:
        if key in _GMSDASH_INFLIGHT:
            return False
        _GMSDASH_INFLIGHT.add(key)
        _GMSDASH_PROGRESS[key] = {"done": 0, "total": 0, "rows": [],
                                  "started_at": int(_t_k.time()),
                                  "stage": "liste des liens", "error": ""}
    import threading as _th_k

    def _bg():
        try:
            payload = _gmsdash_compute(team, period, progress_key=key, force=force,
                                         store_cb=lambda pl: _gmsdash_store(team, period, pl))
            import time as _t_bg
            if payload.get("ok"):
                _gmsdash_store(team, period, payload)
                with _GMSDASH_LOCK:
                    _GMSDASH_PROGRESS.pop(key, None)
                    _GMSDASH_LASTFAIL.pop(key, None)
            else:
                err = str(payload.get("error") or "?")[:140]
                with _GMSDASH_LOCK:
                    _GMSDASH_LASTFAIL[key] = {"ts": int(_t_bg.time()), "error": err}
                    pr = _GMSDASH_PROGRESS.setdefault(
                        key, {"done": 0, "total": 0, "stage": "", "error": ""})
                    pr["error"] = err
        except Exception as e:
            import time as _t_bg2
            err = f"{type(e).__name__}: {e}"[:140]
            with _GMSDASH_LOCK:
                _GMSDASH_LASTFAIL[key] = {"ts": int(_t_bg2.time()), "error": err}
                pr = _GMSDASH_PROGRESS.setdefault(
                    key, {"done": 0, "total": 0, "stage": "", "error": ""})
                pr["error"] = err
        finally:
            with _GMSDASH_LOCK:
                _GMSDASH_INFLIGHT.discard(key)

    _th_k.Thread(target=_bg, daemon=True, name=f"gmsdash-{key}").start()
    return True


def _gmsdash_get(team: str, period: str, force: bool = False) -> dict:
    """INSTANTANÉ, toujours : sert ce qu'on a (même vieux) et lance le recalcul en
    arrière-plan si besoin. S'il n'y a encore RIEN, renvoie {loading, progress}
    que la page affiche en barre de progression (elle re-demande toutes les 2 s).
    La route ne bloque donc JAMAIS plusieurs secondes."""
    import time as _t_g
    key = f"{team}|{period}"
    with _GMSDASH_LOCK:
        hit = _GMSDASH_MEM.get(key)
    has = bool(hit and (hit.get("payload") or {}).get("links"))
    # Un cache d'une ANCIENNE version de payload (déploiement) = périmé : on le
    # sert quand même (instantané) mais on relance le calcul tout de suite au
    # lieu d'attendre le cycle 30 min du démon.
    fresh = (has and (hit.get("payload") or {}).get("ver") == GMSDASH_PAYLOAD_VER
             and (int(_t_g.time()) - int(hit.get("ts", 0))) < _GMSDASH_TTL)
    retry_in = 0
    if force or not fresh:
        # Cooldown après un échec : sans ça, chaque poll (2 s) relançait un calcul
        # qui re-échouait en boucle sur le 429 -> barre figée à « 0 / … » ET
        # martèlement de l'API qui entretenait la saturation.
        with _GMSDASH_LOCK:
            lf = _GMSDASH_LASTFAIL.get(key)
        if lf and not force:
            retry_in = 60 - (int(_t_g.time()) - int(lf.get("ts", 0)))
        if force or retry_in <= 0:
            retry_in = 0
            _gmsdash_kick(team, period, force=force)   # no-op si déjà en cours
    if has:
        out = dict(hit["payload"])
        out["cached_at"] = hit.get("ts")
        out["age_min"] = int((_t_g.time() - int(hit.get("ts", 0))) // 60)
        with _GMSDASH_LOCK:
            out["refreshing"] = key in _GMSDASH_INFLIGHT
            if out["refreshing"]:
                _pr = dict(_GMSDASH_PROGRESS.get(key) or {})
                _pr.pop("rows", None)
                out["progress"] = _pr          # barre + ETA par-dessus les vieilles données
        return out
    with _GMSDASH_LOCK:
        prog = dict(_GMSDASH_PROGRESS.get(key) or {})
        rows_partial = list(prog.pop("rows", []) or [])
        inflight = key in _GMSDASH_INFLIGHT
        lf = _GMSDASH_LASTFAIL.get(key)
    if not inflight and lf and retry_in > 0:
        _err = lf.get("error") or ""
        try:
            import gms as _g_u
            _u = _g_u.api_usage(10)
            _by = ", ".join(f"{k} {v}" for k, v in sorted(_u["by"].items(), key=lambda kv: -kv[1]))
            _err += f" · appels GMS 10 min : {_u['total']} ({_by}) · 429×{_u['e429']}"
        except Exception:
            pass
        prog = {"done": 0, "total": 0,
                "stage": f"échec — nouvelle tentative dans {max(1, retry_in)} s",
                "error": _err}
    return {"ok": True, "loading": True, "progress": prog,
            "team": team, "links": rows_partial, "countries": {}}


_GMSDASH_WARM_STARTED = False


def _gmsdash_warm_loop():
    """Recalcule toutes les catégories × périodes en boucle, en tâche de fond.
    Objectif : la page est déjà prête quand l'utilisateur ouvre le site."""
    import time as _t_w
    _t_w.sleep(240)                    # laisse passer la vague d'appels du boot (autres démons)
    while True:
        had_fail = False
        try:
            import gms
            if not gms.is_configured():
                _t_w.sleep(600)
                continue
            ids = [tid for tid, _n in GMSDASH_TEAMS]
            t0 = _t_w.time()
            for tid in ids:
                for per in _GMSDASH_WARM_PERIODS:
                    key = f"{tid}|{per}"
                    with _GMSDASH_LOCK:
                        hit = _GMSDASH_MEM.get(key)
                    if (hit and (hit.get("payload") or {}).get("links")
                            and (hit.get("payload") or {}).get("ver") == GMSDASH_PAYLOAD_VER
                            and (_t_w.time() - int(hit.get("ts", 0))) < 25 * 60):
                        continue          # frais ET au bon format -> pas de recalcul
                    try:
                        _res_w = _gmsdash_compute(tid, per)
                        if _res_w.get("ok"):
                            _gmsdash_store(tid, per, _res_w)
                        else:
                            had_fail = True
                            print(f"[gmsdash-warm] {tid}/{per} : {_res_w.get('error')}", flush=True)
                    except Exception as e:
                        had_fail = True
                        print(f"[gmsdash-warm] {tid}/{per} : {e}", flush=True)
                    _t_w.sleep(30)        # souffle entre les lots (partage le quota API)
            print(f"[gmsdash-warm] {len(ids)} catégorie(s) × {len(_GMSDASH_WARM_PERIODS)} "
                  f"période(s) en {int(_t_w.time() - t0)}s", flush=True)
        except Exception as e:
            had_fail = True
            print(f"[gmsdash-warm] crash: {e}", flush=True)
        # Échec (IP rate-limitée) -> nouvel essai dans 3 min, sinon cycle 30 min.
        _t_w.sleep(180 if had_fail else 30 * 60)


def _start_gmsdash_warm():
    global _GMSDASH_WARM_STARTED
    if _GMSDASH_WARM_STARTED:
        return
    _GMSDASH_WARM_STARTED = True
    _gmsdash_load_disk()
    import threading as _th_w
    _th_w.Thread(target=_gmsdash_warm_loop, daemon=True, name="gmsdash-warm").start()
    print("[gmsdash-warm] démon démarré (pré-calcul toutes les 30 min)", flush=True)


