def _render_security_sessions_html() -> str:
    """Liste des sessions actives."""
    sessions = _load_active_sessions()
    try:
        from flask import session as flask_session
        current_sid = flask_session.get("session_id")
        for s in sessions:
            if s.get("id") == current_sid:
                s["current"] = True
    except Exception:
        pass
    if not sessions:
        return (
            "<p style='color:#888'>Aucune session active trackée pour l'instant.</p>"
            "<small>Les sessions seront enregistrées au prochain login.</small>"
        )
    rows = ["<div style='display:flex;flex-direction:column;gap:10px;margin-top:14px'>"]
    import datetime
    for s in sessions[:20]:
        ts = s.get("last_seen", 0)
        try:
            last_seen = datetime.datetime.fromtimestamp(ts).strftime("%d/%m/%Y %H:%M")
        except Exception:
            last_seen = "?"
        is_current = s.get("current", False)
        badge = "<span style='background:#10b981;color:#fff;font-size:10px;padding:2px 8px;border-radius:10px;font-weight:700'>ACTUELLE</span>" if is_current else ""
        rows.append(
            f"<div style='background:#0f0f0f;border:1px solid #2a2a2a;border-radius:10px;padding:14px;display:flex;justify-content:space-between;align-items:center'>"
            f"<div>"
            f"<div style='font-weight:600;font-size:14px;margin-bottom:4px'>{s.get('user_agent_short', 'Unknown browser')} {badge}</div>"
            f"<div style='font-size:12px;color:#888'>IP : {s.get('ip', '?')} · Dernière activité : {last_seen}</div>"
            f"</div>"
            f"<form method='POST' action='/security/revoke_session' style='margin:0'>"
            f"<input type='hidden' name='session_id' value='{s.get('id', '')}'>"
            f"<button type='submit' class='danger-btn' data-confirm='Déconnecter cette session ?'>Déconnecter</button>"
            f"</form>"
            f"</div>"
        )
    rows.append("</div>")
    return "".join(rows)


def _load_role_users() -> list:
    """Liste des utilisateurs additionnels avec rôles."""
    f = DATA_DIR / "role_users.json"
    if not f.exists():
        return []
    try:
        return json.loads(f.read_text(encoding="utf-8"))
    except Exception:
        return []


def _save_role_users(users: list):
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    f = DATA_DIR / "role_users.json"
    safe_json.write_text(f, json.dumps(users, indent=2, ensure_ascii=False))


def _role_key(name) -> str:
    """Clé CANONIQUE d'un rôle : minuscules, espaces normalisés.

    BUG HISTORIQUE : les permissions étaient ENREGISTRÉES sous le nom tapé
    (« VA JB ») mais RELUES en minuscules par _role_allowed_tabs (« va jb »).
    Résultat : les droits n'étaient jamais trouvés -> l'employé retombait sur le
    minimum {saccount, sprefs}. Et comme l'éditeur relisait avec la clé brute,
    il réaffichait les cases cochées : on croyait la config enregistrée alors
    qu'elle ne s'appliquait pas. Tout passe désormais par cette fonction.
    """
    return " ".join(str(name or "").strip().lower().split())


def _load_role_definitions() -> dict:
    """Charge les définitions des rôles personnalisés (nom, description, permissions).

    Les clés sont NORMALISÉES à la lecture : les anciennes entrées écrites avec
    des majuscules (« VA JB ») redeviennent donc actives immédiatement, sans
    migration manuelle. Si deux variantes de casse coexistent, on garde celle
    qui a réellement des permissions.
    """
    f = DATA_DIR / "role_definitions.json"
    if not f.exists():
        return {}
    try:
        raw = json.loads(f.read_text(encoding="utf-8"))
    except Exception:
        return {}
    if not isinstance(raw, dict):
        return {}
    out: dict = {}
    for k, v in raw.items():
        nk = _role_key(k)
        if not nk:
            continue
        prev = out.get(nk)
        if prev is None:
            out[nk] = v
            continue
        # doublon de casse : on privilégie l'entrée qui porte des permissions
        def _npterms(d):
            p = (d or {}).get("permissions") or {}
            return sum(1 for x in p.values() if isinstance(x, dict) and x.get("enabled"))
        if _npterms(v) > _npterms(prev):
            out[nk] = v
    return out


def _save_role_definitions(data: dict):
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    # Écrit TOUJOURS en clés canoniques : plus jamais de « VA JB » vs « va jb ».
    clean = {}
    for k, v in (data or {}).items():
        nk = _role_key(k)
        if nk:
            clean[nk] = v
    safe_json.write_text(DATA_DIR / "role_definitions.json",
                         json.dumps(clean, indent=2, ensure_ascii=False))


