# Fallback pour un rôle SANS permissions définies (rétro-compat chatter).
_ROLE_ALLOWED_TABS = {
    "chatter": {"chatplanning", "revenus", "saccount", "sprefs"},
}


def _role_allowed_tabs(role):
    """Onglets (showTab name) visibles pour un rôle, ou None = accès complet.

    - owner / admin : None (accès complet).
    - Autres rôles : DÉRIVÉ des permissions définies via "Set permissions"
      (role_definitions[role]['permissions']) -> onglets dont enabled=True.
    - Rôle sans permissions définies : map connu (chatter) sinon MINIMAL
      (juste son compte) -> deny par défaut (un nouveau compte ne voit PAS tout).
    """
    r = _role_key(role)      # MÊME normalisation qu'à l'enregistrement (casse + espaces)
    if r in ("owner", "admin"):
        return None
    if not r:
        # Rôle vide / inconnu : on NE donne PAS l'accès complet (fail-closed).
        return {"saccount", "sprefs"}
    try:
        perms = _load_role_definitions().get(r, {}).get("permissions", {})
    except Exception:
        perms = {}
    if isinstance(perms, dict) and perms:
        allowed = set()
        for k, v in perms.items():
            if isinstance(v, dict) and v.get("enabled"):
                allowed |= _PERM_KEY_TO_TABS.get(k, {k})
        allowed |= {"saccount", "sprefs"}  # toujours son propre compte + préférences
        return allowed
    if r in _ROLE_ALLOWED_TABS:
        return _ROLE_ALLOWED_TABS[r]
    return {"saccount", "sprefs"}  # minimal : ne voit PAS tout par défaut


def _role_gate_script(allowed) -> str:
    """Script injecte (roles restreints uniquement) : cache les boutons sidebar,
    groupes/sections vides et panneaux non autorises, puis active l'onglet par
    defaut. Le contenu reste rendu cote serveur (pour ne pas casser le CSS/JS
    partage) ; ce script restreint la navigation et cache les panneaux interdits."""
    import json as _json
    allowed_js = _json.dumps(sorted(allowed))
    # Approche INVERSE (robuste aux structures imbriquees / boutons "SOON" sans
    # showTab) : on cache TOUT le sidebar, puis on ne revele QUE les onglets
    # autorises + leurs conteneurs parents.
    return (
        "<script>(function(){"
        "var A=" + allowed_js + ";if(!A||!A.length)return;"
        "var ok={};A.forEach(function(n){ok[n]=1;});"
        "function nm(b){var o=b.getAttribute('onclick')||'';"
        "var m=o.match(/showTab\\(\\s*'[^']*'\\s*,\\s*'([^']*)'/);"
        "if(m)return m[1];return (b.id&&b.id.indexOf('tab-')===0)?b.id.slice(4):'';}"
        "function run(){"
        "var sb=document.querySelector('.sidebar');if(!sb)return;"
        # 1) tout cacher
        "sb.querySelectorAll('.group,.solo-group,.items,.item,.section-label,.group-head').forEach(function(e){e.style.display='none';});"
        # 2) reveler chaque onglet autorise + tous ses ancetres (+ ouvrir les groupes)
        "function reveal(b){var el=b;while(el&&el!==sb){el.style.display='';"
        "if(el.classList&&el.classList.contains('group')){el.classList.add('open');"
        "var h=el.querySelector('.group-head');if(h)h.style.display='';}"
        "el=el.parentElement;}}"
        "function findBtn(name){var b=document.getElementById('tab-'+name);if(b)return b;"
        "var all=sb.querySelectorAll('.item');for(var i=0;i<all.length;i++){if(nm(all[i])===name)return all[i];}return null;}"
        "A.forEach(function(name){var b=findBtn(name);if(b)reveal(b);});"
        # 3) reveler les labels de section qui precedent un bloc redevenu visible
        "Array.prototype.forEach.call(sb.children,function(c){"
        "if(c.classList&&c.classList.contains('section-label')){var n=c.nextElementSibling,v=false;"
        "while(n&&!(n.classList&&n.classList.contains('section-label'))){if(n.style.display!=='none')v=true;n=n.nextElementSibling;}"
        "if(v)c.style.display='';}});"
        # 4) CACHER (pas supprimer) les panneaux non autorises : on garde le CSS/JS
        #    partage dans le DOM, sinon des pages autorisees (ex: Jailbreak) perdent
        #    leur style. + ouvrir l'onglet autorise par defaut.
        "document.querySelectorAll('.form-section').forEach(function(s){var id=s.id||'';if(id.indexOf('form-')===0&&!ok[id.slice(5)])s.style.display='none';});"
        "for(var di=0;di<A.length;di++){var db=findBtn(A[di]);if(db){db.click();break;}}"
        "}"
        "if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',run);}else{run();}"
        "})();</script>"
    )


def _get_all_roles():
    """Retourne la liste unifiee des roles (defauts + custom). Source unique
    de verite pour le tableau ET le dropdown 'Ajouter un utilisateur'."""
    role_defs = _load_role_definitions()
    default_roles = [
        ("owner",   "Owner",   "Toutes permissions, sans restriction",                                                     "#3b82f6"),
        ("admin",   "Admin",   "Accès complet à toutes les pages + gestion des utilisateurs / VAs / paiements",            "#3b82f6"),
        ("va",      "VA",      "Upload contenu, planning posts/stories, gestion des comptes Insta assignés à son identité", "#a855f7"),
        ("chatter", "Chatter", "Vue revenus + planning SFS + historique conversations. Pas d'upload, pas de gestion VAs",  "#fbbf24"),
        ("creator", "Creator", "Modèle (OF/MyM) — vue de ses propres revenus, dashboard perso, validation contenu",         "#10b981"),
        ("sfs",     "SFS Manager", "Création / édition / validation des SFS uniquement (calendrier SFS + preuves AVANT/APRÈS)", "#ec4899"),
    ]
    out = []
    for key, name, desc, color in default_roles:
        custom = role_defs.get(key, {}) if isinstance(role_defs, dict) else {}
        out.append({
            "key": key,
            "name": custom.get("name", name),
            "desc": custom.get("description", desc),
            "color": color,
            "enabled": custom.get("enabled", True),
            "default": True,
        })
    # Roles custom ajoutes par l user (non dans la liste default)
    if isinstance(role_defs, dict):
        for key, info in role_defs.items():
            if any(r["key"] == key for r in out):
                continue
            if not isinstance(info, dict):
                continue
            out.append({
                "key": key,
                "name": info.get("name", key.title()),
                "desc": info.get("description", ""),
                "color": info.get("color", "#6b7280"),
                "enabled": info.get("enabled", True),
                "default": False,
            })
    return out


