    def _save_image_or_video_with_pair(form_files, form_text, subdir_name, allow_exts):
        identity = form_text.get("identity", "").strip().lower()
        if not identity or identity not in _list_identities():
            return _error("Identité invalide")
        photo = form_files.get("photo") or form_files.get("video")
        if not photo or not photo.filename:
            return _error("Fichier manquant")
        ext = os.path.splitext(photo.filename)[1].lower()
        if ext not in allow_exts:
            return _error(f"Format non supporté ({ext})")
        target_dir = IDENTITIES_DIR / identity / subdir_name
        target_dir.mkdir(parents=True, exist_ok=True)
        target = target_dir / _safe_upload_name(photo.filename)
        if target.exists():
            return _error(f"Fichier {photo.filename} existe déjà")
        photo.save(str(target))
        stem = target.stem
        caption = form_text.get("caption", "").strip()
        description = form_text.get("description", "").strip()
        if caption:
            (target_dir / f"{stem}.txt").write_text(caption, encoding="utf-8")
        if description:
            (target_dir / f"{stem}.desc.txt").write_text(description, encoding="utf-8")
        example = form_files.get("example")
        if example and example.filename:
            ex_ext = os.path.splitext(example.filename)[1].lower()
            if ex_ext in allow_exts:
                ex_target = target_dir / f"{stem}.example{ex_ext}"
                example.save(str(ex_target))
        session["last_upload_identity"] = identity  # le Cloud s'ouvrira sur cette identité
        return _success(f"✓ Ajouté à {identity}/{subdir_name} : {photo.filename}")

    @app.route("/upload/reel", methods=["POST"])
    def upload_reel():
        if not is_auth():
            return redirect("/")
        # Reuse logic but with VIDEO_EXTS
        return _save_image_or_video_with_pair(
            {"photo": request.files.get("video"), "example": request.files.get("example")},
            request.form, _vault_subdir("videos"), VIDEO_EXTS,
        )

    def _save_many_videos(field: str, subdir: str):
        """Enregistre TOUS les fichiers du champ, pas seulement le premier.

        L'interface envoie déjà une requête par fichier, mais un envoi groupé
        (JS coupé, POST direct) ne gardait que le 1er fichier EN SILENCE.
        """
        files = [f for f in request.files.getlist(field) if f and f.filename]
        if not files:
            return _save_image_or_video_with_pair(
                {"photo": None, "example": request.files.get("example")},
                request.form, subdir, VIDEO_EXTS,
            )
        # Un ZIP = toutes les vidéos qu'il contient (envoyer 50 rushs un par un
        # est interminable). On extrait NOUS-MÊMES : chaque entrée est validée
        # (extension + nom sûr), donc une archive piégée ne peut pas écrire
        # hors du dossier de l'identité.
        zips = [f for f in files if os.path.splitext(f.filename)[1].lower() == ".zip"]
        if zips:
            import zipfile as _zip
            ident = (request.form.get("identity") or "").strip().lower()
            if ident not in _list_identities():
                return _error("Identité invalide")
            target_dir = IDENTITIES_DIR / ident / subdir
            target_dir.mkdir(parents=True, exist_ok=True)
            n_ok = n_skip = 0
            for z in zips:
                try:
                    with _zip.ZipFile(z.stream._file if hasattr(z.stream, "_file") else z.stream) as arch:
                        for info in arch.infolist():
                            if info.is_dir() or info.file_size <= 0:
                                continue
                            nom = _safe_upload_name(info.filename)
                            if os.path.splitext(nom)[1].lower() not in VIDEO_EXTS:
                                n_skip += 1
                                continue
                            if info.file_size > 15 * 1024 * 1024 * 1024:   # garde-fou
                                n_skip += 1
                                continue
                            dst = target_dir / nom
                            k = 2
                            while dst.exists():        # jamais d'écrasement
                                dst = target_dir / f"{Path(nom).stem}_{k}{Path(nom).suffix}"
                                k += 1
                            with arch.open(info) as src, dst.open("wb") as out:
                                _sh_copy = __import__("shutil").copyfileobj
                                _sh_copy(src, out, 1 << 20)
                            # Description du formulaire : posee sur CHAQUE
                            # video du zip (sinon un envoi .zip perdait le
                            # texte en silence).
                            _dz = (request.form.get("description") or "").strip()[:1000]
                            if _dz:
                                try:
                                    dst.with_suffix(".desc.txt").write_text(
                                        _dz, encoding="utf-8")
                                except Exception:
                                    pass
                            n_ok += 1
                except Exception as e:
                    return _error(f"ZIP illisible : {e}")
            others = [f for f in files if f not in zips]
            for f in others:
                _save_image_or_video_with_pair(
                    {"photo": f, "example": None}, request.form, subdir, VIDEO_EXTS)
                n_ok += 1
            if not n_ok:
                return _error("Aucune vidéo dans le ZIP (formats acceptés : "
                              + ", ".join(sorted(VIDEO_EXTS)) + ")")
            return _success(f"✓ {n_ok} vidéo(s) importée(s) depuis le ZIP"
                            + (f" · {n_skip} fichier(s) ignoré(s)" if n_skip else ""))
        last = None
        for f in files:
            last = _save_image_or_video_with_pair(
                {"photo": f, "example": None},
                request.form, subdir, VIDEO_EXTS,
            )
        return last

