    @app.route("/noctus/identities")
    def noctus_identities():
        """Liste des models pour la modale « Appliquer à d'autres models » :
        nom + photo de profil (1re image de profile_pics/) + nombre de vidéos
        brutes (utile : 0 brute = le template partira sans remplacement)."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False}), 401
        # HEIC en dernier recours : le serveur ne sait pas le miniaturiser et le
        # navigateur ne l'affiche pas -> on préfère toujours jpg/png/webp.
        img_pref = {".jpg": 0, ".jpeg": 0, ".png": 1, ".webp": 2, ".gif": 3, ".heic": 9}

        def _first_img(d):
            if not d.exists():
                return None
            cands = sorted(
                (p for p in d.iterdir()
                 if p.is_file() and p.suffix.lower() in img_pref
                 and ".example" not in p.name),
                key=lambda p: (img_pref[p.suffix.lower()], p.name))
            return cands[0].name if cands else None

        def _first_vid(d):
            if not d.exists():
                return None
            for p in sorted(d.iterdir()):
                if (p.is_file() and p.suffix.lower() in VIDEO_EXTS
                        and ".example" not in p.name):
                    return p.name
            return None

        out = []
        for ident in _list_content_identities():
            # MÊME visage que la barre latérale de la Bibliothèque : avatar
            # uploadé, sinon photo MyPuls de la créatrice. À défaut, une photo
            # de sa Bibliothèque (Photos profil, post, story), sinon la
            # miniature d'un reel. En tout dernier : pastille à initiale.
            pp = None
            try:
                pp = _identity_avatar_url(ident) or None
            except Exception:
                pp = None
            base = IDENTITIES_DIR / ident
            if not pp:
                for sub in ("profile_pics", "posts", "stories", "storyctas"):
                    name = _first_img(base / sub)
                    if name:
                        pp = f"/cloud/thumb/{ident}/{sub}/{_url_nom(name)}"
                        break
            if not pp:
                for sub in ("videos", "templates", "brutes"):
                    name = _first_vid(base / sub)
                    if name:
                        pp = f"/cloud/thumb/{ident}/{sub}/{_url_nom(name)}"
                        break
            # Un compteur de stock DISPONIBLE : les desactivees n en font pas
            # partie, sinon il annonce une matiere qui ne partira jamais.
            nb = len(_off.lister(IDENTITIES_DIR / ident / "brutes",
                                 extensions=VIDEO_EXTS))
            out.append({"name": ident, "pp": pp, "brutes": nb})
        return jsonify({"ok": True, "identities": out})

    @app.route("/noctus/montage_apply", methods=["POST"])
    def noctus_montage_apply():
        """Applique un TEMPLATE à d'autres models : copie la vidéo (+ caption,
        description, exemple s'ils existent) dans identities/<model>/templates/
        et y écrit le MÊME brouillon de montage (captions + style + trait de
        coupe). Chaque model garde ses propres brutes -> même montage, contenus
        différents à la génération."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        parsed = _parse_file_id(request.form.get("file_id", ""))
        if not parsed:
            return jsonify({"ok": False, "error": "vidéo introuvable"})
        src_dir, src = parsed
        src_ident = src_dir.parent.name
        idents = set(_list_identities())
        targets = [t.strip().lower() for t in (request.form.get("targets") or "").split(",")]
        targets = [t for t in dict.fromkeys(targets)          # dédoublonné, ordre gardé
                   if t and t in idents and t != src_ident][:40]
        if not targets:
            return jsonify({"ok": False, "error": "choisis au moins une model"})
        import shutil as _sh
        draft = {
            "segments": request.form.get("segments") or "[]",
            "font": (request.form.get("font") or "Strong").strip(),
            "style": request.form.get("style") or "{}",
        }
        try:
            _cut = float(request.form.get("cut_at") or 0)
            if _cut > 0:
                draft["cut_at"] = round(_cut, 3)
        except (TypeError, ValueError):
            pass
        if (request.form.get("va_ready") or "") in ("1", "true"):
            draft["va_ready"] = True
        # Partage depuis la GALERIE (bouton Partager, pas d'éditeur ouvert) :
        # aucun état posté -> on reprend le brouillon ENREGISTRÉ tel quel.
        if request.form.get("segments") is None:
            try:
                import json as _js2
                _saved = _js2.loads((src_dir / f"{src.stem}.montage.json").read_text(encoding="utf-8"))
                if isinstance(_saved, dict) and _saved.get("segments") is not None:
                    draft = _saved
            except Exception:
                pass
        done, errs = [], []
        src_size = src.stat().st_size
        for t in targets:
            try:
                dstdir = IDENTITIES_DIR / t / "templates"
                dstdir.mkdir(parents=True, exist_ok=True)
                dst = dstdir / src.name
                # Collision de nom : même taille = même vidéo (on met juste le
                # brouillon à jour) ; taille différente = un AUTRE template
                # porte ce nom chez la cible -> on suffixe au lieu d'écraser.
                if dst.exists() and dst.stat().st_size != src_size:
                    k = 2
                    while True:
                        cand = dstdir / f"{src.stem}_{k}{src.suffix}"
                        if not cand.exists() or cand.stat().st_size == src_size:
                            dst = cand
                            break
                        k += 1
                if not (dst.exists() and dst.stat().st_size == src_size):
                    _sh.copy2(str(src), str(dst))
                # annexes : caption (.txt), description (.desc.txt), exemple
                for suffix in (".txt", ".desc.txt"):
                    sp = src_dir / (src.stem + suffix)
                    if sp.exists():
                        _sh.copy2(str(sp), str(dstdir / (dst.stem + suffix)))
                for ex in src_dir.glob(src.stem + ".example.*"):
                    _sh.copy2(str(ex), str(dstdir / (dst.stem + ex.name[len(src.stem):])))
                if not safe_json.write(dstdir / f"{dst.stem}.montage.json", draft, indent=None):
                    raise OSError("écriture du brouillon impossible")
                done.append(t)
            except Exception as e:
                errs.append(f"{t} : {e}")
        return jsonify({"ok": bool(done), "done": done, "errors": errs})

    @app.route("/noctus/montage_load")
    def noctus_montage_load():
        """Recharge le brouillon du montage d'un reel (captions + style)."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False}), 401
        parsed = _parse_file_id(request.args.get("file_id", ""))
        if not parsed:
            return jsonify({"ok": False})
        target_dir, src = parsed
        p = target_dir / f"{src.stem}.montage.json"
        dsc = ""
        try:
            _dp = target_dir / f"{src.stem}.desc.txt"
            if _dp.exists():
                dsc = _dp.read_text(encoding="utf-8").strip()
        except Exception:
            dsc = ""
        if not p.exists():
            # Aucun brouillon enregistre : on propose l'analyse automatique
            # faite a l'import, si elle a abouti. Elle reste une PROPOSITION —
            # rien n'est applique tant que l'editeur n'a pas ete enregistre.
            _sugg = None
            try:
                _ap = target_dir / f"{src.stem}.analyse.json"
                if _ap.exists():
                    import json as _js0
                    _sugg = _js0.loads(_ap.read_text(encoding="utf-8"))
            except Exception:
                _sugg = None
            return jsonify({"ok": True, "draft": None, "desc": dsc,
                            "analyse": _sugg})
        import json as _js
        try:
            return jsonify({"ok": True, "draft": _js.loads(p.read_text(encoding="utf-8")),
                            "desc": dsc})
        except Exception:
            return jsonify({"ok": True, "draft": None, "desc": dsc})

    @app.route("/noctus/montage_log")
    def noctus_montage_log():
        """Renvoie la fin du log du pipeline (_run.log) -> diagnostiquer un échec."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False}), 401
        import noctus_web
        model = noctus_web._safe(request.args.get("model") or "")
        if not model:
            return jsonify({"ok": False, "log": ""})
        logf = noctus_web._models_dir() / model / "_run.log"
        try:
            if logf.exists():
                txt = logf.read_text(encoding="utf-8", errors="ignore")
                return jsonify({"ok": True, "log": txt[-2500:]})
        except Exception:
            pass
        return jsonify({"ok": True, "log": ""})

    @app.route("/noctus/montage_zip")
    def noctus_montage_zip():
        """Zippe toutes les variantes générées d'un modèle -> 1 seul téléchargement
        (bulk). Évite le blocage navigateur des téléchargements multiples."""
        from flask import send_file
        if not is_auth():
            return redirect("/")
        import noctus_web, io as _io, zipfile as _zip
        model = noctus_web._safe(request.args.get("model") or "")
        if not model:
            return "", 404
        paths = noctus_web.output_paths(model)
        if not paths:
            return "", 404
        buf = _io.BytesIO()
        with _zip.ZipFile(buf, "w", _zip.ZIP_STORED) as z:   # mp4 déjà compressé -> pas de recompression
            seen = set()
            for p in paths:
                name = p.name
                if name in seen:            # noms uniques dans le zip
                    name = f"{p.parent.name}_{name}"
                seen.add(name)
                try:
                    z.write(str(p), arcname=name)
                except Exception:
                    pass
        buf.seek(0)
        return send_file(buf, mimetype="application/zip", as_attachment=True,
                         download_name=f"variantes_{model[:24]}.zip")

    @app.route("/noctus/montage_gen", methods=["POST"])
    def noctus_montage_gen():
        """Génère les variations Noctus DIRECTEMENT depuis un reel de la Bibliothèque
        (réutilise sa vidéo + sa caption). Génération à la demande."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        import noctus_web
        import shutil as _sh
        import re as _re
        if not noctus_web.setup_ok():
            return jsonify({"ok": False, "error": "Setup vidéo incomplet (Node/ffmpeg) — va dans « Création de vidéos »"})
        parsed = _parse_file_id(request.form.get("file_id", ""))
        if not parsed:
            return jsonify({"ok": False, "error": "reel introuvable"})
        target_dir, src = parsed
        if src.suffix.lower() not in VIDEO_EXTS:
            return jsonify({"ok": False, "error": "ce n'est pas une vidéo"})
        identity = target_dir.parent.name  # IDENTITIES_DIR/<identity>/videos
        if identity not in _list_identities():   # bloque tout file_id qui sortirait de IDENTITIES_DIR
            return jsonify({"ok": False, "error": "identité invalide"})
        stem = _re.sub(r"[^a-zA-Z0-9_\-]", "", src.stem)[:28]
        model = _re.sub(r"[^a-zA-Z0-9_\-]", "", f"reel-{identity}-{stem}")[:40]
        # L'identifiant du modèle ne dépend que du reel : deux générations
        # lancées en même temps (double-clic, deux onglets) partageraient le
        # même dossier et la seconde effacerait input/ et output/ de la
        # première EN PLEIN RENDU, en tuant son process. On refuse plutôt.
        # On ne regarde ni _status.json (écrit par le runner Node avec un
        # délai : deux clics rapprochés passeraient tous les deux au travers),
        # ni _PROCS SEUL : cette table n'est remplie qu'au LANCEMENT de Node, et
        # l'assemblage qui le précède dure des minutes (un ffmpeg par variante).
        # Pendant tout ce temps elle restait vide, un second clic passait le
        # garde et vidait input/ et output/ sous les pieds du premier. La place
        # est donc RÉSERVÉE ici, AVANT l'assemblage.
        _mid_gen = noctus_web._safe(model)
        if not _montage_gen_reserver(_mid_gen):
            return jsonify({"ok": False, "error":
                            "une génération est déjà en cours sur ce reel — "
                            "attends qu'elle finisse (ou clique sur ✋ Stop)"})
        try:
            # Chaque reel généré laissait son dossier models/reel-… sur le disque
            # pour toujours ; avec l'assemblage il contient une vidéo PAR VARIANTE.
            noctus_web.purge_old_models("reel-")
            inp = noctus_web._models_dir() / model / "input"
            inp.mkdir(parents=True, exist_ok=True)
            for f in inp.glob("*"):
                try:
                    f.unlink()
                except Exception:
                    pass
            # Nettoie les sorties précédentes -> UNE seule vidéo à chaque génération
            # (sinon les générations s'accumulent dans output/ et on voit N versions).
            _outdir = noctus_web._models_dir() / model / "output"
            try:
                if _outdir.exists():
                    _sh.rmtree(str(_outdir), ignore_errors=True)
            except Exception:
                pass
            font = (request.form.get("font") or "Strong").strip() or "Strong"
            folders = [f for f in (request.form.get("folders") or "").split(",") if f in noctus_web.V_FOLDERS] or ["V1", "V2", "V3"]
            # ASSEMBLAGE : si un point de coupe est demandé et que l'identité a des
            # vidéos brutes, chaque variante part d'un montage (brute + template) au
            # lieu du template seul. Sinon _prepare_inputs recopie la source.
            _cut = request.form.get("cut_at")
            _targets, _fmap, _gaps = noctus_web._prepare_inputs(
                src, inp, {"cut_at": _cut} if _cut else {}, folders,
                IDENTITIES_DIR / identity / "brutes")
            label = ("m_" + model)[:40]
            def _hms(v):
                # garde les décimales (millisecondes) -> timing précis au centième
                try:
                    sec = max(0.0, float(v))
                except Exception:
                    sec = 0.0
                h = int(sec // 3600)
                m = int((sec % 3600) // 60)
                s = sec - h * 3600 - m * 60
                return f"{h:02d}:{m:02d}:{s:06.3f}"

            # Style texte GLOBAL (réglages CapCut) appliqué à toutes les captions.
            # Nettoyé ici ; le moteur (renderCaptionsPng) re-valide de toute façon.
            def _clean_style(raw):
                out = {}
                if not isinstance(raw, dict):
                    return out
                try:
                    if raw.get("size") is not None:
                        out["size"] = max(16, min(160, int(float(raw["size"]))))
                except Exception:
                    pass
                c = raw.get("color")
                if isinstance(c, str) and re.match(r"^#[0-9a-fA-F]{3,8}$", c):
                    out["color"] = c
                if raw.get("align") in ("left", "center", "right"):
                    out["align"] = raw["align"]
                if raw.get("case") in ("upper", "lower", "title", "none"):
                    out["case"] = raw["case"]
                for k in ("bold", "italic", "underline"):
                    if k in raw:
                        out[k] = bool(raw[k])
                if raw.get("box") in (True, "1", "true"):
                    out["box"] = True
                bc = raw.get("boxColor")
                if isinstance(bc, str) and re.match(r"^#[0-9a-fA-F]{3,8}$", bc):
                    out["boxColor"] = bc
                if raw.get("effect") in ("shadow", "neon"):
                    out["effect"] = raw["effect"]
                return out
            _style = {}
            try:
                import json as _js
                _style = _clean_style(_js.loads(request.form.get("style") or "{}"))
            except Exception:
                _style = {}

            # Plusieurs captions chronométrées (liste + frise) -> champ 'segments' JSON.
            # Chaque segment = {text, start, end} en secondes (start/end null = toute la vidéo).
            segments = []
            seg_raw = request.form.get("segments")
            if seg_raw:
                import json as _json
                try:
                    arr = _json.loads(seg_raw)
                except Exception:
                    arr = []
                if isinstance(arr, list):
                    for it in arr[:40]:  # garde-fou : 40 captions max
                        if not isinstance(it, dict):
                            continue
                        txt = (it.get("text") or "").strip()
                        if not txt:
                            continue
                        st = it.get("start")
                        en = it.get("end")
                        if st is None or en is None:
                            start, end = "00:00:00", "99:99:99"
                        else:
                            start, end = _hms(st), _hms(en)
                        seg = {"start": start, "end": end, "text": txt}
                        seg.update(_style)   # applique le style global à chaque caption
                        for _pk in ("x", "y"):   # position PAR caption (drag éditeur) -> écrase le défaut moteur
                            _pv = it.get(_pk)
                            try:
                                if _pv is not None:
                                    _pf = float(_pv)
                                    if 0.0 <= _pf <= 1.0:
                                        seg[_pk] = round(_pf, 4)
                            except Exception:
                                pass
                        try:                     # largeur de wrap (poignée ↔)
                            _wv = it.get("wrapW")
                            if _wv is not None:
                                _wf = float(_wv)
                                if 0.2 <= _wf <= 0.97:
                                    seg["wrapW"] = round(_wf, 4)
                        except Exception:
                            pass
                        try:                     # interligne (poignée ↕)
                            _lv = it.get("lineSpacing")
                            if _lv is not None:
                                _lf = float(_lv)
                                if 0.9 <= _lf <= 3.0:
                                    seg["lineSpacing"] = round(_lf, 3)
                        except Exception:
                            pass
                        segments.append(seg)

            # Ce qu'il y aura à écrire dans captions.json : une entrée, ou rien.
            _entry = None
            if segments:
                _entry = {"label": label, "font": font, "captions": segments}
            else:
                # rétro-compat : ancien champ 'caption' unique (+ start_s/end_s)
                caption = (request.form.get("caption") or "").strip()
                if caption:
                    s_s = request.form.get("start_s")
                    e_s = request.form.get("end_s")
                    if s_s is not None and e_s is not None:
                        start, end = _hms(s_s), _hms(e_s)
                    else:
                        start, end = "00:00:00", "99:99:99"
                    _entry = {"label": label, "font": font,
                              "captions": [{"start": start, "end": end, "text": caption}]}
            # captions.json est PARTAGÉ avec le « Reel déjà monté » des VA
            # (noctus_web.gen_from_draft) : ici il était lu, modifié puis écrit HORS
            # VERROU, donc deux générations lancées ensemble repartaient du même
            # contenu et la seconde écriture effaçait le label de la première : sa
            # vidéo sortait sans aucun texte. Même verrou que gen_from_draft — un
            # second verrou ne sérialiserait rien du tout.
            with noctus_web._GEN_LOCK:
                caps = [c for c in noctus_web.read_captions()
                        if not (isinstance(c, dict)
                                and (c.get("label") == label
                                     or str(c.get("label", "")).startswith(label + "_s")))]
                if _entry:
                    caps.append(_entry)
                    sel = [label]
                else:
                    if not any(isinstance(c, dict) and c.get("label") == "sans_texte" for c in caps):
                        caps.append({"label": "sans_texte", "font": None, "captions": []})
                    sel = ["sans_texte"]
                # variantes dont le début a été coupé (brute plus courte que la place) :
                # copie DÉCALÉE des captions pour chacune, sinon elles arrivent en retard.
                _cmap = noctus_web.caption_map_for(_entry, _targets, _gaps, caps)
                # Écriture ratée = le moteur ne trouve pas le label et rend la vidéo
                # SANS texte, alors que la page annonce « ok ». On refuse plutôt.
                if not noctus_web.write_captions(caps):
                    return jsonify({"ok": False, "error":
                                    "captions.json non écrit — génération annulée "
                                    "(la vidéo serait sortie sans texte)"})
                proc = noctus_web.run(model, folders, sel, targets=_targets, folder_map=_fmap,
                                      caption_map=_cmap)
            if not proc:
                return jsonify({"ok": False, "error": "lancement impossible"})
            return jsonify({"ok": True, "model": model, "identity": identity,
                            "assembled": bool(_fmap)})
        finally:
            # Sans ce retrait, un assemblage qui échoue (ffmpeg, disque plein)
            # laisserait le reel bloqué « en cours » jusqu'au redémarrage du bot.
            _montage_gen_liberer(_mid_gen)

    @app.route("/noctus/montage_send", methods=["POST"])
    def noctus_montage_send():
        """Envoie une variation générée vers Discord (salon banger-{identité})."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        import noctus_web
        identity = (request.form.get("identity") or "").strip().lower()
        model = noctus_web._safe(request.form.get("model") or "")
        vf = (request.form.get("vf") or "").strip()
        name = (request.form.get("file") or "").strip()
        if identity not in _list_identities():
            return jsonify({"ok": False, "error": "identité inconnue"})
        if vf not in noctus_web.V_FOLDERS or "/" in name or "\\" in name or ".." in name:
            return jsonify({"ok": False, "error": "fichier invalide"})
        base = (noctus_web._models_dir() / model / "output" / vf).resolve()
        p = (base / name).resolve()
        if not str(p).startswith(str(base)) or not p.exists() or not p.is_file():
            return jsonify({"ok": False, "error": "fichier introuvable"})
        # Description optionnelle (captions) : posée en sidecar <stem>.desc.txt,
        # le format d'envoi banger la lit déjà (message DESCRIPTION après la vidéo).
        desc_txt = (request.form.get("desc") or "").strip()[:1000]
        if desc_txt:
            try:
                p.with_suffix(".desc.txt").write_text(desc_txt, encoding="utf-8")
            except Exception:
                pass
        ok, msg, _meta = _send_reel_to_banger_channel(identity, p)
        if ok:
            return jsonify({"ok": True, "channel": msg})
        return jsonify({"ok": False, "error": msg})

    @app.route("/gmsdash/teams")
    def gmsdash_teams():
        """Catégories = les TEAMS GetMySocial (BOYA, KHLOE, marche francais…).
        Via la clé API (pas le cookie de session) -> fiable sur le VPS."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        # AUCUN appel API ici : quand GMS rate-limite (429), le sélecteur restait
        # bloqué sur « Chargement… ». Les noms sont en dur, le nombre de liens
        # vient du cache pré-calculé (0 = pas encore calculé, purement cosmétique).
        out = []
        for tid, name in GMSDASH_TEAMS:
            n = 0
            with _GMSDASH_LOCK:
                for per in ("today", "7", "30", "quinz"):
                    hit = _GMSDASH_MEM.get(f"{tid}|{per}")
                    if hit and (hit.get("payload") or {}).get("links"):
                        n = len(hit["payload"]["links"])
                        break
            out.append({"id": tid, "name": name, "link_count": n})
        return jsonify({"ok": True, "teams": out})

    def _gd_mask(k):
        k = k or ""
        return (k[:12] + "…" + k[-4:]) if len(k) > 18 else (k[:6] + "…") if k else ""

    @app.route("/gmsdash/keys")
    def gmsdash_keys():
        """État MASQUÉ des slots de clés (principale + 4 dédiées) pour le panneau."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False}), 401
        import gms
        return jsonify({"ok": True,
                        "main": _gd_mask(gms.get_api_key()),
                        "pool": [_gd_mask(k) for k in gms.get_dash_keys()]})

    @app.route("/gmsdash/set_keys", methods=["POST"])
    def gmsdash_set_keys():
        """Slots nommés : main + k1..k4. Champ vide = conserver la clé actuelle du
        slot ; « - » dans une clé dédiée = vider ce slot. La principale est testée
        (ping) après remplacement."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        import gms
        cur_pool = gms.get_dash_keys()
        new_pool = []
        for i in range(4):
            v = (request.form.get(f"k{i + 1}") or "").strip()
            if v == "-":
                continue
            if not v:
                if i < len(cur_pool):
                    new_pool.append(cur_pool[i])
                continue
            if not v.startswith("gms_"):
                return jsonify({"ok": False, "error": f"clé dédiée {i + 1} invalide (gms_…)"})
            new_pool.append(v)
        main_v = (request.form.get("main") or "").strip()
        if main_v and main_v != "-":
            if not main_v.startswith("gms_") or len(main_v) < 20:
                return jsonify({"ok": False, "error": "clé principale invalide (gms_…, 20+ caractères)"})
            gms.save_api_key(main_v)
        gms.save_dash_key(chr(10).join(new_pool))
        ping_ok = None
        if main_v and main_v != "-":
            try:
                ping_ok = bool((gms.ping() or {}).get("ok"))
            except Exception:
                ping_ok = False
        return jsonify({"ok": True, "pool_count": len(new_pool), "main_ping": ping_ok})

    @app.route("/gmsdash/set_main_key", methods=["POST"])
    def gmsdash_set_main_key():
        """Remplace la clé PRINCIPALE GetMySocial (report horaire + paie + pages),
        puis la teste immédiatement (ping)."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        import gms
        k = (request.form.get("key") or "").strip()
        if not k.startswith("gms_") or len(k) < 20:
            return jsonify({"ok": False, "error": "clé invalide (gms_…, 20+ caractères)"})
        gms.save_api_key(k)
        try:
            pr = gms.ping() or {}
            return jsonify({"ok": bool(pr.get("ok")),
                            "error": None if pr.get("ok") else f"clé enregistrée mais ping KO : {str(pr.get('error'))[:100]}"})
        except Exception as e:
            return jsonify({"ok": False, "error": f"clé enregistrée, test impossible : {e}"[:140]})

    @app.route("/gmsdash/set_key", methods=["POST"])
    def gmsdash_set_key():
        """Enregistre la clé API DÉDIÉE au dashboard (quota séparé du report/paie).
        À coller depuis GetMySocial > API keys (ex: la clé « claude »)."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        import gms
        import re as _re_k
        raw = (request.form.get("key") or "").strip()
        parts = [x for x in _re_k.split(r"[\s,;]+", raw) if x]
        if not parts or any(not x.startswith("gms_") for x in parts):
            return jsonify({"ok": False, "error": "clé(s) invalide(s) — chaque clé commence par gms_"})
        gms.save_dash_key(chr(10).join(parts))   # une clé par ligne dans la config
        return jsonify({"ok": True, "count": len(parts)})

    @app.route("/gmsdash/data")
    def gmsdash_data():
        """Clics par lien pour UNE catégorie (team) et une période.
        Sert le cache pré-calculé par le démon ; ne calcule à la volée que si le
        cache est vide/périmé (ou si ?force=1)."""
        from flask import jsonify
        team = (request.args.get("team") or "").strip()
        period = (request.args.get("period") or "7").strip()
        force = (request.args.get("force") or "") == "1"
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        if not team:
            return jsonify({"ok": False, "error": "catégorie manquante"})
        if team not in {t[0] for t in GMSDASH_TEAMS}:
            return jsonify({"ok": False, "error": "catégorie inconnue"})
        try:
            return jsonify(_gmsdash_get(team, period, force=force))
        except Exception as e:
            # Toujours du JSON : sinon le front reçoit la page d'erreur HTML de
            # Flask et affiche « <!DOCTYPE ... is not valid JSON ».
            import traceback as _tb
            print("[gmsdash] " + _tb.format_exc(), flush=True)
            return jsonify({"ok": False, "error": f"{type(e).__name__}: {e}"[:200]})

    @app.route("/insta/pp/<handle>")
    def insta_pp(handle):
        """Sert la photo de profil téléchargée en local (data/insta/pp/<handle>.jpg).
        Évite de dépendre des URLs Instagram signées, qui expirent -> plus de comptes
        affichés sans photo. 404 si on n'a pas encore de copie."""
        from flask import send_file, make_response
        if not is_auth():
            return "", 401
        try:
            import insta_scraper as _ig_pp
            p = _ig_pp.local_pp_path(handle)
            if not p:
                # Un 404 sans en-tete de cache etait redemande a CHAQUE rendu, et a
                # chaque reconstruction JS : un compte sans copie locale coutait une
                # requete par affichage, pour rien.
                r404 = make_response("", 404)
                # PAS en text/html : le hook de cache force « no-store » sur
                # tout le HTML (les pages portent des donnees de session), ce
                # qui annulait justement la duree de vie posee ici.
                r404.mimetype = "text/plain"
                r404.headers["Cache-Control"] = "public, max-age=3600"
                return r404
            # La copie locale fait 320x320 — ce que rend Instagram — alors que la
            # pastille affichee mesure 30 a 46 px. Avec ~800 comptes le navigateur
            # gardait 800 bitmaps de 320x320x4 o, soit 328 Mo DECODES : c est ce qui
            # figeait le rendu (la capture d ecran expirait au bout de 30 s). 96 px
            # couvre encore les ecrans 2x. Reduction faite une seule fois, sous le
            # verrou de generation deja en place pour les vignettes.
            petite = THUMB_DIR / "insta_pp96" / (p.stem + ".jpg")
            try:
                if not (_vignette_valide(petite)
                        and petite.stat().st_mtime >= p.stat().st_mtime):
                    with _thumb_gen_lock("insta_pp96/" + p.stem):
                        if not (_vignette_valide(petite)
                                and petite.stat().st_mtime >= p.stat().st_mtime):
                            from PIL import Image as _Im_pp
                            petite.parent.mkdir(parents=True, exist_ok=True)
                            _tmp_pp = petite.with_name(petite.name + ".tmp")
                            with _Im_pp.open(p) as _src_pp:
                                _im_pp = _src_pp.convert("RGB")
                                _im_pp.thumbnail((96, 96), _Im_pp.LANCZOS)
                                _im_pp.save(_tmp_pp, "JPEG", quality=72, optimize=True)
                            os.replace(str(_tmp_pp), str(petite))   # ecriture atomique
            except Exception:
                petite = p        # jamais de compte sans photo : on sert l original
            resp = send_file(str(petite), mimetype="image/jpeg", conditional=True)
            resp.headers["Cache-Control"] = "public, max-age=86400"
            return resp
        except Exception:
            return "", 404

    @app.route("/noctus/montage_approve", methods=["POST"])
    def noctus_montage_approve():
        """Marque un reel « bon pour les VA » : enregistre son brouillon de montage
        (captions + police + style) ET pose va_ready=true dans <stem>.montage.json.
        AUCUNE génération ici — la variante montée est générée À LA DEMANDE quand un VA
        clique « 🎞️ Reel déjà monté » (chaque demande = une variante unique)."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        parsed = _parse_file_id(request.form.get("file_id", ""))
        if not parsed:
            return jsonify({"ok": False, "error": "reel introuvable"})
        target_dir, src = parsed
        import json as _js
        p = target_dir / f"{src.stem}.montage.json"
        draft = {
            "segments": request.form.get("segments") or "[]",
            "font": (request.form.get("font") or "Strong").strip(),
            "style": request.form.get("style") or "{}",
            "va_ready": True,
        }
        # Le POINT DE COUPE doit survivre à l'approbation : sans lui, le reel
        # généré à la demande pour un VA repartirait du template seul, sans la
        # vidéo brute au début. On prend celui du formulaire, sinon celui déjà
        # enregistré par montage_save.
        try:
            _cut = float(request.form.get("cut_at") or 0)
        except (TypeError, ValueError):
            _cut = 0.0
        if _cut <= 0:
            try:
                _old = _js.loads(p.read_text(encoding="utf-8"))
                if isinstance(_old, dict):
                    _cut = float(_old.get("cut_at") or 0)
            except Exception:
                _cut = 0.0
        if _cut > 0:
            draft["cut_at"] = round(_cut, 3)
        try:
            # Ecriture ATOMIQUE : un redemarrage pendant l ecriture
            # laissait un brouillon tronque, et le reel perdait son point
            # de coupe et ses captions sans un message.
            safe_json.write(p, draft, indent=None)
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})
        return jsonify({"ok": True})

    @app.route("/noctus/montage_unapprove", methods=["POST"])
    def noctus_montage_unapprove():
        """Retire un reel du stock VA : enlève va_ready du .montage.json (le brouillon
        reste). Le reel n'est plus proposé au bouton « Reel déjà monté »."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        parsed = _parse_file_id(request.form.get("file_id", ""))
        if not parsed:
            return jsonify({"ok": False, "error": "reel introuvable"})
        target_dir, src = parsed
        p = target_dir / f"{src.stem}.montage.json"
        import json as _js
        # Répondre « ok » sans avoir rien retiré est le pire des deux mondes : le
        # bouton repasse au gris et la carte perd son filigrane, alors que
        # va_ready est TOUJOURS sur le disque — le reel continue de partir aux
        # VA et personne ne le sait. Chaque cas est donc distingué et dit.
        if not p.exists():
            # Pas de brouillon = pas de va_ready : le disque est déjà dans
            # l'état voulu, il n'y a rien à retirer (et rien à cacher).
            return jsonify({"ok": True, "retire": False,
                            "detail": "ce reel ne figurait pas dans le stock VA"})
        try:
            d = _js.loads(p.read_text(encoding="utf-8"))
        except Exception as e:
            return jsonify({"ok": False, "error":
                            f"brouillon illisible ({e}) — le reel PEUT être encore "
                            "proposé aux VA"})
        if not isinstance(d, dict):
            return jsonify({"ok": False, "error":
                            "brouillon inattendu (ce n'est pas un objet) — retrait "
                            "impossible, le reel PEUT être encore proposé aux VA"})
        if d.pop("va_ready", None) is None:
            return jsonify({"ok": True, "retire": False,
                            "detail": "ce reel ne figurait pas dans le stock VA"})
        if not safe_json.write(p, d, indent=None):
            return jsonify({"ok": False, "error":
                            "écriture du brouillon impossible — le reel est TOUJOURS "
                            "proposé aux VA"})
        return jsonify({"ok": True, "retire": True})

    # ================= CAPTIONS (onglet Caption du Reel montage) =============
    # Bibliothèque de textes par identité (data/captions.json). La génération
    # tire UNE brute + UNE caption au hasard et réutilise le moteur montage
    # (noctus_web.gen_from_draft, brute seule : pas de template ni de cut_at,
    # le son de la brute est conservé). Écriture admin-only via le deny-par-
    # défaut du before_request ; lecture gatée sur l'onglet cloudcaptions.
    @app.route("/identity/create", methods=["POST"])
    def identity_create():
        """Crée une identité depuis la Bibliothèque (bouton ＋ des sidebars vault).
        Même structure que la création côté Jailbreak, mais réponse JSON (AJAX,
        pas de redirect). Écriture admin-only via le préfixe /identity/."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        raw_name = (request.form.get("identity_name") or "").strip()
        import re as _re
        safe = _re.sub(r"[^a-z0-9_\-]", "", raw_name.lower())[:30]
        if not safe:
            return jsonify({"ok": False, "error": "Nom invalide (lettres, chiffres, _ ou -)"})
        # Vault PRO : l'identité est créée avec le préfixe technique v2_
        # (jamais affiché) -> invisible de la Bibliothèque, de Discord et des VAs.
        if str(request.form.get("vault2") or "").strip() in ("1", "true", "on"):
            safe = V2_PREFIX + safe[:26]
        if safe in _list_identities():
            return jsonify({"ok": False, "error": f"L'identité {safe} existe déjà"})
        target_dir = IDENTITIES_DIR / safe
        try:
            target_dir.mkdir(parents=True, exist_ok=False)
        except FileExistsError:
            return jsonify({"ok": False, "error": f"L'identité {safe} existe déjà"})
        except Exception as e:
            return jsonify({"ok": False, "error": f"Création échouée : {e}"})
        # Sous-dossiers standards + ceux du Reel montage (créés d'office ici :
        # l'identité est immédiatement utilisable dans toutes les bibliothèques).
        for sub in ("videos", "posts", "stories", "storyctas", "brutes", "templates"):
            (target_dir / sub).mkdir(exist_ok=True)
        warn = ""
        avatar_file = request.files.get("avatar")
        if avatar_file and avatar_file.filename:
            ext = os.path.splitext(avatar_file.filename)[1].lower().lstrip(".")
            if ext in ("png", "jpg", "jpeg", "webp"):
                try:
                    avatar_file.save(str(target_dir / f"avatar.{ext}"))
                except Exception as e:
                    warn = f"avatar non sauvé : {e}"
            else:
                warn = f"avatar refusé (format {ext})"
        _invalidate_all_ttl_cache()   # compteurs/sidebars vault à jour partout
        return jsonify({"ok": True, "identity": safe, "warn": warn})

    @app.route("/identity/avatar_set", methods=["POST"])
    def identity_avatar_set():
        """Change la photo d'une identité (avatar.<ext> dans son dossier)."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        ident = (request.form.get("identity") or "").strip().lower()
        if ident not in _list_identities():
            return jsonify({"ok": False, "error": "identité inconnue"})
        f = request.files.get("avatar")
        if not f or not f.filename:
            return jsonify({"ok": False, "error": "photo manquante"})
        ext = os.path.splitext(f.filename)[1].lower().lstrip(".")
        if ext not in ("png", "jpg", "jpeg", "webp"):
            return jsonify({"ok": False, "error": f"format refusé ({ext})"})
        d = IDENTITIES_DIR / ident
        for old in d.glob("avatar.*"):        # une seule photo à la fois
            try:
                old.unlink()
            except Exception:
                pass
        try:
            f.save(str(d / f"avatar.{ext}"))
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})
        _invalidate_all_ttl_cache()
        return jsonify({"ok": True, "identity": ident})

