    def _ventes_contexte(tx):
        """Taux EUR/USD et commissions REELS, pour que les montants du
        classeur recoupent ceux de la page Paie."""
        try:
            taux = float(mypuls.get_eur_usd_rate()["rate"])
        except Exception:
            taux = 1.14
        comm = {}
        try:
            noms = {(t.get("chatter") or "").strip() for t in (tx or [])}
            for n in noms:
                if n:
                    comm[n] = float(mypuls.get_chatter_meta(n)["commission_pct"])
        except Exception:
            pass
        return comm, taux

    def _a_relire_liste():
        """Les descriptions reprises d'un post et pas encore validees."""
        out = []
        try:
            for d in sorted(IDENTITIES_DIR.iterdir()):
                if not d.is_dir():
                    continue
                for sub in ("templates", "brutes"):
                    dossier = d / sub
                    if not dossier.is_dir():
                        continue
                    for marq in sorted(dossier.glob("*.acheck.txt")):
                        stem = marq.name[:-len(".acheck.txt")]
                        video = next((dossier / (stem + e) for e in VIDEO_EXTS
                                      if (dossier / (stem + e)).exists()), None)
                        if video is None:
                            continue          # video partie : marqueur orphelin
                        desc = ""
                        dp = dossier / (stem + ".desc.txt")
                        try:
                            desc = dp.read_text(encoding="utf-8").strip()
                        except Exception:
                            pass
                        source = ""
                        try:
                            lignes = marq.read_text(encoding="utf-8").splitlines()
                            source = lignes[1].strip() if len(lignes) > 1 else ""
                        except Exception:
                            pass
                        # Ce que l'analyse automatique a trouve : la caption
                        # incrustee lue a l'image, et l'instant ou le montage
                        # se separe de l'accroche.
                        captions, coupe = [], None
                        try:
                            ap = dossier / (stem + ".analyse.json")
                            if ap.exists():
                                import json as _js1
                                a = _js1.loads(ap.read_text(encoding="utf-8"))
                                captions = [str(c.get("text") or "").strip()
                                            for c in (a.get("captions") or [])
                                            if str(c.get("text") or "").strip()]
                                coupe = a.get("cut_at")
                        except Exception:
                            pass
                        out.append({"identity": d.name, "sub": sub, "stem": stem,
                                    "fichier": video.name, "desc": desc,
                                    "source": source, "captions": captions,
                                    "coupe": coupe,
                                    "ts": int(video.stat().st_mtime)})
        except Exception:
            pass
        out.sort(key=lambda r: -r["ts"])
        return out

