    @app.route("/a-relire/valider", methods=["POST"])
    def page_a_relire_valider():
        """Valide (ou vide) une description reprise, et retire le marqueur."""
        if not is_auth():
            return redirect("/")
        ident = (request.form.get("identity") or "").strip().lower()
        sub = (request.form.get("sub") or "").strip().lower()
        stem = (request.form.get("stem") or "").strip()
        action = (request.form.get("action") or "ok").strip()
        # Aucun chemin compose depuis le formulaire : identite et dossier sont
        # verifies, et le nom de fichier ne peut pas remonter l'arborescence.
        if sub not in ("templates", "brutes") or ident not in _list_identities()                 or not stem or "/" in stem or "\\" in stem or ".." in stem:
            return redirect("/a-relire")
        dossier = IDENTITIES_DIR / ident / sub
        dp = dossier / (stem + ".desc.txt")
        try:
            if action == "vider":
                dp.unlink(missing_ok=True)
            else:
                texte = (request.form.get("desc") or "").strip()[:2000]
                if texte:
                    dp.write_text(texte, encoding="utf-8")
                else:
                    dp.unlink(missing_ok=True)
        except Exception:
            pass
        try:
            (dossier / (stem + ".acheck.txt")).unlink(missing_ok=True)
        except Exception:
            pass
        return redirect("/a-relire")

    RIG_TOKEN_FILE = DATA_DIR / "rig_token.json"

    def _rig_token_attendu() -> str:
        """Le jeton partage : l'environnement d'abord, le fichier ensuite.

        L'environnement garde la priorite pour ne rien changer aux
        installations qui le definissent deja. Le fichier existe parce que
        poser une variable sur le VPS demande un acces SSH — sans lui, la
        chaine restait inerte faute d'une ligne a ecrire.
        """
        import os as _os
        v = (_os.environ.get("RIG_API_TOKEN") or "").strip()
        if v:
            return v
        try:
            return str((safe_json.load(RIG_TOKEN_FILE, default={}) or {})
                       .get("token") or "").strip()
        except Exception:
            return ""

    @app.route("/rig-jeton", methods=["GET", "POST"])
    def rig_jeton_page():
        """Voir, creer ou remplacer le jeton du poste."""
        import os as _os
        if not is_auth() or not _is_admin():
            return redirect("/")
        msg = ""
        if request.method == "POST":
            import secrets as _sec
            # Deux sens possibles, et le second compte autant que le premier :
            # coller une valeur deja posee sur la machine du telephone evite
            # d'avoir a la recopier a la main dans l'autre sens.
            colle = (request.form.get("token") or "").strip()
            if colle:
                if len(colle) < 16:
                    msg = ("<p style='color:#b45309'>Trop court — un jeton doit "
                           "faire au moins 16 caracteres.</p>")
                else:
                    safe_json.write(RIG_TOKEN_FILE, {"token": colle[:200]}, indent=2)
                    msg = ("<p style='color:#166534'>Jeton enregistre. Il doit "
                           "etre identique sur la machine du telephone.</p>")
            else:
                safe_json.write(RIG_TOKEN_FILE,
                                {"token": _sec.token_urlsafe(24)}, indent=2)
                msg = ("<p style='color:#166534'>Jeton cree. Recopie-le sur la "
                       "machine du telephone.</p>")
        actuel = _rig_token_attendu()
        par_env = bool(_os.environ.get("RIG_API_TOKEN"))

        if actuel:
            bloc = ("<p><b>Actuel :</b> <code style='background:#f2f2f7;"
                    "padding:3px 8px;border-radius:6px'>"
                    + html_escape(actuel) + "</code>"
                    + (" <span style='color:#666;font-size:12px'>(pose par "
                       "l'environnement du serveur)</span>" if par_env else "")
                    + "</p>")
        else:
            bloc = ("<p style='color:#b45309'><b>Aucun jeton</b> — l'API repond "
                    "503 et rien ne peut fonctionner.</p>")

        form = ("" if par_env else
                "<form method='POST' style='margin-top:16px;display:flex;"
                "gap:9px;flex-wrap:wrap;align-items:center'>"
                "<input type='text' name='token' placeholder='coller un jeton "
                "existant (facultatif)' style='flex:1;min-width:230px;padding:9px 12px;"
                "border:1px solid #d1d5db;border-radius:9px;font:inherit;"
                "font-size:13px'>"
                "<button style='padding:9px 16px;background:#007aff;border:0;"
                "color:#fff;border-radius:9px;font:inherit;font-weight:600;"
                "cursor:pointer'>Enregistrer</button></form>"
                "<p style='color:#666;font-size:12.5px;margin-top:7px'>"
                "Champ vide : un jeton est cree ici. Champ rempli : c'est celui "
                "de la machine du telephone qui est repris.</p>")

        return ("<div style=\"font:14px/1.6 -apple-system,system-ui,sans-serif;"
                "padding:26px;max-width:620px;margin:40px auto;background:#fff;"
                "color:#1c1c1e;border:1px solid #e5e7eb;border-radius:14px\">"
                "<h2 style='margin:0 0 10px'>Jeton du poste</h2>"
                "<p style='color:#666'>Il autorise la machine ou l'iPhone est "
                "branche a venir chercher du travail. La meme valeur doit se "
                "trouver des deux cotes.</p>"
                + msg + bloc + form +
                "<h3 style='margin:22px 0 6px;font-size:14px'>Sur la machine du "
                "telephone</h3>"
                "<p style='color:#666;font-size:13px'>Colle ceci dans "
                "<code>secrets.json</code>, a la racine du projet :</p>"
                "<pre style='background:#f2f2f7;padding:12px;border-radius:9px;"
                "font-size:12.5px;overflow-x:auto'>"
                + html_escape(GABARIT_JETON % (actuel or "…")) + "</pre>"
                "<p style='margin-top:18px'><a href='/?tab=remote'>Retour a "
                "Remote</a></p></div>")

    def _rig_ok():
        """Le jeton partage. 503 tant qu'il n'est pas configure, 403 s'il ne
        correspond pas : une API muette vaut mieux qu'une API ouverte."""
        attendu = _rig_token_attendu()
        if not attendu:
            return 503
        donne = (request.headers.get("X-Rig-Token")
                 or request.args.get("token") or "").strip()
        return 200 if donne and donne == attendu else 403

    @app.route("/api/rig/media")
    def rig_media():
        """Les medias d'une identite, pour le poste qui pilote le telephone."""
        from flask import jsonify
        code = _rig_ok()
        if code != 200:
            return jsonify({"ok": False, "error": "jeton"}), code

        subdir = (request.args.get("subdir") or "videos").strip().lower()
        if subdir not in CLOUD_SUBDIRS:
            return jsonify({"ok": False, "error": "sous-dossier inconnu"}), 404
        identites = _list_identities()
        demandee = (request.args.get("identity") or "").strip().lower()
        if demandee:
            if demandee not in identites:
                return jsonify({"ok": False, "error": "identite inconnue"}), 404
            cibles = [demandee]
        else:
            cibles = list(identites)

        # « Ne jamais ecarter en silence » : ce qui n'est pas rendu est
        # compte ET motive, sinon un media manquant reste inexplicable.
        items, ecartes = [], []
        exts = VIDEO_EXTS | IMAGE_EXTS
        for ident in cibles:
            dossier = IDENTITIES_DIR / ident / subdir
            if not dossier.is_dir():
                continue
            for f in sorted(dossier.iterdir()):
                if not f.is_file():
                    continue
                if f.suffix.lower() not in exts:
                    ecartes.append({"fichier": f.name, "identite": ident,
                                    "motif": "extension non geree"})
                    continue
                try:
                    taille = f.stat().st_size
                except Exception:
                    ecartes.append({"fichier": f.name, "identite": ident,
                                    "motif": "illisible"})
                    continue
                if taille <= 0:
                    ecartes.append({"fichier": f.name, "identite": ident,
                                    "motif": "fichier vide"})
                    continue
                # DESACTIVEE : ce que le rig recoit finit PUBLIE sur
                # Instagram. Une brute qui porte deja une caption incrustee
                # ne doit pas y arriver — c'est plus grave qu'un envoi a un
                # VA, qui aurait au moins pu s'en apercevoir avant de poster.
                if _off.est_desactivee(f):
                    ecartes.append({"fichier": f.name, "identite": ident,
                                    "motif": "désactivée (caption déjà incrustée)"})
                    continue
                # La description voisine part avec le media : le rig en a
                # besoin pour legender la publication.
                desc = ""
                try:
                    dp = f.with_suffix(".desc.txt")
                    if dp.exists():
                        desc = dp.read_text(encoding="utf-8").strip()[:2000]
                except Exception:
                    pass
                items.append({
                    "identite": ident, "subdir": subdir, "fichier": f.name,
                    "taille": taille, "modifie": int(f.stat().st_mtime),
                    "description": desc,
                    "url": "/api/rig/file/%s/%s/%s" % (ident, subdir, f.name),
                })
        return jsonify({"ok": True, "items": items, "identites": list(identites),
                        "nb_ecartes": len(ecartes), "ecartes": ecartes[:50]})

    RIG_FILE = DATA_DIR / "rig_file_attente.json"

    def _rig_file_lire():
        d = safe_json.load(RIG_FILE, default={}) or {}
        return d if isinstance(d, dict) else {}

    RIG_JOBS = DATA_DIR / "rig_jobs.json"

    def _jobs_lire():
        d = safe_json.load(RIG_JOBS, default={}) or {}
        if not isinstance(d, dict):
            d = {}
        d.setdefault("jobs", [])
        d.setdefault("battement", 0)
        return d

    @app.route("/api/rig/jobs", methods=["GET", "POST"])
    def rig_jobs():
        """Lit la file, ou y inscrit un travail.

        En POST, l'appelant est le SITE (session ouverte) ; en GET, ce peut
        etre le poste (jeton). Les deux voies sont donc acceptees, mais
        jamais confondues : inscrire un travail demande une session.
        """
        from flask import jsonify
        if request.method == "POST":
            if not is_auth():
                return jsonify({"ok": False, "error": "unauth"}), 401
            d = _jobs_lire()
            corps = request.get_json(force=True, silent=True) or {}
            genre = (corps.get("type") or "").strip()[:40]
            if genre not in ("cycle", "etape", "scenario", "geste",
                             "enregistrer"):
                return jsonify({"ok": False, "error": "type inconnu"}), 400
            if genre == "enregistrer":
                etapes = corps.get("etapes")
                if not isinstance(etapes, list) or not etapes:
                    return jsonify({"ok": False,
                                    "error": "aucune etape a enregistrer"}), 400
                if len(etapes) > 200:
                    return jsonify({"ok": False,
                                    "error": "trop d etapes (max 200)"}), 400
            # Un cycle sans categorie va jusqu'a la sixieme etape puis
            # echoue : l'etape des medias ne sait pas quoi choisir. Autant
            # le refuser tout de suite que de creer un compte pour rien.
            if genre == "scenario" and not (corps.get("scenario") or "").strip():
                return jsonify({"ok": False,
                                "error": "aucun scenario choisi"}), 400
            if genre == "cycle" and not (corps.get("categorie") or "").strip():
                return jsonify({"ok": False,
                                "error": "categorie obligatoire pour un cycle "
                                         "(sinon l etape des medias echoue)"}), 400
            job = {
                "id": "j%d" % int(time.time() * 1000),
                "type": genre,
                "conteneur": (corps.get("conteneur") or "").strip()[:60],
                "etape": (corps.get("etape") or "").strip()[:40],
                "scenario": (corps.get("scenario") or "").strip()[:60],
                # Un geste : tap, glissement, bouton, saisie. Les parametres
                # sont verifies par l'agent, qui seul connait l'ecran.
                "geste": (corps.get("geste") or {}) if isinstance(
                    corps.get("geste"), dict) else {},
                "identity": (corps.get("identity") or "").strip().lower()[:60],
                # L'etape 1 appelle un lien de changement d'IP avant de creer
                # le conteneur. Le sauter sert a comparer : la passation
                # soupconne ce lien de pousser Instagram vers WhatsApp, sans
                # que la mesure ait jamais ete faite.
                "sans_lien": bool(corps.get("sans_lien")),
                "categorie": (corps.get("categorie") or "").strip()[:40],
                # Les etapes d'un scenario reecrit. C'est le moteur du poste
                # qui les valide : le site ne connait pas les actions, et
                # une etape refusee ne doit pas ecraser le fichier.
                "etapes": (corps.get("etapes") or [])[:200] if isinstance(
                    corps.get("etapes"), list) else [],
                "par": (session.get("username") or "?")[:40],
                "cree": int(time.time()),
                "etat": "en_attente", "avancement": "", "erreur": "",
            }
            d["jobs"] = ([job] + d["jobs"])[:80]     # les 80 derniers suffisent
            safe_json.write(RIG_JOBS, d, indent=None)
            return jsonify({"ok": True, "job": job})

        # GET : l'etat de la file. Session OU jeton — l'interface et le poste
        # regardent la meme chose.
        if not is_auth() and _rig_ok() != 200:
            return jsonify({"ok": False, "error": "jeton"}), 403
        d = _jobs_lire()
        vieux = int(time.time()) - int(d.get("battement") or 0)
        return jsonify({"ok": True, "jobs": d["jobs"][:40],
                        "poste_en_ligne": vieux < 90,
                        "etat_poste": d.get("etat_poste") or {},
                        "vu_il_y_a": vieux if d.get("battement") else None})

    RIG_SCENARIOS = DATA_DIR / "rig_scenarios.json"

    RIG_PARC = DATA_DIR / "rig_parc.json"

    @app.route("/api/rig/parc", methods=["GET", "POST"])
    def rig_parc():
        """L'etat du parc de conteneurs, declare par l'agent."""
        from flask import jsonify
        if request.method == "POST":
            code = _rig_ok()
            if code != 200:
                return jsonify({"ok": False, "error": "jeton"}), code
            corps = request.get_json(force=True, silent=True) or {}
            propres = []
            for c in (corps.get("conteneurs") or [])[:200]:
                if not isinstance(c, dict) or not c.get("nom"):
                    continue
                et = c.get("etapes")
                propres.append({
                    "nom": str(c["nom"])[:60],
                    "categorie": str(c.get("categorie") or "")[:40],
                    "pseudo": str(c.get("pseudo") or "")[:60],
                    "passages": int(c.get("passages") or 0),
                    "abandonne": bool(c.get("abandonne")),
                    "etapes": et if isinstance(et, dict) else {},
                    "statut": str(c.get("statut") or "")[:20],
                    "etape": str(c.get("etape") or "")[:30],
                    "reconstitue": bool(c.get("reconstitue")),
                })
            safe_json.write(RIG_PARC, {
                "conteneurs": propres,
                "categories": [str(x)[:40] for x in
                               (corps.get("categories") or [])][:20],
                "objectif": int(corps.get("objectif") or 0),
                "wda": bool(corps.get("wda")),
                "ts": int(time.time()),
            }, indent=None)
            return jsonify({"ok": True, "n": len(propres)})

        if not is_auth() and _rig_ok() != 200:
            return jsonify({"ok": False, "error": "jeton"}), 403
        return jsonify({"ok": True, **(safe_json.load(RIG_PARC, default={}) or {})})

    @app.route("/api/rig/scenarios", methods=["GET", "POST"])
    def rig_scenarios():
        """Le catalogue des scenarios du poste.

        En POST, c'est l'agent qui le declare — le site n'a pas les fichiers
        et n'a aucun moyen de les deviner. En GET, l'interface le lit.
        """
        from flask import jsonify
        if request.method == "POST":
            code = _rig_ok()
            if code != 200:
                return jsonify({"ok": False, "error": "jeton"}), code
            corps = request.get_json(force=True, silent=True) or {}
            propres = []
            for it in (corps.get("scenarios") or [])[:80]:
                if not isinstance(it, dict):
                    continue
                nom = str(it.get("nom") or "").strip()[:60]
                if not nom:
                    continue
                # Le detail sert a AFFICHER le scenario, pas a le jouer :
                # c'est toujours le fichier local du poste qui est execute.
                detail = it.get("detail")
                propres.append({
                    "nom": nom,
                    "titre": str(it.get("titre") or nom)[:80],
                    "description": str(it.get("description") or "")[:300],
                    "etapes": int(it.get("etapes") or 0),
                    "detail": detail[:120] if isinstance(detail, list) else [],
                    # Sans ce drapeau, l'editeur reenregistrerait une liste
                    # coupee a 120 et perdrait la fin du scenario en silence.
                    "complet": bool(it.get("complet", True)) and (
                        not isinstance(detail, list) or len(detail) <= 120),
                })
            propres.sort(key=lambda x: x["nom"])
            safe_json.write(RIG_SCENARIOS,
                            {"scenarios": propres, "ts": int(time.time())},
                            indent=None)
            return jsonify({"ok": True, "n": len(propres)})

        if not is_auth() and _rig_ok() != 200:
            return jsonify({"ok": False, "error": "jeton"}), 403
        d = safe_json.load(RIG_SCENARIOS, default={}) or {}
        return jsonify({"ok": True, "scenarios": d.get("scenarios") or [],
                        "ts": d.get("ts") or 0})

    RIG_ACTIONS = DATA_DIR / "rig_actions.json"

    @app.route("/api/rig/actions", methods=["GET", "POST"])
    def rig_actions():
        """Les actions que le moteur du poste comprend.

        L'editeur s'en sert pour proposer une palette. Sans elle il faudrait
        deviner les noms, et une action inventee fait echouer la validation
        au moment ou l'on croit avoir enregistre.
        """
        from flask import jsonify
        if request.method == "POST":
            code = _rig_ok()
            if code != 200:
                return jsonify({"ok": False, "error": "jeton"}), code
            corps = request.get_json(force=True, silent=True) or {}
            propres = []
            for a in (corps.get("actions") or [])[:80]:
                if not isinstance(a, dict) or not (a.get("nom") or "").strip():
                    continue
                propres.append({"nom": str(a["nom"]).strip()[:40],
                                "doc": str(a.get("doc") or "")[:200],
                                "exemple": str(a.get("exemple") or "")[:300]})
            propres.sort(key=lambda x: x["nom"])
            safe_json.write(RIG_ACTIONS,
                            {"actions": propres, "ts": int(time.time())},
                            indent=None)
            return jsonify({"ok": True, "n": len(propres)})

        if not is_auth() and _rig_ok() != 200:
            return jsonify({"ok": False, "error": "jeton"}), 403
        d = safe_json.load(RIG_ACTIONS, default={}) or {}
        return jsonify({"ok": True, "actions": d.get("actions") or [],
                        "ts": d.get("ts") or 0})

    RIG_ECRAN = DATA_DIR / "rig_ecran.jpg"
    RIG_PILOTAGE = DATA_DIR / "rig_pilotage.json"

    def _pilotage_actif() -> bool:
        """Quelqu'un regarde-t-il l'ecran en ce moment ?"""
        try:
            d = safe_json.load(RIG_PILOTAGE, default={}) or {}
            return (time.time() - float(d.get("ts") or 0)) < 25
        except Exception:
            return False

    @app.route("/api/rig/pilotage", methods=["POST"])
    def rig_pilotage():
        """L'interface signale qu'elle affiche l'ecran."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False}), 401
        safe_json.write(RIG_PILOTAGE, {"ts": int(time.time())}, indent=None)
        return jsonify({"ok": True})

    @app.route("/api/rig/ecran", methods=["GET", "POST"])
    def rig_ecran():
        """La derniere capture d'ecran du telephone."""
        from flask import jsonify, send_file
        if request.method == "POST":
            code = _rig_ok()
            if code != 200:
                return jsonify({"ok": False, "error": "jeton"}), code
            data = request.get_data() or b""
            # Une capture reduite tient en quelques dizaines de kilo-octets ;
            # au-dela, c'est que la reduction n'a pas eu lieu cote poste.
            if not (100 < len(data) <= 900_000):
                return jsonify({"ok": False, "error": "taille inattendue"}), 400
            tmp = RIG_ECRAN.with_suffix(".part")
            tmp.write_bytes(data)
            tmp.replace(RIG_ECRAN)
            return jsonify({"ok": True, "octets": len(data)})

        if not is_auth():
            return redirect("/")
        if not RIG_ECRAN.exists():
            return ("", 204)
        r = send_file(str(RIG_ECRAN), mimetype="image/jpeg")
        # Jamais de cache : c'est une image qui change en permanence, et une
        # copie gardee par le navigateur figerait l'ecran.
        r.headers["Cache-Control"] = "no-store"
        return r

    @app.route("/api/rig/pull", methods=["POST"])
    def rig_pull():
        """Le poste prend le plus ancien travail en attente, et signale qu'il
        est vivant. Rend null s'il n'y a rien — ce n'est pas une erreur."""
        from flask import jsonify
        code = _rig_ok()
        if code != 200:
            return jsonify({"ok": False, "error": "jeton"}), code
        d = _jobs_lire()
        d["battement"] = int(time.time())
        # Le poste joint l'etat du telephone : c'est lui qui parle a la
        # console, en local. Le navigateur ne le peut qu'en etant sur cette
        # machine ET avec une autorisation de lecture — deux conditions de
        # trop pour un simple bandeau.
        corps = request.get_json(force=True, silent=True) or {}
        et = corps.get("etat")
        if isinstance(et, dict):
            d["etat_poste"] = {
                "connecte": bool(et.get("connecte")),
                "appareil": str(et.get("appareil") or "")[:40],
                "ios": str(et.get("ios") or "")[:20],
                "ecran": str(et.get("ecran") or "")[:20],
                "fps": int(et.get("fps") or 0),
            }
        pris = None
        # Le plus ancien d'abord : la liste est rangee du plus recent au plus
        # vieux, on la parcourt donc a l'envers.
        for job in reversed(d["jobs"]):
            if job.get("etat") == "en_attente":
                job["etat"] = "pris"
                job["pris_a"] = int(time.time())
                pris = job
                break
        safe_json.write(RIG_JOBS, d, indent=None)
        return jsonify({"ok": True, "job": pris,
                        "pilotage": _pilotage_actif()})

    @app.route("/api/rig/report", methods=["POST"])
    def rig_report():
        """Le poste rend compte d'un travail : avancement, fin ou echec."""
        from flask import jsonify
        code = _rig_ok()
        if code != 200:
            return jsonify({"ok": False, "error": "jeton"}), code
        corps = request.get_json(force=True, silent=True) or {}
        ident = (corps.get("id") or "").strip()
        d = _jobs_lire()
        d["battement"] = int(time.time())
        touche = False
        for job in d["jobs"]:
            if job.get("id") != ident:
                continue
            etat = (corps.get("etat") or "").strip()
            if etat in ("en_cours", "fini", "echec"):
                job["etat"] = etat
            job["avancement"] = str(corps.get("avancement") or "")[:200]
            job["erreur"] = str(corps.get("erreur") or "")[:300]
            job["maj"] = int(time.time())
            touche = True
            break
        safe_json.write(RIG_JOBS, d, indent=None)
        # Un rapport sur un travail inconnu n'est pas une erreur du poste : le
        # site a pu etre redeploye entre-temps. On le dit sans echouer.
        return jsonify({"ok": True, "connu": touche})

    @app.route("/api/rig/queue", methods=["POST"])
    def rig_queue():
        """Le poste pose la file du cycle : une liste de medias, dans l'ordre.

        Chaque entree est verifiee ici — un nom fabrique cote poste ne doit
        pas pouvoir sortir de la bibliotheque.
        """
        from flask import jsonify
        code = _rig_ok()
        if code != 200:
            return jsonify({"ok": False, "error": "jeton"}), code
        import json as _js
        try:
            brut = request.get_json(force=True, silent=True) or {}
            demandes = brut.get("items") or []
        except Exception:
            demandes = []
        retenus, refuses = [], []
        for it in demandes[:60]:
            if not isinstance(it, dict):
                continue
            chemin, c, motif = _cloud_media_path(
                it.get("identity") or "", it.get("subdir") or "",
                it.get("fichier") or "")
            if chemin is None:
                refuses.append({"fichier": it.get("fichier"), "motif": motif})
                continue
            # Une brute desactivee n'entre pas dans la file : sans ce test elle
            # y resterait meme si on l'eteint juste apres, et partirait au
            # prochain cycle. Refusee AVEC son motif — jamais en silence.
            if _off.est_desactivee(chemin):
                refuses.append({"fichier": it.get("fichier"),
                                "motif": "désactivée (caption déjà incrustée)"})
                continue
            retenus.append({"identity": (it.get("identity") or "").lower().strip(),
                            "subdir": it.get("subdir"), "fichier": it.get("fichier"),
                            "taille": chemin.stat().st_size})
        safe_json.write(RIG_FILE, {"items": retenus, "servis": [],
                                   "ts": int(time.time())}, indent=None)
        return jsonify({"ok": True, "n": len(retenus), "refuses": refuses})

    @app.route("/api/rig/count")
    def rig_count():
        """Combien de medias restent a prendre. Aucun nom n'est revele."""
        from flask import jsonify
        code = _rig_ok()
        if code != 200:
            return jsonify({"ok": False, "error": "jeton"}), code
        d = _rig_file_lire()
        reste = len(d.get("items") or []) - len(d.get("servis") or [])
        return jsonify({"n": max(0, reste)})

    @app.route("/api/rig/next")
    def rig_next():
        """Le prochain media de la file, en octets.

        Marque servi AVANT l'envoi, comme le serveur local : on ne sait pas
        si le telephone a tout recu. C'est pourquoi l'etape 2 verifie la
        pellicule au lieu de croire ce compteur — ne pas revenir la-dessus.
        """
        from flask import jsonify, send_file
        code = _rig_ok()
        if code != 200:
            return jsonify({"ok": False, "error": "jeton"}), code
        d = _rig_file_lire()
        items = d.get("items") or []
        servis = set(d.get("servis") or [])
        for i, it in enumerate(items):
            cle = "%d" % i
            if cle in servis:
                continue
            chemin, c, motif = _cloud_media_path(
                it.get("identity"), it.get("subdir"), it.get("fichier"))
            if chemin is None:
                servis.add(cle)          # disparu depuis : on passe au suivant
                continue
            # Ceinture et bretelles : la file a pu etre remplie AVANT qu'on
            # eteigne la video. C'est le dernier maillon avant la pellicule du
            # telephone — donc avant la publication.
            if _off.est_desactivee(chemin):
                servis.add(cle)
                d["servis"] = sorted(servis)
                safe_json.write(RIG_FILE, d, indent=None)
                continue
            servis.add(cle)
            d["servis"] = sorted(servis)
            safe_json.write(RIG_FILE, d, indent=None)
            return send_file(str(chemin), conditional=False)
        return jsonify({"ok": False, "error": "file vide"}), 404

    @app.route("/api/rig/file/<identity>/<subdir>/<path:filename>")
    def rig_serve_file(identity, subdir, filename):
        """Un media, servi au poste. Memes controles que le dashboard."""
        from flask import jsonify, send_file
        code = _rig_ok()
        if code != 200:
            return jsonify({"ok": False, "error": "jeton"}), code
        path, code, motif = _cloud_media_path(identity, subdir, filename)
        if path is None:
            return jsonify({"ok": False, "error": motif}), code
        return send_file(str(path), conditional=True)

    @app.route("/version")
    def version_du_site():
        """Quelle version du code ce serveur fait-il tourner ?

        Question posee plusieurs fois sans qu'on puisse y repondre : « les
        icones sont changees dans le code mais je vois encore les anciennes ».
        Sans ce reperage, impossible de distinguer un cache navigateur d'un
        serveur reste sur un ancien processus.
        """
        import datetime as _d
        import subprocess as _sp
        commit, quand, sujet = "?", "?", ""
        try:
            r = _sp.run(["git", "log", "-1", "--format=%h|%cI|%s"],
                        capture_output=True, text=True, timeout=5,
                        cwd=str(Path(__file__).resolve().parent))
            if r.returncode == 0 and r.stdout.strip():
                commit, quand, sujet = (r.stdout.strip().split("|", 2) + ["", ""])[:3]
        except Exception:
            # Pas de git sur la machine : le fichier .git/HEAD suffit a
            # identifier la revision.
            try:
                g = Path(__file__).resolve().parent / ".git"
                tete = (g / "HEAD").read_text(encoding="utf-8").strip()
                if tete.startswith("ref:"):
                    commit = (g / tete[5:]).read_text(encoding="utf-8").strip()[:7]
                else:
                    commit = tete[:7]
            except Exception:
                pass
        # Les deux dates doivent se lire dans le MEME fuseau : la date de
        # publication vient de git (heure de la machine qui a commite), celle
        # du demarrage vient du serveur. Affichees telles quelles, un
        # deploiement et son redemarrage semblaient separes de deux heures.
        demarre = _d.datetime.fromtimestamp(
            _DEMARRAGE, _d.timezone.utc).astimezone().strftime("%d/%m %H:%M %Z")
        age = int((time.time() - _DEMARRAGE) // 60)
        return (
            "<div style=\"font:14px/1.6 -apple-system,system-ui,sans-serif;"
            "padding:26px;max-width:560px;margin:40px auto;background:#fff;"
            "color:#1c1c1e;border:1px solid #e5e7eb;border-radius:14px\">"
            "<h2 style='margin:0 0 14px'>Version en ligne</h2>"
            f"<p><b>Code</b> : {html_escape(commit)}<br>"
            f"<span style='color:#666'>{html_escape(sujet[:90])}</span><br>"
            f"<span style='color:#666'>publie le {html_escape(quand[:16].replace('T', ' a '))}</span></p>"
            f"<p><b>Serveur demarre</b> : {demarre} "
            f"<span style='color:#666'>(il y a {age} min)</span></p>"
            # ffmpeg decide de TOUTES les vignettes video. Sans lui, la
            # galerie des rushs bruts est un mur de cartes noires — et on
            # cherche du cote du navigateur pendant des heures. Autant que la
            # page qu'on ouvre deja pour verifier un deploiement le dise.
            f"<p><b>ffmpeg</b> : {_diag_ffmpeg()}</p>"
            "<p style='color:#666;font-size:13px'>Si le code affiche ici n'est pas "
            "le dernier publie, le serveur n'a pas redemarre. Si c'est bien le "
            "dernier mais que la page reste ancienne, c'est le cache du "
            "navigateur.</p>"
            "<p><a href='/'>Retour au site</a></p></div>")

    @app.route("/ventes-sheet")
    def ventes_sheet_go():
        """Declenche la synchro et affiche le resultat — accessible a la main.

        Les boutons vivent dans la section MyPuls, qui ne s'affiche que si le
        scraping a reussi. Cette adresse marche dans tous les cas : on la colle
        dans la barre du navigateur.
        """
        if not is_auth():
            return redirect("/")
        import ventes_sheet as _vs
        import mypuls
        import datetime as _d
        today = _d.date.today()
        debut = today.replace(day=1).isoformat()
        _err = None
        try:
            res = mypuls.fetch_team_stats(debut, today.isoformat(), use_cache=True)
            tx = res.get("transactions") or []
            if not res.get("ok"):
                _err = res.get("error") or "MyPuls indisponible"
        except Exception as e:
            tx, _err = [], str(e)[:200]
        # Commissions et taux du jour : sans eux, la feuille de paie tombait
        # sur les valeurs par defaut et n'avait plus rien a voir avec la page.
        _comm, _taux = _ventes_contexte(tx)
        out = _vs.pousser(tx, periode=f"{debut} -> {today.isoformat()}",
                          commissions=_comm, eur_usd=_taux,
                          chatters=(res.get("chatters") if not _err else None),
                          diagnostic=(res.get("diagnostic") if not _err else None)
                          ) if not _err else {"ok": False, "err": _err}
        lien = "https://docs.google.com/spreadsheets/d/%s/edit" % _vs.sheet_id()
        if out.get("ok"):
            # Le resume des ecarts s'affiche ICI : le but de la manoeuvre est
            # de reperer les ventes manquantes, pas seulement de recopier.
            alerte = ""
            try:
                import ventes_export as _ve
                _lg = _ve.lignes_ventes(tx)
                _c, _rows = _ve.rapprochement(_lg, res.get("chatters"),
                                              res.get("diagnostic"))
                _pb = [r for r in _rows if str(r[5]).startswith(("ABSENT", "INCOMPLET"))]
                if _pb:
                    lis = "".join(
                        "<li><b>%s</b> — %s</li>" % (html_escape(str(r[0])),
                                                     html_escape(str(r[5])))
                        for r in _pb[:12])
                    alerte = ("<div style='margin:16px 0;padding:12px 14px;"
                              "background:#fef2f2;border:1px solid #fecaca;"
                              "border-radius:10px'>"
                              "<b>%d ecart(s) entre le site et le registre</b>"
                              "<ul style='margin:8px 0 0;padding-left:20px'>%s</ul>"
                              "<p style='margin:8px 0 0;font-size:13px;color:#7f1d1d'>"
                              "Detail complet dans l'onglet « Site vs registre ».</p>"
                              "</div>") % (len(_pb), lis)
                else:
                    alerte = ("<p style='color:#166534'>Aucun ecart : le registre "
                              "recoupe le tableau du site.</p>")
            except Exception:
                pass
            corps = (f"<h2 style='margin:0 0 8px'>Classeur mis a jour</h2>"
                     f"<p>{out.get('lignes', 0)} vente(s) ecrite(s) — periode {debut} au {today.isoformat()}.</p>"
                     f"{alerte}"
                     f"<p>Il se rafraichira tout seul toutes les 5 minutes.</p>"
                     f"<p><a href='{lien}' target='_blank'>Ouvrir le classeur</a></p>")
        else:
            corps = (f"<h2 style='margin:0 0 8px'>Echec</h2>"
                     f"<p style='color:#b91c1c'>{html_escape(str(out.get('err') or '?'))}</p>"
                     f"<p>Verifie que le classeur est partage en <b>Editeur</b> avec le compte "
                     f"de service du site.</p>")
        return ("<div style=\"font:15px/1.5 -apple-system,system-ui,sans-serif;padding:28px;"
                "max-width:620px;margin:40px auto;background:#fff;border:1px solid #e5e7eb;"
                "border-radius:14px\">" + corps +
                "<p style='margin-top:18px'><a href='/?tab=revenus'>Retour au site</a></p></div>")

    @app.route("/chatters/ventes.xlsx")
    def chatters_ventes_xlsx():
        """Registre detaille des ventes, en Excel.

        Repond au besoin de VERIFIER une vente : un chatteur affirme l'avoir
        faite, on ouvre le fichier et on voit l'heure, la creatrice, le fan et
        le montant. Trois onglets : le registre, un total par chatteur, et un
        controle qui signale les ventes sans chatteur ou sans date — c'est la
        que se voient les lignes qui « ne montent pas ».
        """
        from flask import send_file, request as _rq
        if not is_auth():
            return redirect("/")
        try:
            _al = _role_allowed_tabs(_live_role())
        except Exception:
            _al = None
        if _al is not None and "revenus" not in _al:
            return ("", 403)
        import mypuls
        import datetime as _d
        today = _d.date.today()
        start = (_rq.args.get("start") or "").strip() or (today - _d.timedelta(days=29)).isoformat()
        end = (_rq.args.get("end") or "").strip() or today.isoformat()
        try:
            res = mypuls.fetch_team_stats(start, end, use_cache=True)
        except Exception as e:
            return _error(f"MyPuls indisponible : {e}", tab="revenus")
        if not res.get("ok"):
            return _error(res.get("error") or "MyPuls indisponible", tab="revenus")
        tx = res.get("transactions") or []
        # total annonce : sert a chiffrer l'ecart dans l'onglet Controle
        _tot = None
        try:
            _t = res.get("totals") or {}
            _tot = float(_t.get("ca") or _t.get("total") or 0) or None
        except Exception:
            _tot = None
        import ventes_export as _ve
        try:
            _comm, _taux = _ventes_contexte(tx)
            data = _ve.construire_xlsx(tx, periode=f"{start} -> {end}", total_annonce=_tot,
                                       commissions=_comm, eur_usd=_taux,
                                       chatters=res.get("chatters"),
                                       diagnostic=res.get("diagnostic"))
        except Exception as e:
            return _error(f"Export impossible : {e}", tab="revenus")
        import io as _io
        return send_file(_io.BytesIO(data),
                         mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                         as_attachment=True,
                         download_name=f"ventes_{start}_{end}.xlsx")

    @app.route("/gdrive/attente")
    def gdrive_attente():
        """Ce que la veille a vu la derniere fois. Lecture d'un fichier :
        aucun appel a Google, donc appelable a chaque chargement de page."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False}), 401
        import gdrive_sync as _gd
        try:
            return jsonify({"ok": True, **(_gd.attente() or {})})
        except Exception:
            return jsonify({"ok": True, "total": 0})

    @app.route("/gdrive/import_scan", methods=["POST"])
    def gdrive_import_scan():
        """Combien de fichiers attendent dans le Drive, et chez qui — sans
        rien télécharger. Le bouton d'import partait à l'aveugle avant."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        import gdrive_sync as _gd
        # La veille parcourt le Drive chaque minute et ecrit ce qu'elle a vu
        # dans data/gdrive_attente.json (meme fonction, meme charge utile).
        # Refaire le parcours pendant que le bouton attend, c'est une centaine
        # d'allers-retours Google pour une reponse deja sur le disque. Passe
        # 90 s, on redemande pour de vrai. Un fichier d'attente illisible ne
        # doit PAS transformer le bouton en erreur : on retombe sur le parcours.
        try:
            _vu = _gd.attente() or {}
            if _vu.get("detail") is not None and \
                    (time.time() - float(_vu.get("ts") or 0)) < 90:
                return jsonify({"ok": True, "cache": True, **_vu})
        except Exception:
            pass
        try:
            return jsonify({"ok": True, **_gd.import_preview()})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)[:200]})

    @app.route("/drive-manques")
    def gdrive_inventaire_page():
        """Ce que le Drive contient face a ce que le site possede.

        L'apercu d'import ne sait dire que « ce que je vais rapatrier » : il
        annonce donc « rien de nouveau » alors qu'il manque des centaines de
        fichiers qu'il n'a pas su voir. Cette page-ci compte les deux cotes.
        """
        if not is_auth():
            return redirect("/")
        import gdrive_sync as _gd
        if request.args.get("refaire"):
            _gd._INVENTAIRE_CACHE["data"] = None
        etat = _gd.inventaire_lancer()
        if etat.get("state") != "done":
            # La page s'affiche AVANT que le comptage soit fini : sinon le
            # navigateur reste sur un ecran blanc pendant tout le parcours du
            # Drive, sans rien pour dire que ca avance.
            return ("<div style=\"font:14px/1.55 -apple-system,system-ui,sans-serif;"
                    "padding:28px;max-width:640px;margin:40px auto;background:#fff;"
                    "color:#1c1c1e;border:1px solid #e5e7eb;border-radius:14px\">"
                    "<h2 style='margin:0 0 8px'>Lecture du Drive…</h2>"
                    "<p style='color:#666'>Je compte les fichiers des deux cotes, "
                    "puis je regarde ce que l'import sait voir. Comptez une a deux "
                    "minutes ; la page se rafraichit toute seule.</p>"
                    + (f"<p style='color:#1c1c1e;font-weight:600;margin:0 0 10px'>"
                       f"{html_escape(str(etat.get('etape') or ''))}"
                       f"<span style='font-weight:400;color:#999'> — "
                       f"{max(0, int(time.time()) - int(etat.get('debut') or time.time()))} s"
                       f"</span></p>" if etat.get("etape") else "")
                    + "<div style='height:4px;background:#eee;border-radius:3px;overflow:hidden'>"
                    "<div style='height:100%;width:35%;background:#3b82f6;"
                    "animation:vaSlide 1.4s ease-in-out infinite'></div></div>"
                    "<style>@keyframes vaSlide{0%{margin-left:-35%}"
                    "100%{margin-left:100%}}</style>"
                    "<p style='margin-top:16px;font-size:12px;color:#999'>"
                    + html_escape(str(etat.get("err") or "")) + "</p>"
                    "<script>setTimeout(function(){location.reload();},4000);</script>"
                    "</div>")
        inv = _gd.inventaire_etat().get("data") or {}
        if not inv:
            return ("<div style='font:15px/1.5 -apple-system,system-ui;padding:28px'>"
                    "<b>Lecture impossible :</b> "
                    + html_escape(str(etat.get("err") or "resultat vide")) +
                    "<p><a href='/?tab=cloud'>Retour</a></p></div>")

        def _tr(r):
            manque = r["manque"]
            invisible = r.get("invisible", 0)
            # Rouge vif : l'import ne voit meme pas ces fichiers. C'est la
            # colonne qui compte — un manque que l'import connait se resout
            # d'un clic, un manque invisible ne se resoudra jamais tout seul.
            fond = ("background:#fee2e2" if invisible
                    else ("background:#fffbeb" if manque else ""))
            couleur = "#b91c1c" if manque else "#166534"
            return (f"<tr style='{fond}'><td>{html_escape(r['identity'])}</td>"
                    f"<td>{html_escape(r['type'])}</td>"
                    f"<td style='text-align:right'>{r['drive']}</td>"
                    f"<td style='text-align:right'>{r['site']}</td>"
                    f"<td style='text-align:right;font-weight:700;color:{couleur}'>"
                    f"{manque or '—'}</td>"
                    f"<td style='text-align:right;color:#2563eb'>"
                    f"{r.get('import', 0) or '—'}</td>"
                    f"<td style='text-align:right;font-weight:700;color:#b91c1c'>"
                    f"{invisible or '—'}</td></tr>")

        lignes = "".join(_tr(r) for r in inv["lignes"]) or (
            "<tr><td colspan='7' style='padding:18px;color:#888'>"
            "Aucun dossier lisible sur le Drive.</td></tr>")

        alertes = ""
        if inv["dossiers_non_reconnus"]:
            items = "".join("<li><b>%s</b> — %d fichier(s)</li>"
                            % (html_escape(d["nom"]), d["n"])
                            for d in inv["dossiers_non_reconnus"])
            alertes += ("<div style='margin:14px 0;padding:12px 14px;background:#fffbeb;"
                        "border:1px solid #fde68a;border-radius:10px'>"
                        "<b>Dossiers dont le nom n'est pas reconnu</b> — leur contenu "
                        "est ignoré par l'import :<ul style='margin:6px 0 0'>"
                        + items + "</ul></div>")
        if inv["identites_inconnues"]:
            items = "".join("<li><b>%s</b> — %d fichier(s)</li>"
                            % (html_escape(d["nom"]), d["n"])
                            for d in inv["identites_inconnues"])
            alertes += ("<div style='margin:14px 0;padding:12px 14px;background:#fef2f2;"
                        "border:1px solid #fecaca;border-radius:10px'>"
                        "<b>Identités présentes sur le Drive, inconnues du site</b> — "
                        "leurs fichiers ne peuvent aller nulle part. Vérifie "
                        "l'orthographe du dossier :<ul style='margin:6px 0 0'>"
                        + items + "</ul></div>")

        entete = ("<h2 style='margin:0 0 4px'>Drive face au site</h2>"
                  f"<p style='color:#666;margin:0 0 6px'>{inv['total_drive']} fichier(s) "
                  f"sur le Drive, {inv['total_site']} sur le site — "
                  f"<b style='color:{'#b91c1c' if inv['total_manque'] else '#166534'}'>"
                  f"{inv['total_manque']} manquant(s)</b>.</p>"
                  f"<p style='color:#666;margin:0 0 16px;font-size:13px'>"
                  f"L'import en reconnait <b style='color:#2563eb'>"
                  f"{inv.get('total_import', 0)}</b> — il en reste "
                  f"<b style='color:#b91c1c'>{inv.get('total_invisible', 0)}</b> "
                  f"qu'il ne voit pas.</p>"
                  + (f"<p style='color:#92400e;margin:0 0 16px;font-size:13px;"
                     f"padding:10px 12px;background:#fffbeb;border:1px solid #fde68a;"
                     f"border-radius:8px'><b>{inv['copies_drive']} copie(s) sur le "
                     f"Drive</b> — des « _2 », « _3 » identiques a leur original, "
                     f"laissees par d'anciens imports. Elles ne sont ni comptees "
                     f"comme manquantes ni rapatriees.</p>"
                     if inv.get("copies_drive") else ""))

        # Les compteurs du scan : c'est la que se lit POURQUOI un fichier
        # present sur le Drive n'est pas propose a l'import.
        _r = inv.get("raisons_import") or {}
        _lbl = {"deja_sur_le_site": "ecartes car deja presents sur le site",
                "identique_au_site": "ecartes : meme nom et meme taille en local",
                "format_non_gere": "ecartes : extension non geree",
                "copies_du_drive": "ecartes : copies du Drive (pp_69_2, pp_69_3…)",
                "nom_deja_pris": "ecartes : ce nom existe deja sur le site",
                "dossiers_non_reconnus": "dossiers au nom inconnu",
                "erreur": "erreur pendant le scan"}
        _items = "".join(
            "<li>%s : <b>%s</b></li>" % (html_escape(_lbl.get(k, k)),
                                         html_escape(str(v)))
            for k, v in _r.items() if v and k != "vus")
        if _items:
            entete += ("<div style='margin:0 0 16px;padding:12px 14px;background:#f8fafc;"
                       "border:1px solid #e2e8f0;border-radius:10px;font-size:13px'>"
                       "<b>Ce que le scan d'import a ecarte</b>"
                       "<ul style='margin:6px 0 0'>" + _items + "</ul></div>")

        return ("<div style=\"font:14px/1.55 -apple-system,system-ui,sans-serif;"
                "padding:28px;max-width:860px;margin:30px auto;background:#fff;"
                "color:#1c1c1e;border:1px solid #e5e7eb;border-radius:14px\">"
                + entete + alertes +
                "<table style='width:100%;border-collapse:collapse'>"
                "<thead><tr style='text-align:left;border-bottom:2px solid #e5e7eb'>"
                "<th>Identité</th><th>Type</th>"
                "<th style='text-align:right'>Drive</th>"
                "<th style='text-align:right'>Site</th>"
                "<th style='text-align:right'>Manque</th>"
                "<th style='text-align:right' title='Ce que le bouton Importer "
                "compte rapatrier'>Import</th>"
                "<th style='text-align:right' title='Manquants que l import ne "
                "voit meme pas'>Invisible</th></tr></thead>"
                "<tbody>" + lignes + "</tbody></table>"
                "<p style='margin-top:18px'><a href='/?tab=cloud'>Retour au Drive</a>"
                " &nbsp;·&nbsp; <a href='/drive-manques?refaire=1'>Recompter</a></p>"
                "</div>")

    @app.route("/gdrive/root_cleanup", methods=["POST"])
    def gdrive_root_cleanup():
        """Range la racine du Drive : met à la CORBEILLE les dossiers laissés
        par l'ancien rangement (identités en vrac, « Vault PRO »).

        Volontairement à part de gdrive_sync, qui n'a le droit de rien
        supprimer — invariant vérifié par les tests. Trois garde-fous :
        seulement des DOSSIERS, seulement s'ils sont VIDES (récursivement),
        et jamais « Bibliothèque » ni « A IMPORTER ». Corbeille, pas
        suppression définitive : récupérable 30 jours.

        `dry=1` : liste seulement, ne touche à rien."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        if not _is_admin():
            return jsonify({"ok": False, "error": "réservé à l'admin"}), 403
        import gdrive_sync as _gd
        cfg = _gd.load_config()
        root = _gd.folder_id_from(cfg.get("folder") or "")
        if not root:
            return jsonify({"ok": False, "error": "dossier Drive non configuré"})
        try:
            sess = _gd._session()
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)[:200]})

        # `tout=1` : on examine AUSSI les dossiers nommes comme la
        # bibliotheque. Utile quand un doublon existe (« Bibliotheque » sans
        # accent a cote de « Bibliothèque ») : c'est le test de vacuite qui
        # protege, pas le nom.
        _tout = bool(request.form.get("tout"))
        garder = {_gd._sansaccent(_gd.IMPORT_FOLDER_NAME)}
        if not _tout:
            garder.add(_gd._sansaccent(_gd.RACINE_BIBLIO))

        def _compte_fichiers(fid, profondeur=0):
            """Nombre de fichiers sous ce dossier. S'arrête au premier trouvé :
            un dossier qui contient quelque chose ne sera pas touché."""
            if profondeur > 4:
                return 1            # trop profond -> on considère non vide
            try:
                if _gd._lister(sess, fid, dossiers=False):
                    return 1
                for sous in _gd._lister(sess, fid, dossiers=True):
                    if _compte_fichiers(sous["id"], profondeur + 1):
                        return 1
            except Exception:
                return 1            # dans le doute, on n'y touche pas
            return 0

        candidats = []
        try:
            for f in _gd._lister(sess, root, dossiers=True):
                if _gd._sansaccent(f["name"]) in garder:
                    continue
                candidats.append({"nom": f["name"], "id": f["id"],
                                  "vide": _compte_fichiers(f["id"]) == 0})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)[:200]})

        vides = [c for c in candidats if c["vide"]]
        # Garde-fou : si TOUS les dossiers « bibliotheque » sont vides, on n'y
        # touche pas. Ca voudrait dire que le contenu a disparu, et supprimer
        # serait exactement la mauvaise reaction.
        _nom_b = _gd._sansaccent(_gd.RACINE_BIBLIO)
        _bibs = [c for c in candidats if _gd._sansaccent(c["nom"]) == _nom_b]
        if _bibs and all(c["vide"] for c in _bibs):
            vides = [c for c in vides if _gd._sansaccent(c["nom"]) != _nom_b]
        if request.form.get("dry"):
            # « tous » sert au diagnostic : deux dossiers dont le nom ne
            # differe que par un accent sont indiscernables a l'oeil.
            try:
                tous = [{"nom": f["name"], "id": f["id"]}
                        for f in _gd._lister(sess, root, dossiers=True)]
            except Exception:
                tous = []
            return jsonify({"ok": True, "dry": True, "tous": tous,
                            "a_supprimer": [c["nom"] for c in vides],
                            "gardes_car_non_vides": [c["nom"] for c in candidats
                                                     if not c["vide"]]})
        # Ces dossiers ont ete crees par le COMPTE DE SERVICE : sur Drive,
        # seul le proprietaire peut mettre a la corbeille. Le compte du
        # patron, meme editeur du dossier parent, recolte un 403. On tente
        # donc avec son compte, puis avec le compte de service.
        sess_sa = None
        try:
            if _gd.SA_FILE.exists():
                from google.oauth2.service_account import Credentials as _SACreds
                from google.auth.transport.requests import AuthorizedSession as _AuthSess
                sess_sa = _AuthSess(_SACreds.from_service_account_file(
                    str(_gd.SA_FILE), scopes=[_gd.OAUTH_SCOPE]))
        except Exception:
            sess_sa = None

        def _corbeille(session, fid):
            return session.patch(
                "https://www.googleapis.com/drive/v3/files/" + fid
                + "?supportsAllDrives=true",
                json={"trashed": True}, timeout=60)

        faits, echecs = [], []
        for c in vides:
            try:
                r = _corbeille(sess, c["id"])
                if r.status_code >= 400 and sess_sa is not None:
                    r = _corbeille(sess_sa, c["id"])       # le proprietaire
                if r.status_code < 400:
                    faits.append(c["nom"])
                else:
                    echecs.append(c["nom"] + " (HTTP " + str(r.status_code) + ")")
            except Exception as e:
                echecs.append(c["nom"] + " — " + str(e)[:80])
        return jsonify({"ok": True, "corbeille": faits, "echecs": echecs,
                        "gardes_car_non_vides": [c["nom"] for c in candidats
                                                 if not c["vide"]]})

    @app.route("/gdrive/report")
    def gdrive_report():
        """Statut de synchro identité par identité (pour rafraîchir sans recharger)."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False}), 401
        import gdrive_sync as _gd
        try:
            return jsonify({"ok": True, **_gd.sync_report()})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)[:200]})

    @app.route("/gdrive/status")
    def gdrive_status():
        """Avancement des 2 sens (barres de progression)."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False}), 401
        import gdrive_sync as _gd
        return jsonify({"ok": True, "sync": _gd.status(), "import": _gd.import_status()})

    @app.route("/gdrive/import", methods=["POST"])
    def gdrive_import_now():
        """Rapatrie « A IMPORTER » du Drive vers la bibliothèque. Idéal pour les
        gros lots : le VPS télécharge depuis Google, donc aucune limite de
        taille du navigateur."""
        if not is_auth():
            return redirect("/")
        import gdrive_sync as _gd
        if not _gd.available():
            return _error("Compte de service Google absent (data/google_service_account.json)",
                          tab="clouddrive")
        if not _gd.folder_id_from(_gd.load_config().get("folder") or ""):
            return _error("Renseigne d'abord le dossier Drive partagé", tab="clouddrive")
        if not _gd.start_import_background():
            return _error("Un import tourne déjà — la barre suit l'avancement",
                          tab="clouddrive")
        return _success("⬇️ Import lancé — la barre affiche l'avancement",
                        tab="clouddrive")

