    @app.route("/insta/dl_status")
    def insta_dl_status():
        """Compte des vidéos prêtes (mp4 en local) sur les reels vidéo des 7
        derniers jours — alimente la barre de progression de Trends."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False}), 401
        try:
            from insta_scraper import get_all_cached_reels, load_watchlist
            import time as _t2
            wl = {str(u or "").lower().strip().lstrip("@") for u in (load_watchlist() or [])}
            cutoff = _t2.time() - 7 * 86400
            total = ready = 0
            for r in get_all_cached_reels():
                if not r.get("is_video"):
                    continue
                if str(r.get("_owner") or "").lower().strip().lstrip("@") not in wl:
                    continue
                ta = r.get("taken_at") or 0
                if ta and ta < cutoff:
                    continue
                m = re.search(r'/(?:p|reel|reels)/([A-Za-z0-9_-]+)', r.get("url") or "")
                if not m:
                    continue
                total += 1
                f = INSTA_VIDEOS_DIR / f"{m.group(1)}.mp4"
                if f.exists() and f.stat().st_size > 1024:
                    ready += 1
            _active = _PREDL_STATE.get("active")
            return jsonify({"ok": True, "ready": ready, "total": total,
                            "running": bool(_PREDL_STATE.get("running")),
                            "pass_done": int(_PREDL_STATE.get("done") or 0),
                            "pass_total": int(_PREDL_STATE.get("total") or 0),
                            "active": list(_active) if isinstance(_active, set) else [],
                            "apify": _PREDL_STATE.get("apify") or {}})
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})

    @app.route("/admin/backup_data")
    def admin_backup_data():
        """CHECKPOINT des données du VPS : zippe data/ (hors médias lourds
        régénérables) dans data_backups/checkpoint_<horodatage>.zip.
        ?list=1 pour lister les sauvegardes existantes."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False}), 401
        import zipfile
        import datetime as _dtb
        dest_dir = Path("data_backups")
        dest_dir.mkdir(exist_ok=True)
        if request.args.get("list"):
            lst = sorted(dest_dir.glob("checkpoint_*.zip"), reverse=True)
            return jsonify({"ok": True, "sauvegardes": [
                {"fichier": p.name, "taille_mo": round(p.stat().st_size / 1e6, 2)}
                for p in lst[:20]]})
        stamp = _dtb.datetime.now().strftime("%Y%m%d_%H%M%S")
        dest = dest_dir / f"checkpoint_{stamp}.zip"
        import threading

        def _zip_bg():
            # EN FOND : le zip de data/ peut dépasser le timeout du proxy (502
            # observé) — la requête rend la main immédiatement, l'état se lit
            # avec ?list=1 (le .part disparaît quand c'est fini)
            skip_parts = {"videos", "tg_tmp", "thumbs"}
            skip_ext = {".mp4", ".mov", ".zip"}
            n = 0
            part = dest.with_suffix(".part")
            try:
                with zipfile.ZipFile(part, "w", zipfile.ZIP_DEFLATED) as z:
                    for p in Path("data").rglob("*"):
                        if p.is_dir():
                            continue
                        rel = p.relative_to("data")
                        if (any(prt in skip_parts for prt in rel.parts)
                                or p.suffix.lower() in skip_ext):
                            continue
                        try:
                            z.write(p, str(rel))
                            n += 1
                        except Exception:
                            pass
                os.replace(str(part), str(dest))
                print(f"[backup] {dest.name} : {n} fichiers, "
                      f"{dest.stat().st_size / 1e6:.1f} Mo", flush=True)
            except Exception as e:
                print(f"[backup] échec : {type(e).__name__}: {e}", flush=True)
                try:
                    part.unlink()
                except Exception:
                    pass

        threading.Thread(target=_zip_bg, daemon=True).start()
        return jsonify({"ok": True, "lance": True, "fichier": str(dest),
                        "note": "Sauvegarde lancée en arrière-plan (~1-2 min). "
                                "Vérifie avec /admin/backup_data?list=1 : le zip "
                                "apparaît quand c'est terminé."})

    @app.route("/mypuls/pushs_refresh_probe")
    def mypuls_pushs_refresh_probe():
        """DÉCOUVERTE (lecture seule) : trouve la requête envoyée par le bouton
        orange « MAJ » de la page Pushs MyPuls, pour pouvoir l'automatiser
        chaque nuit. Récupère le HTML de /pushs (cookies du VPS) et liste les
        endpoints candidats (refresh/sync/update...) + le contexte du bouton."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False}), 401
        try:
            import mypuls
            if not mypuls.is_configured():
                return jsonify({"ok": False, "error": "Cookies MyPuls absents"})
            s = mypuls._make_session()
            cr = mypuls.list_creators()
            ids = list((cr.get("creators") or {}).items())
            if not ids:
                return jsonify({"ok": False, "error": f"Aucune créatrice : {cr.get('error')}"})
            name, cid = ids[0]
            s.get(f"{mypuls.BASE_URL}/switch-creator/{int(cid)}?from=app_pushs",
                  timeout=20, allow_redirects=True)
            r = s.get(f"{mypuls.BASE_URL}/pushs", timeout=20)
            if r.status_code != 200 or mypuls._detect_login_redirect(r.text):
                return jsonify({"ok": False, "error": f"HTTP {r.status_code} / login"})
            html = r.text
            hits = set()
            for pat in (r"(?:href|action|data-url|data-action|data-href|data-route)="
                        r"[\"']([^\"']*(?:refresh|sync|update|scrap|reload|maj)[^\"']*)[\"']",
                        r"fetch\([\"']([^\"']+)[\"']",
                        r"\$\.(?:get|post|ajax)\([\"']([^\"']+)[\"']",
                        r"axios\.[a-z]+\([\"']([^\"']+)[\"']"):
                for m in re.findall(pat, html, re.I):
                    hits.add(m)
            out = {"ok": True, "creatrice_test": name,
                   "candidats": sorted(hits)[:40]}
            i = html.find("MAJ")
            if i < 0:
                i = html.lower().find("nouveau push")
            out["contexte_bouton"] = (html[max(0, i - 900):i + 300]
                                      .replace("\n", " ")[:1400] if i >= 0 else "non trouvé")
            return jsonify(out)
        except Exception as e:
            return jsonify({"ok": False, "error": f"{type(e).__name__}: {e}"})

    @app.route("/mypuls/save_cookies", methods=["POST"])
    def mypuls_save_cookies():
        if not is_auth():
            return redirect("/")
        try:
            import mypuls
        except Exception as e:
            return _error(f"✕ Module mypuls indispo : {e}")
        phpsessid = (request.form.get("phpsessid") or "").strip()
        rememberme = (request.form.get("rememberme") or "").strip()
        if not phpsessid or len(phpsessid) < 16:
            return _error("✕ PHPSESSID invalide (au moins 16 caractères)")
        mypuls.save_cookies(phpsessid, rememberme)
        # Test immédiat
        res = mypuls.ping()
        if res.get("ok"):
            return _success(f"✓ Cookies MyPuls enregistrés. Connecté en tant que <code>{res.get('email', '?')}</code>")
        return _error(f"⚠ Cookies enregistrés mais ping échoué : {res.get('error', '?')}")

    @app.route("/mypuls/import_har", methods=["POST"])
    def mypuls_import_har():
        """Importe les cookies MyPuls (PHPSESSID + REMEMBERME) depuis un HAR
        exporté du navigateur (DevTools → Network → Export HAR), pour rafraîchir
        l'auth sans copier-coller à la main."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        try:
            import mypuls
            import json as _json
            import re as _re
        except Exception as e:
            return jsonify({"ok": False, "error": f"module: {e}"})
        f = request.files.get("har")
        if not f or not f.filename:
            return jsonify({"ok": False, "error": "Aucun fichier HAR"})
        try:
            har = _json.loads(f.read().decode("utf-8", "replace"))
        except Exception as e:
            return jsonify({"ok": False, "error": f"HAR illisible : {e}"})
        php = ""
        rem = ""
        for ent in har.get("log", {}).get("entries", []):
            if "mypuls.app" not in (ent.get("request", {}).get("url", "") or ""):
                continue
            for h in ent.get("request", {}).get("headers", []):
                if (h.get("name", "") or "").lower() == "cookie":
                    for part in (h.get("value", "") or "").split(";"):
                        if "=" in part:
                            k, v = part.strip().split("=", 1)
                            k = k.strip(); v = v.strip()
                            if k == "PHPSESSID" and v:
                                php = v
                            elif k == "REMEMBERME" and v:
                                rem = v
            for h in ent.get("response", {}).get("headers", []):
                if (h.get("name", "") or "").lower() == "set-cookie":
                    val = h.get("value", "") or ""
                    m = _re.search(r"REMEMBERME=([^;]+)", val)
                    if m:
                        rem = m.group(1)
                    m = _re.search(r"PHPSESSID=([^;]+)", val)
                    if m:
                        php = m.group(1)
        if not php or len(php) < 16:
            return jsonify({"ok": False, "error": "PHPSESSID introuvable dans ce HAR. Connecte-toi sur mypuls.app, ouvre DevTools → Network, recharge la page, puis Export HAR."})
        mypuls.save_cookies(php, rem)
        res = mypuls.ping()
        note = ""
        if not rem:
            note = " ⚠️ Aucun REMEMBERME dans ce HAR : l'auto-refresh ne pourra PAS garder la session vivante (elle expirera). Reconnecte-toi sur mypuls.app en cochant « rester connecté / remember me », puis ré-exporte le HAR."
        if res.get("ok"):
            return jsonify({"ok": True, "email": res.get("email", "?"), "rememberme": bool(rem), "note": note})
        return jsonify({"ok": False, "error": f"Cookies enregistrés mais ping échoué : {res.get('error', '?')}"})

