    @app.route("/jbactivite/cfg", methods=["POST"])
    def jbactivite_cfg():
        """Config par VA : base de paie, retenue par oubli, jours de repos."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False}), 401
        va = (request.form.get("va") or "").strip().lower()
        if not va:
            return jsonify({"ok": False, "error": "va manquant"})
        try:
            # Borne >= 0 côté SERVEUR : le min="0" du champ HTML n'est pas
            # appliqué (envoi via fetch/FormData). Un malus négatif donnait
            # « à payer » = base - (négatif) > base = un bonus au lieu d'une retenue.
            base = max(0.0, float(request.form.get("base") or 0))
            malus = max(0.0, float(request.form.get("malus") or 0))
        except Exception:
            return jsonify({"ok": False, "error": "montants invalides"})
        repos = sorted({int(x) for x in (request.form.get("repos") or "").split(",")
                        if x.strip().isdigit() and 0 <= int(x) <= 6})
        try:
            quota = max(0, int(float(request.form.get("quota") or 0)))
        except Exception:
            quota = 0
        try:
            quota_pct = min(100, max(1, int(float(request.form.get("quota_pct") or 100))))
        except Exception:
            quota_pct = 100
        cfg = _vaact_cfg_load()
        cadence = "m" if (request.form.get("cadence") or "q").strip() == "m" else "q"
        cfg.setdefault("vas", {})[va] = {"base": base, "malus": malus,
                                         "repos": repos, "quota": quota,
                                         "quota_pct": quota_pct, "cadence": cadence}
        _vaact_cfg_save(cfg)
        return jsonify({"ok": True})

    @app.route("/jailbreak/discord_debug")
    def jailbreak_discord_debug():
        """Diagnostic PP Discord : dit si le bot voit les membres et pourquoi un
        pseudo ne matche pas. Usage : /jailbreak/discord_debug?handle=fahnih_37050"""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False}), 401
        bot = _BOT_REF
        out = {
            "ok": True,
            "bot_connecte": bot is not None,
            "guilds": len(getattr(bot, "guilds", []) or []) if bot else 0,
            "membres_en_cache": sum(len(g.members) for g in (getattr(bot, "guilds", []) or [])) if bot else 0,
        }
        h = (request.args.get("handle") or "").strip().lstrip("@")
        if h and bot:
            info = _resolve_discord_user_by_handle(h)
            out["handle"] = h
            out["trouve"] = bool(info)
            out["resultat"] = info
            if not info:
                # propose les pseudos les plus proches (aide à trouver le bon)
                frag = _norm_handle(h)[:5]
                near = []
                try:
                    for g in bot.guilds:
                        for m in g.members:
                            for c in (getattr(m, "name", ""), getattr(m, "global_name", ""),
                                      getattr(m, "display_name", "")):
                                if c and frag and frag in _norm_handle(c):
                                    near.append(c)
                                    break
                            if len(near) >= 12:
                                break
                        if len(near) >= 12:
                            break
                except Exception:
                    pass
                out["pseudos_proches"] = sorted(set(near))[:12]
        return jsonify(out)

    def _pourquoi_rename_refuse(jb, identity, old_name, new_name):
        """Dit LAQUELLE des deux raisons a fait echouer le renommage.

        « Conflit de nom ou VA introuvable » ne disait pas laquelle : devant
        sept fois le meme message, on ne sait pas s'il faut changer de nom ou
        chercher pourquoi la fiche est invisible.
        """
        try:
            noms = {str(n).strip().lower()
                    for n in jb.list_va_names_for_identity(identity)}
        except Exception:
            return "Renommage refusé"
        n = (new_name or "").strip().lower()
        o = (old_name or "").strip().lower()
        if n and n != o and n in noms:
            return f"« {new_name} » existe déjà pour cette identité"
        if o not in noms:
            return f"« {old_name} » est introuvable dans cette identité"
        return "Renommage refusé"

    @app.route("/jailbreak/update_va", methods=["POST"])
    def jailbreak_update_va():
        if not is_auth():
            if request.form.get("ajax") == "1":
                from flask import jsonify
                return jsonify({"ok": False, "auth": True,
                                "error": "Session expirée — la page va se recharger"}), 401
            return redirect("/")
        try:
            import jailbreak as jb
        except Exception as e:
            return _error(f"✕ Module indispo : {e}", tab="jailbreak")
        identity = (request.form.get("identity") or "").strip().lower()
        old_name = (request.form.get("old_name") or "").strip()
        new_name = (request.form.get("new_name") or "").strip()
        # discord_username peut etre vide pour le retirer
        discord_username = (request.form.get("discord_username") or "").strip().lstrip("@")
        if not identity or not old_name:
            return _error("✕ Identité ou ancien nom manquant", tab="jailbreak")
        kwargs = {}
        if new_name:
            kwargs["new_name"] = new_name
        kwargs["discord_username"] = discord_username
        ok = jb.update_va(identity, old_name, **kwargs)
        # Push Sheet force, comme le fait deja la suppression juste en dessous.
        # Sans lui, le classeur garde l'ANCIEN nom jusqu'au push suivant, qui
        # est asynchrone, non force, et peut echouer sur quota ou mourir avec
        # un redemarrage. Le poller passe toutes les 2 min : il lisait donc
        # l'ancien nom et annulait le renommage. La pierre tombale couvre cette
        # fenetre, ce push la referme a la source.
        if ok and new_name:
            try:
                import sheets_sync, threading as _th_rn
                _snap_rn = jb._load()
                _th_rn.Thread(
                    target=lambda: sheets_sync.push_all(_snap_rn, force=True),
                    daemon=True, name="jb-renomme-sheet").start()
            except Exception:
                pass
        # AJAX : réponse instantanée (évite de re-rendre toute la page Jailbreak,
        # qui régénère des centaines de comptes -> c'était ça, la lenteur).
        if request.form.get("ajax"):
            from flask import jsonify
            # Résout la PP Discord TOUT DE SUITE (cache vidé pour ce pseudo, sinon
            # un ancien "introuvable" resterait collé 2 min) -> l'avatar se met à
            # jour sans recharger la page.
            avatar, found = "", False
            if discord_username:
                try:
                    _DISCORD_RESOLVE_CACHE.pop(discord_username.strip().lower(), None)
                    info = _resolve_discord_user_by_handle(discord_username)
                    if info:
                        found = True
                        avatar = info.get("avatar_url") or ""
                except Exception:
                    pass
            return jsonify({"ok": bool(ok), "name": new_name or old_name,
                            "discord": discord_username,
                            "avatar": avatar, "discord_found": found,
                            "error": "" if ok else _pourquoi_rename_refuse(
                                jb, identity, old_name, new_name)})
        if ok:
            return _success(f"✓ VA <b>{old_name}</b> mise à jour", tab="jailbreak")
        return _error("✕ Mise à jour échouée (conflit de nom ou VA introuvable)", tab="jailbreak")

