    @app.route("/textpool/ai_bios", methods=["POST"])
    def textpool_ai_bios():
        """Génère des bios Insta par IA (Claude) selon la model + son âge,
        et les ajoute au pool 'bios'. Clé : ANTHROPIC_API_KEY dans le .env."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        identity = (request.form.get("identity") or "").strip()
        age = (request.form.get("age") or "21").strip()
        try:
            count = max(1, min(15, int(request.form.get("count") or 6)))
        except Exception:
            count = 6
        key = (os.environ.get("ANTHROPIC_API_KEY") or "").strip()
        if not key:
            for line in _read_env_lines():
                if line.strip().startswith("ANTHROPIC_API_KEY="):
                    key = line.strip().split("=", 1)[1].strip()
                    break
        if not key:
            return jsonify({"ok": False, "error": "Clé IA manquante : ajoute ANTHROPIC_API_KEY=sk-ant-... dans le .env du VPS (console.anthropic.com)"})
        # Les bios EXISTANTES de la model servent de référence de style : l'IA
        # génère « du même style, jamais la même » (demande user).
        _examples = []
        try:
            import text_pool as _tpx
            _examples = [str(e.get("text") or "").strip()
                         for e in _tpx.list_entries("bios", identity=identity.lower())
                         if str(e.get("text") or "").strip()][-15:]
        except Exception:
            _examples = []
        # Exemples FOURNIS dans le formulaire : ils PRIMENT sur les bios en base
        # (cas d'une model qui n'en a encore aucune).
        # ⚠️ Une bio Insta tient sur PLUSIEURS lignes -> le séparateur est une
        # LIGNE VIDE, pas le retour à la ligne. Sans ligne vide, on retombe sur
        # « une par ligne » (compatible avec l'ancien usage).
        _raw_seed = (request.form.get("seed") or "").replace("\r\n", "\n")
        if "\n\n" in _raw_seed:
            _seed = [b.strip() for b in re.split(r"\n\s*\n", _raw_seed) if b.strip()][:20]
        else:
            _seed = [l.strip() for l in _raw_seed.splitlines() if l.strip()][:20]
        if _seed:
            _examples = _seed + [t for t in _examples if t not in _seed]
        _ex_block = ""
        if _examples:
            _src = ("que TU as fournies — c'est EXACTEMENT ce style qu'il faut"
                    if _seed else "EXISTANTES de cette model — c'est LE style à imiter")
            _ex_block = (
                f"Voici des bios {_src} (ton, longueur, emojis, vibe) :\n"
                + "\n".join("- " + t for t in _examples)
                + "\nGénère de NOUVELLES bios dans ce MÊME style, mais JAMAIS identiques "
                "ni quasi identiques à celles ci-dessus.\n"
            )
        prompt = (
            f"Tu écris des bios Instagram pour le compte d'une créatrice/modèle.\n"
            f"Identité : {identity or 'une jeune femme française'} — Âge : {age} ans.\n"
            + _ex_block +
            f"Génère exactement {count} bios DIFFÉRENTES.\n"
            "FORMAT DE RÉPONSE : sépare chaque bio par une LIGNE VIDE. Une bio peut "
            "elle-même tenir sur plusieurs lignes (comme une vraie bio Instagram). "
            "Pas de numérotation, pas de tirets, pas de guillemets.\n"
            "Contraintes STRICTES :\n"
            "- max 140 caractères chacune (sauts de ligne compris)\n"
            "- style fille jeune, française, naturelle (pas commercial)\n"
            "- quelques emojis bien placés (🇫🇷 💌 ☀️ 🤍 …)\n"
            "- varie les styles : mystérieuse, fun, directe, minimaliste\n"
            "- mentionne l'âge dans certaines (ex: « 21 · Paris »)\n"
            "- AUCUNE mention d'OnlyFans/MYM/lien, aucun mot risqué pour Instagram\n"
            "Réponds UNIQUEMENT avec les bios, une par ligne."
        )
        try:
            import requests as _rq
            r = _rq.post(
                "https://api.anthropic.com/v1/messages",
                headers={"x-api-key": key, "anthropic-version": "2023-06-01",
                         "content-type": "application/json"},
                json={"model": "claude-haiku-4-5", "max_tokens": 1200,
                      "messages": [{"role": "user", "content": prompt}]},
                timeout=60,
            )
            data = r.json()
            if r.status_code != 200:
                err = (data.get("error") or {}).get("message") or f"HTTP {r.status_code}"
                return jsonify({"ok": False, "error": f"API Claude : {err}"})
            text = "".join(b.get("text", "") for b in (data.get("content") or []))
        except Exception as e:
            return jsonify({"ok": False, "error": f"Appel IA échoué : {e}"})
        import text_pool as tp
        added = 0
        _seen = {t.lower() for t in _examples}
        # Blocs séparés par une ligne vide (une bio = potentiellement plusieurs
        # lignes) ; si l'IA a répondu à l'ancienne (1 par ligne), ça marche aussi.
        _blocks = [b for b in re.split(r"\n\s*\n", text.replace("\r\n", "\n")) if b.strip()]
        if len(_blocks) <= 1:
            _blocks = text.splitlines()
        for line in _blocks:
            # Nettoyage PRUDENT : on retire « 1. », « 2) », « - », « • » en tête
            # de bloc, mais JAMAIS un âge nu (« 18 🎀 … » doit rester intact).
            _ls = [l.strip().strip("\"'") for l in line.strip().splitlines() if l.strip()]
            if _ls:
                _ls[0] = re.sub(r"^(?:\d{1,2}\s*[.)]\s+|[-•*]\s+)", "", _ls[0]).strip()
            line = "\n".join(_ls)
            if not (5 <= len(line) <= 150):
                continue
            if line.lower() in _seen:      # jamais deux fois la même
                continue
            try:
                # bios générées ASSIGNÉES à la model (onglet Bios par identité)
                if tp.add_entry("bios", line, identity=identity.lower()).get("ok"):
                    added += 1
            except Exception:
                pass
            if added >= count:
                break
        if not added:
            return jsonify({"ok": False, "error": "L'IA n'a rien renvoyé d'utilisable, réessaie"})
        return jsonify({"ok": True, "added": added})

