    @app.route("/textpool/vault_add", methods=["POST"])
    def textpool_vault_add():
        """Ajout depuis les onglets Bios/CTA : liste de textes (un champ par
        texte, multi-ligne autorisé DANS un texte), assignés à une identité
        (« _pool_ » ou vide = pool commun)."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        try:
            import text_pool as tp
        except Exception as e:
            return jsonify({"ok": False, "error": f"module indispo: {e}"})
        import json as _js
        cat = (request.form.get("category") or "").strip()
        ident = (request.form.get("identity") or "").strip().lower()
        if ident == "_pool_":
            ident = ""
        if ident and ident not in _list_identities():
            return jsonify({"ok": False, "error": "identité inconnue"})
        try:
            texts = _js.loads(request.form.get("texts") or "[]")
        except Exception:
            return jsonify({"ok": False, "error": "JSON invalide"})
        if not isinstance(texts, list) or not texts:
            return jsonify({"ok": False, "error": "aucun texte"})
        added = dupes = 0
        vus = set()
        for t in texts[:500]:
            # doublon DANS le lot colle : deux fois la meme ligne dans le
            # presse-papier ne doit compter qu'une fois
            cle = tp.norm_texte(str(t))
            if cle and cle in vus:
                dupes += 1
                continue
            vus.add(cle)
            res = tp.add_entry(cat, str(t), identity=ident)
            if res.get("ok"):
                added += 1
            elif res.get("error") == "already_exists":
                dupes += 1
        _invalidate_all_ttl_cache()
        return jsonify({"ok": True, "added": added, "duplicates": dupes})

    @app.route("/textpool/share", methods=["POST"])
    def textpool_share():
        """Copie des textes (Bios / CTA) vers d'autres identités. COPIE : les
        originaux restent en place, les doublons sont ignorés."""
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        try:
            import text_pool as tp
        except Exception as e:
            return jsonify({"ok": False, "error": f"module indispo: {e}"})
        import json as _js
        cat = (request.form.get("category") or "").strip()
        try:
            ids = set(_js.loads(request.form.get("ids") or "[]"))
            cibles = [str(t).strip().lower()
                      for t in _js.loads(request.form.get("targets") or "[]")]
        except Exception:
            return jsonify({"ok": False, "error": "JSON invalide"})
        if not ids or not cibles:
            return jsonify({"ok": False, "error": "rien à copier"})
        connues = set(_list_identities())
        cibles = [t for t in cibles if t in connues]
        if not cibles:
            return jsonify({"ok": False, "error": "identité(s) inconnue(s)"})
        textes = [str(e.get("text") or "") for e in tp.list_entries(cat)
                  if str(e.get("id")) in ids]
        if not textes:
            return jsonify({"ok": False, "error": "textes introuvables"})
        copies = dupes = 0
        for cible in cibles:
            for txt in textes:
                res = tp.add_entry(cat, txt, identity=cible)
                if res.get("ok"):
                    copies += 1
                elif res.get("error") == "already_exists":
                    dupes += 1
        _invalidate_all_ttl_cache()
        return jsonify({"ok": True, "copied": copies, "duplicates": dupes})

