    @app.route("/veille/send_banger", methods=["POST"])
    def veille_send_banger():
        """Envoie un reel (en VIDEO) dans le salon banger-{identity} Discord.

        Sert a stocker les MEILLEURS reels par identite. Telecharge via yt-dlp
        (methode primaire), puis poste le fichier dans le salon banger associe.
        """
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        try:
            import veille
            import veille_telegram
        except Exception as e:
            return jsonify({"ok": False, "error": f"module indispo: {e}"})
        rid = (request.form.get("reel_id") or "").strip()
        identity = (request.form.get("identity") or "").strip()
        if not rid or not identity:
            return jsonify({"ok": False, "error": "reel_id + identity requis"})
        reel = veille.get_reel(rid)
        if not reel:
            return jsonify({"ok": False, "error": "Reel introuvable"})
        url = (reel.get("url") or "").strip()
        # 0) CACHE DISQUE d'abord (data/insta/videos/{sc}.mp4, partagé avec la
        # lecture et la veille) : un reel déjà téléchargé part sans yt-dlp.
        # (Le file_id Telegram ne sert PAS ici : le banger poste sur DISCORD,
        # qui a besoin des octets — et getFile Telegram est plafonné à 20 Mo.)
        info = {}
        video_bytes = None
        _scb = re.search(r'/(?:p|reel|reels)/([A-Za-z0-9_-]+)', url or "")
        if _scb:
            _fcb = Path("data/insta/videos") / f"{_scb.group(1)}.mp4"
            if _fcb.exists() and 1024 < _fcb.stat().st_size <= 50 * 1024 * 1024:
                try:
                    video_bytes = _fcb.read_bytes()
                except Exception:
                    video_bytes = None
        # 1) Download : yt-dlp (le plus fiable), puis la chaine de secours
        if not video_bytes:
            video_bytes = veille_telegram.download_via_ytdlp(url, info=info) if url else None
        if not video_bytes and info.get("reason") not in ("audience_restreinte", "trop_gros_50mb"):
            fresh = veille_telegram.refresh_post_data(url, owner=reel.get("owner", "")) if url else {}
            vu = (fresh.get("video_url") or reel.get("video_url") or "").strip()
            if vu:
                video_bytes = veille_telegram.download_video_bytes(vu, info=info)
        if not video_bytes:
            reason = info.get("reason") or "video indisponible"
            return jsonify({"ok": False, "error": f"Telechargement impossible ({reason})"})
        caption = (reel.get("caption") or "").strip()
        ok, msg = _send_video_to_banger_channel(
            identity, video_bytes, filename=f"banger_{rid}.mp4", caption=caption
        )
        if ok:
            return jsonify({"ok": True, "channel": msg, "identity": identity})
        return jsonify({"ok": False, "error": msg})

    @app.route("/veille/send_day", methods=["POST"])
    def veille_send_day():
        if not is_auth():
            from flask import jsonify
            return jsonify({"ok": False, "error": "unauth"}), 401
        from flask import jsonify
        try:
            import veille
            import veille_telegram
        except Exception as e:
            return jsonify({"ok": False, "error": f"module indispo: {e}"})
        day = (request.form.get("day") or "").strip()
        if not day:
            return jsonify({"ok": False, "error": "day manquant"})
        if not veille_telegram.is_configured():
            return jsonify({"ok": False, "error": "Bot Telegram non configuré"})
        by_day = veille.reels_by_day()
        reels = by_day.get(day, [])
        # sent/failed = partition des REELS (posté / non posté) ; fwd_failed =
        # forwards modèles ratés (ne doit pas polluer failed, sinon sent+failed
        # dépasse le nb de reels).
        sent, failed, fwd_failed = 0, 0, 0
        for r in reels:
            if r.get("sent_to_telegram"):
                continue
            url = (r.get("url") or "").strip()
            # Un reel déjà uploadé (file_id central) ou déjà sur disque n'a
            # besoin d'AUCUNE re-résolution RapidAPI+instaloader (2-10 s/reel) :
            # cette cascade ne sert qu'aux reels froids sans caption/video_url.
            _scm2 = re.search(r'/(?:p|reel|reels)/([A-Za-z0-9_-]+)', url or "")
            _sc2 = _scm2.group(1) if _scm2 else ""
            _has_asset = bool(
                (r.get("tg_file_id") or "").strip()
                or (_sc2 and veille_telegram.fileid_get(_sc2))
                or (_sc2 and (Path("data/insta/videos") / f"{_sc2}.mp4").exists()))
            if url and not _has_asset and (not (r.get("caption") or "").strip()
                                           or not (r.get("video_url") or "").strip()):
                fresh = veille_telegram.refresh_post_data(url, owner=r.get("owner", ""))
                if fresh.get("caption") and not (r.get("caption") or "").strip():
                    r["caption"] = fresh["caption"]
                    veille.update_reel(r["id"], caption=fresh["caption"])
                if fresh.get("video_url"):
                    r["video_url"] = fresh["video_url"]
            caption = _veille_caption(r)
            description = (r.get("caption") or "").strip()
            _dfinal = False
            # brouillon « prêt » : le draft fait foi (comme /veille/send), même vide
            if r.get("prepared") and "prep_desc" in r:
                description = (r.get("prep_desc") or "").strip()
                _dfinal = True
            # capture du brouillon AVANT l'envoi (clear_prepared le supprimera)
            _pm = [m.strip().lower() for m in (r.get("prep_models") or "").split(",")
                   if m.strip()] if r.get("prepared") else []
            _pov = r.get("prep_overlay") if (r.get("prepared") and (r.get("prep_overlay") or "").strip()) else None
            res = veille_telegram.send_video_from_url(
                r.get("video_url", ""),
                caption=caption,
                fallback_url=url,
                followup_text=description,
                owner=r.get("owner", ""),
                tg_file_id=(r.get("tg_file_id") or ""),
                followup_final=_dfinal,
            )
            if res.get("ok"):
                veille.mark_sent(r["id"])
                # aligné sur /veille/send : on persiste ce que l'envoi a appris
                # (file_id -> renvois instantanés ; description ; message Veille)
                try:
                    _u = {}
                    if res.get("tg_file_id"):
                        _u["tg_file_id"] = res["tg_file_id"]
                    if res.get("chat_id") and res.get("message_id"):
                        _u["veille_chat_id"] = res["chat_id"]
                        _u["veille_msg_id"] = res["message_id"]
                    if res.get("description") and not (r.get("caption") or "").strip():
                        _u["caption"] = res["description"]
                    if _u:
                        veille.update_reel(r["id"], **_u)
                except Exception:
                    pass
                # forward AUSSI aux modèles du brouillon (comme /veille/send) puis
                # purge le brouillon -> plus de draft fantôme après envoi.
                _fid = res.get("tg_file_id") or r.get("tg_file_id") or ""
                if _pm and res.get("mode") == "video" and _fid:
                    try:
                        import tg_router
                        for m in _pm:
                            try:
                                r2 = tg_router.send_veille_to_model(
                                    m, _fid, link=url, desc=description, overlay=_pov,
                                    src_chat_id=res.get("chat_id"),
                                    src_msg_id=res.get("message_id"))
                                if not r2.get("ok"):
                                    fwd_failed += 1
                            except Exception:
                                fwd_failed += 1
                    except Exception:
                        pass
                try:
                    veille.clear_prepared(r["id"])
                except Exception:
                    pass
                sent += 1
            else:
                failed += 1
        return jsonify({"ok": True, "sent": sent, "failed": failed, "forward_failed": fwd_failed})

    @app.route("/settings/veille_telegram", methods=["POST"])
    def settings_veille_telegram():
        if not is_auth():
            return redirect("/")
        try:
            import veille_telegram
        except Exception as e:
            return _error(f"✕ Module veille_telegram indispo : {e}", tab="vtg")
        bot_token = (request.form.get("bot_token") or "").strip()
