    @app.route("/mypulslive/push", methods=["POST"])
    def mypulslive_push():
        if not is_auth():
            return redirect("/")
        try:
            import mypuls_scheduler
        except Exception as e:
            return _error(f"✕ Module mypuls_scheduler indispo : {e}", tab="mypulslive")

        try:
            creator_id = int(request.form.get("creator_id") or 0)
        except Exception:
            return _error("✕ Createur invalide", tab="mypulslive")
        if not creator_id:
            return _error("✕ Createur manquant", tab="mypulslive")

        content_type = (request.form.get("content_type") or "both").strip()
        date_start = (request.form.get("date_start") or "").strip()
        date_end = (request.form.get("date_end") or "").strip()
        infinite_mode = (request.form.get("infinite_mode") or "0") == "1"
        post_slots_raw = request.form.get("post_slots_json") or "[]"
        story_slots_raw = request.form.get("story_slots_json") or "[]"
        media_ids_raw = request.form.get("media_ids") or ""
        captions_raw = request.form.get("captions") or ""
        post_action = (request.form.get("post_action") or "delete").strip()
        try:
            post_delete_days = int(request.form.get("post_delete_days") or 2)
        except Exception:
            post_delete_days = 2
        delay_sec = max(1, post_delete_days) * 86400
        # Options toggles
        shuffle_media = (request.form.get("shuffle_media") or "0") == "1"
        randomize_minutes = (request.form.get("randomize_minutes") or "1") == "1"
        # infinite_recycle est l'algorithme par defaut (cycle via modulo) - le flag
        # est pour info, le code recycle de toute facon
        import json as _json
        try:
            post_slots = _json.loads(post_slots_raw)
            if not isinstance(post_slots, list):
                post_slots = []
        except Exception:
            post_slots = []
        try:
            story_slots = _json.loads(story_slots_raw)
            if not isinstance(story_slots, list):
                story_slots = []
        except Exception:
            story_slots = []

        if not date_start:
            return _error("✕ Date de debut manquante", tab="mypulslive")
        if not infinite_mode and not date_end:
            return _error("✕ Date de fin manquante (sinon active Mode infini)", tab="mypulslive")

        def _parse_lines(raw):
            return [ln.strip() for ln in (raw or "").splitlines() if ln.strip()]

        media_ids_str = _parse_lines(media_ids_raw)
        try:
            media_ids = [int(m) for m in media_ids_str]
        except Exception:
            return _error("✕ media_ids doivent etre des entiers", tab="mypulslive")
        if not media_ids:
            return _error("✕ Aucun media_id", tab="mypulslive")

        captions = _parse_lines(captions_raw) or [""]

        # === Mode INFINI : creer une (ou 2) campagnes au lieu d un push one-shot ===
        if infinite_mode:
            try:
                import mypuls_campaigns
                import mypuls
            except Exception as e:
                return _error(f"✕ Module campagnes indispo : {e}", tab="mypulslive")
            creators = mypuls.list_creators().get("creators", {})
            cname = ""
            for n, cid in creators.items():
                if int(cid) == creator_id:
                    cname = n
                    break
            # Pour chaque type configure (post / story), on cree une campagne.
            # content_type="both" -> 2 campagnes si les 2 slots sont remplis.
            campaigns_to_create = []
            if content_type in ("post", "both") and post_slots:
                campaigns_to_create.append(("post", post_slots))
            if content_type in ("story", "both") and story_slots:
                campaigns_to_create.append(("story", story_slots))
            if not campaigns_to_create:
                return _error(
                    "✕ Mode infini : configure au moins un slot post ou story (et clique sur l'onglet correspondant)",
                    tab="mypulslive",
                )
            results = []
            for ctype, slots in campaigns_to_create:
                res = mypuls_campaigns.create_campaign(
                    creator_id=creator_id,
                    creator_name=cname,
                    campaign_type=ctype,
                    slots=slots,
                    media_ids=media_ids,
                    captions=captions,
                    options={"shuffle_media": shuffle_media, "randomize_minutes": randomize_minutes},
                    post_action=post_action,
                    delay_sec=delay_sec,
                    start_date=date_start,
                )
                if not res.get("ok"):
                    return _error(f"✕ Creation campagne {ctype} : {res.get('error', '?')}", tab="mypulslive")
                results.append((ctype, res.get("planned", 0)))
            msg_parts = [f"♾️ {n} {ct}(s) sur les 2 prochains jours" for ct, n in results]
            return _success(
                f"Campagne(s) lancée(s) pour <b>{cname}</b> : "
                + " · ".join(msg_parts)
                + ". Le cron étend de 2 jours toutes les heures.",
                tab="mypulslive",
            )

        summary_parts = []
        all_errors = []

        # Story push
        if content_type in ("story", "both") and story_slots:
            # story_slots est une liste de "HH:MM" strings
            res = mypuls_scheduler.bulk_schedule_stories(
                creator_id=creator_id,
                media_ids=media_ids,
                date_start=date_start,
                date_end=date_end,
                story_slots=story_slots,
                shuffle_media=shuffle_media,
                randomize_minutes=randomize_minutes,
            )
            summary_parts.append(
                f"▭ Stories : {res.get('planned', 0)} OK / {res.get('failed', 0)} fail"
            )
            if res.get("errors"):
                all_errors.extend(res["errors"][:3])

        # Post push
        if content_type in ("post", "both") and post_slots:
            # post_slots est [{time:"HH:MM", visibility:"public"|"private"}, ...]
            res = mypuls_scheduler.bulk_schedule_posts(
                creator_id=creator_id,
                media_ids=media_ids,
                captions=captions,
                date_start=date_start,
                date_end=date_end,
                post_slots=post_slots,
                action=post_action,
                delay_sec=delay_sec,
                shuffle_media=shuffle_media,
                randomize_minutes=randomize_minutes,
            )
            summary_parts.append(
                f"📰 Posts : {res.get('planned', 0)} OK / {res.get('failed', 0)} fail"
            )
            if res.get("errors"):
                all_errors.extend(res["errors"][:3])

        if not summary_parts:
            return _error("✕ Aucun slot configure pour le type choisi", tab="mypulslive")

        msg = "✓ Push live termine — " + " | ".join(summary_parts)
        if all_errors:
            msg += " | Premieres erreurs : " + "; ".join(all_errors[:3])
        return _success(msg, tab="mypulslive")

    # ============ BULK DELETE ALL CREATORS — async with progress polling ============
    # Le bulk delete peut prendre 5+ minutes (1 list + N delete per creator).
    # On le fait en background thread + endpoint de status pour feedback temps reel.
    # _BULK_DELETE_JOBS : {job_id: {status, creators_scanned, total, current,
    #   deleted, failed, errors, cancelled, started_at}}
    if not hasattr(app, "_bulk_delete_jobs"):
        app._bulk_delete_jobs = {}
        app._bulk_delete_lock = threading.Lock()

    def _run_bulk_delete_job(job_id, creator_ids, start_iso, end_iso):
        """Worker thread : phase 1 list events, phase 2 delete events."""
        import mypuls_scheduler
        job = app._bulk_delete_jobs[job_id]
        try:
            # Phase 1 : list
            job["status"] = "listing"
            all_events = []  # [(creator_id, event_id), ...]
            for cid in creator_ids:
                if job["cancelled"]:
                    job["status"] = "cancelled"
                    return
                try:
                    lst = mypuls_scheduler.list_calendar_events([cid], start_iso, end_iso)
                    if lst.get("ok"):
                        for ev in lst.get("events") or []:
                            eid = ev.get("id")
                            if eid:
                                all_events.append((cid, int(eid)))
                    else:
                        job["errors"].append(f"#{cid} list: {lst.get('error', '?')}")
                except Exception as e:
                    job["errors"].append(f"#{cid} list err: {e}")
                job["creators_scanned"] += 1
            job["total"] = len(all_events)
            # Phase 2 : delete
            job["status"] = "deleting"
            for cid, eid in all_events:
                if job["cancelled"]:
                    job["status"] = "cancelled"
                    return
                try:
                    res = mypuls_scheduler.delete_event(eid)
                    if res.get("ok"):
                        job["deleted"] += 1
                    else:
                        job["failed"] += 1
                        if len(job["errors"]) < 20:
                            job["errors"].append(f"#{cid} ev#{eid}: {res.get('error', '?')}")
                except Exception as e:
                    job["failed"] += 1
                    if len(job["errors"]) < 20:
                        job["errors"].append(f"#{cid} ev#{eid}: {e}")
                job["current"] += 1
            job["status"] = "done"
        except Exception as e:
            job["status"] = "error"
            job["errors"].append(f"fatal: {e}")
        finally:
            import time as _t
            job["finished_at"] = _t.time()

    @app.route("/mypulslive/delete_all_creators/start", methods=["POST"])
    def mypulslive_delete_all_creators_start():
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        try:
            import mypuls_creator_settings as mcs
            import seed_media_pools
        except Exception as e:
            return jsonify({"ok": False, "error": f"module indispo : {e}"})

        g = mcs.get_global_settings()
        date_start = (g.get("start_date") or "").strip()
        date_end = (g.get("end_date") or "").strip()
        body = (request.get_json(silent=True) or {})
        if body.get("start_date"): date_start = body["start_date"]
        if body.get("end_date"): date_end = body["end_date"]
        if not date_start or not date_end:
            return jsonify({"ok": False, "error": "Dates manquantes"})

        start_iso = f"{date_start}T00:00:00"
        end_iso = f"{date_end}T23:59:59"
        creator_ids = list(seed_media_pools.MEDIA_SEEDS.keys())

        import uuid, time as _t
        job_id = uuid.uuid4().hex[:12]
        with app._bulk_delete_lock:
            # Cleanup vieux jobs (> 1h) pour pas que la dict grossisse a l infini
            now = _t.time()
            old = [k for k, v in app._bulk_delete_jobs.items() if v.get("finished_at", now) < now - 3600]
            for k in old:
                app._bulk_delete_jobs.pop(k, None)
            app._bulk_delete_jobs[job_id] = {
                "status": "queued",
                "creators_scanned": 0,
                "total": 0,
                "current": 0,
                "deleted": 0,
                "failed": 0,
                "errors": [],
                "cancelled": False,
                "started_at": _t.time(),
                "creators_count": len(creator_ids),
                "date_start": date_start,
                "date_end": date_end,
            }
        threading.Thread(
            target=_run_bulk_delete_job,
            args=(job_id, creator_ids, start_iso, end_iso),
            daemon=True,
            name=f"bulk-delete-{job_id}",
        ).start()
        return jsonify({"ok": True, "job_id": job_id})

    @app.route("/mypulslive/delete_all_creators/status/<job_id>", methods=["GET"])
    def mypulslive_delete_all_creators_status(job_id):
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        job = app._bulk_delete_jobs.get(job_id)
        if not job:
            return jsonify({"ok": False, "error": "job introuvable (peut-etre expire)"})
        # Renvoie une copie sans champs internes
        return jsonify({
            "ok": True,
            "job": {k: v for k, v in job.items() if k != "cancelled"},
        })

    @app.route("/mypulslive/delete_all_creators/cancel/<job_id>", methods=["POST"])
    def mypulslive_delete_all_creators_cancel(job_id):
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        job = app._bulk_delete_jobs.get(job_id)
        if not job:
            return jsonify({"ok": False, "error": "job introuvable"})
        job["cancelled"] = True
        return jsonify({"ok": True})

    @app.route("/mypulslive/push_all_creators", methods=["POST"])
    def mypulslive_push_all_creators():
        """Bulk push : applique le planning GLOBAL (slots + dates) a tous les
        createurs qui ont au moins 1 media_pool_posts dans leur config.

        Utilise par le bouton 'Pousser tous les createurs' pour eviter de
        cliquer 9x. Operation potentiellement longue -> renvoie JSON pour
        que le front affiche un loader.
        """
        from flask import jsonify
        if not is_auth():
            return jsonify({"ok": False, "error": "unauth"}), 401
        try:
            import mypuls_creator_settings as mcs
            import mypuls_scheduler
            import seed_media_pools
        except Exception as e:
            return jsonify({"ok": False, "error": f"module indispo : {e}"})

        # Lit le planning GLOBAL (slots + dates)
        g = mcs.get_global_settings()
        post_slots = (g.get("posts") or {}).get("slots") or []
        story_slots = (g.get("stories") or {}).get("slots") or []
        date_start = (g.get("start_date") or "").strip()
        date_end = (g.get("end_date") or "").strip()
        if not date_start or not date_end:
            return jsonify({"ok": False, "error": "Dates globales non configurees"})
        if not post_slots and not story_slots:
            return jsonify({"ok": False, "error": "Aucun slot global configure"})

        # Stories : convertir au format attendu par bulk_schedule_stories
        # ([{time:"HH:MM", audience:"..."}] -> [{time:"HH:MM", audience:"..."}])
        # (les audiences sont preservees telles quelles)

        creator_ids = list(seed_media_pools.MEDIA_SEEDS.keys())
        results = []
        total_planned_posts = 0
        total_planned_stories = 0
        total_failed = 0
        first_errors: list = []

        for cid in creator_ids:
            try:
                c_settings = mcs.get_creator_settings(cid)
                media_pool = c_settings.get("media_pool_posts") or []
                captions = c_settings.get("captions") or [""]
                if not media_pool:
                    results.append({"cid": cid, "skip": "no_media"})
                    continue
                # Cast media_ids en int (le scheduler veut des ints)
                try:
                    media_ids = [int(m) for m in media_pool]
                except Exception:
                    results.append({"cid": cid, "skip": "bad_media_ids"})
                    continue
                summary = {"cid": cid, "posts": 0, "stories": 0, "failed": 0}
                # Push posts
                if post_slots:
                    res = mypuls_scheduler.bulk_schedule_posts(
                        creator_id=cid,
                        media_ids=media_ids,
                        captions=captions,
                        date_start=date_start,
                        date_end=date_end,
                        post_slots=post_slots,
                        action="delete",
                        delay_sec=172800,
                        shuffle_media=False,
                        randomize_minutes=True,
                    )
                    summary["posts"] = res.get("planned", 0)
                    summary["failed"] += res.get("failed", 0)
                    total_planned_posts += summary["posts"]
                    total_failed += res.get("failed", 0)
                    if res.get("errors"):
                        first_errors.extend(res["errors"][:2])
                # Push stories
                if story_slots:
                    res = mypuls_scheduler.bulk_schedule_stories(
                        creator_id=cid,
                        media_ids=media_ids,
                        date_start=date_start,
                        date_end=date_end,
                        story_slots=story_slots,
                        shuffle_media=False,
                        randomize_minutes=True,
                    )
                    summary["stories"] = res.get("planned", 0)
                    summary["failed"] += res.get("failed", 0)
                    total_planned_stories += summary["stories"]
                    total_failed += res.get("failed", 0)
                    if res.get("errors"):
                        first_errors.extend(res["errors"][:2])
                results.append(summary)
            except Exception as e:
                results.append({"cid": cid, "error": str(e)})
                first_errors.append(f"#{cid}: {e}")

        return jsonify({
            "ok": True,
            "summary": {
                "creators_processed": len([r for r in results if "posts" in r or "stories" in r]),
                "creators_skipped": len([r for r in results if "skip" in r]),
                "total_posts_planned": total_planned_posts,
                "total_stories_planned": total_planned_stories,
                "total_failed": total_failed,
                "date_start": date_start,
                "date_end": date_end,
            },
            "results": results,
            "first_errors": first_errors[:10],
        })

    @app.route("/schedule/generate", methods=["POST"])
    def schedule_generate():
        if not is_auth():
            return redirect("/")
        try:
            import schedule_xlsx
        except Exception as e:
            return _error(f"✕ Module schedule_xlsx indispo (pip install openpyxl ?) : {e}", tab="schedule")

        model_name = (request.form.get("model_name") or "").strip()
        date_start = (request.form.get("date_start") or "").strip()
        date_end = (request.form.get("date_end") or "").strip()
        public_hours = (request.form.get("public_hours") or "").strip()
        private_hours = (request.form.get("private_hours") or "").strip()
        media_ids = request.form.get("media_ids") or ""
        captions = request.form.get("captions") or ""
        # Toggles (style MyPuls Live) : checked == "on" pour les checkboxes
        # On accepte aussi "1" pour compat avec des inputs hidden
        def _flag(name, default=False):
            v = (request.form.get(name) or "").strip().lower()
            if v in ("on", "1", "true", "yes"): return True
            if v in ("off", "0", "false", "no", ""):
                return default if v == "" else False
            return default
        recycle_infinite = _flag("recycle_infinite", default=True)
        shuffle_media = _flag("shuffle_media", default=False)
        randomize_minutes = _flag("randomize_minutes", default=True)
        # Stories : JSON [{time:"HH:MM", audience:"everyone"|"subscribers"|...}]
        # Si absent ou liste vide -> pas de sheet Stories generee.
        story_slots_raw = request.form.get("story_slots_json") or "[]"
        import json as _json_sx
        try:
            story_slots_list = _json_sx.loads(story_slots_raw)
            if not isinstance(story_slots_list, list):
                story_slots_list = []
        except Exception:
            story_slots_list = []

        if not model_name:
            return _error("✕ Nom du modele manquant", tab="schedule")
        if not date_start or not date_end:
            return _error("✕ Dates manquantes", tab="schedule")
        if not media_ids.strip():
            return _error("✕ Aucun media_id fourni", tab="schedule")
        if not public_hours and not private_hours and not story_slots_list:
            return _error("✕ Au moins un slot (post public/prive ou story) doit etre indique", tab="schedule")

        try:
            xlsx_bytes, filename = schedule_xlsx.generate_xlsx(
                model_name=model_name,
                date_start=date_start,
                date_end=date_end,
                public_hours_raw=public_hours,
                private_hours_raw=private_hours,
                media_ids_raw=media_ids,
                captions_raw=captions,
                story_slots=story_slots_list,
                recycle_infinite=recycle_infinite,
                shuffle_media=shuffle_media,
                randomize_minutes=randomize_minutes,
            )
        except ValueError as e:
            return _error(f"✕ {e}", tab="schedule")
        except Exception as e:
            return _error(f"✕ Generation echouee : {type(e).__name__}: {e}", tab="schedule")

        from flask import Response
        resp = Response(
            xlsx_bytes,
            mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        )
        # ASCII-safe disposition (RFC 5987 for unicode filename)
        try:
            ascii_name = filename.encode("ascii", "ignore").decode("ascii") or "template_import.xlsx"
        except Exception:
            ascii_name = "template_import.xlsx"
        from urllib.parse import quote
        resp.headers["Content-Disposition"] = (
            f"attachment; filename=\"{ascii_name}\"; filename*=UTF-8''" + quote(filename)
        )
        return resp

