    @app.route("/settings/role/permissions", methods=["GET", "POST"])
    def settings_role_permissions():
        if not is_auth():
            from flask import jsonify
            return jsonify({"error": "auth required"}), 401
        from flask import jsonify
        # Clé CANONIQUE des deux côtés (_role_key) : sinon on enregistrait sous
        # « VA JB » et le gating relisait « va jb » -> droits jamais appliqués.
        if request.method == "GET":
            key = _role_key(request.args.get("key"))
            if not key:
                return jsonify({"error": "key required"}), 400
            defs = _load_role_definitions()
            perms = defs.get(key, {}).get("permissions", {})
            return jsonify({"key": key, "permissions": perms})
        # POST
        key = _role_key(request.form.get("role_key"))
        if not key:
            return jsonify({"error": "key required"}), 400
        perms_json = request.form.get("permissions") or "{}"
        try:
            perms = json.loads(perms_json)
        except Exception:
            return jsonify({"error": "invalid permissions JSON"}), 400
        defs = _load_role_definitions()
        if key not in defs:
            defs[key] = {}
        defs[key]["permissions"] = perms
        _save_role_definitions(defs)
        # Les rendus en cache peuvent contenir l'ANCIENNE sidebar/onglets de ce
        # rôle : on vide pour que le changement soit visible tout de suite.
        try:
            _invalidate_all_ttl_cache()
        except Exception:
            pass
        return jsonify({"success": True})

    @app.route("/settings/insta_rapidapi", methods=["POST"])
    def settings_insta_rapidapi():
        if not is_auth():
            return redirect("/")
        try:
            from insta_scraper import save_auth, load_auth
        except Exception as e:
            return _error(f"✕ Module indispo: {e}")
        key = (request.form.get("rapidapi_key") or "").strip()
        host = (request.form.get("rapidapi_host") or "").strip()
        # Validation host : doit ressembler à un domaine
        DEFAULT_HOST = "instagram-scraper-stable-api.p.rapidapi.com"
        looks_valid_host = (
            host
            and "." in host
            and "/" not in host
            and ":" not in host
            and " " not in host
            and len(host) < 100
            and not host.startswith("http")
        )
        if not looks_valid_host:
            host = DEFAULT_HOST
        if not key or len(key) < 20:
            return _error("✕ Clé RapidAPI invalide (trop courte). Récupère-la sur RapidAPI → ton API → x-rapidapi-key")
        # Garder cookies existants si présents
        current = load_auth()
        current["rapidapi_key"] = key
        current["rapidapi_host"] = host
        save_auth(current)
        return _success(
            f"✓ Sauvegardé. Host : <code>{host}</code> — Clé : <code>{key[:6]}...{key[-4:]}</code>. "
            f"Teste avec le bouton ▶ Tester maintenant."
        )

    @app.route("/settings/insta_auth_file", methods=["POST"])
    def settings_insta_auth_file():
        if not is_auth():
            return redirect("/")
        try:
            from insta_scraper import save_auth, load_auth
        except Exception as e:
            return _error(f"✕ Module indispo: {e}")
        f = request.files.get("cookies_file")
        if not f or not f.filename:
            return _error("✕ Aucun fichier")
        try:
            content = f.read().decode("utf-8", errors="ignore")
        except Exception as e:
            return _error(f"✕ Erreur lecture : {e}")
        # Parser le format Netscape : domain TRUE path TRUE expiry name value (séparés par tab)
        wanted = {"sessionid": None, "ds_user_id": None, "csrftoken": None}
        for line in content.splitlines():
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split("\t")
            if len(parts) < 7:
                continue
            name = parts[5].strip()
            value = parts[6].strip()
            if name in wanted and value:
                wanted[name] = value
        if not wanted["sessionid"]:
            return _error("✕ Aucun <code>sessionid</code> trouvé dans le fichier. "
                "Assure-toi d'être connecté à Instagram avant d'exporter les cookies.",
                error=True,)
        # MERGE dans l'auth existante : NE PAS ecraser rapidapi_key / rapidapi_host
        # (sinon l'upload de cookie casse tout le scrape RapidAPI !).
        _auth = {}
        try:
            _auth = load_auth() or {}
        except Exception:
            _auth = {}
        _auth["sessionid"] = wanted["sessionid"]
        if wanted["ds_user_id"]:
            _auth["ds_user_id"] = wanted["ds_user_id"]
        if wanted["csrftoken"]:
            _auth["csrftoken"] = wanted["csrftoken"]
        save_auth(_auth)
        # Sauve AUSSI le fichier brut (format Netscape) : yt-dlp l'utilise pour
        # telecharger les reels de la Veille (data/insta/cookies.txt).
        ytdlp_ok = False
        try:
            from insta_scraper import INSTA_DIR
            INSTA_DIR.mkdir(parents=True, exist_ok=True)
            (INSTA_DIR / "cookies.txt").write_text(content, encoding="utf-8")
            ytdlp_ok = True
        except Exception:
            pass
        found = [k for k, v in wanted.items() if v]
        extra = " + activé le téléchargement des vidéos Veille (yt-dlp)" if ytdlp_ok else ""
        return _success(f"✓ Cookies importés ({', '.join(found)}){extra}. Tu peux maintenant ajouter des comptes à scraper.")

