    @app.route("/insta/add_account", methods=["POST"])
    def insta_add_account():
        if not is_auth():
            from flask import jsonify
            return jsonify({"ok": False, "error": "unauth"}), 401
        from flask import jsonify
        try:
            from insta_scraper import add_to_watchlist, scrape_profile, is_auth_configured, _clean_username
        except Exception as e:
            return jsonify({"ok": False, "error": f"module indispo: {e}"})
        u = (request.form.get("username") or "").strip()
        if not u:
            return jsonify({"ok": False, "error": "username vide"})
        added = add_to_watchlist(u)
        clean = _clean_username(u)
        if not is_auth_configured():
            return jsonify({
                "ok": True,
                "added": added,
                "username": clean,
                "scrape_started": False,
                "message": f"@{clean} ajouté" + ("" if added else " (déjà present)") +
                           " — configure tes cookies Instagram pour scraper",
            })
        # Cookies OK -> scrape en background (non-bloquant)
        import threading
        def _bg_scrape():
            try:
                scrape_profile(clean, limit=12)
            except Exception:
                pass
        threading.Thread(target=_bg_scrape, daemon=True).start()
        return jsonify({
            "ok": True,
            "added": added,
            "username": clean,
            "scrape_started": True,
            "message": f"@{clean} {'ajouté' if added else 'déjà présent'} — scrape en arrière-plan…",
        })

    @app.route("/insta/fetch_caption", methods=["GET"])
    def insta_fetch_caption():
        """Fetch la caption d'un reel IG depuis sa page publique.
        Tente plusieurs URLs + UAs + patterns. Plus thorough.

        Query : ?url=<permalink>
        Renvoie {ok, caption} ou {ok:False, error, debug}."""
        if not is_auth():
            from flask import jsonify
            return jsonify({"ok": False, "error": "unauth"}), 401
        from flask import jsonify
        import requests as _rq
        import re as _re
        from html import unescape as _unescape
        url = (request.args.get("url") or "").strip()
        if not url:
            return jsonify({"ok": False, "error": "url manquant"})
        m = _re.search(r'/(?:p|reel|reels)/([A-Za-z0-9_-]+)', url)
        if not m:
            return jsonify({"ok": False, "error": "shortcode introuvable dans url"})
        shortcode = m.group(1)
        # CACHE : sidecar .txt écrit par la Veille / le proxy quand la vidéo a
        # été téléchargée -> zéro yt-dlp+cookie. AVANT, chaque carte visible
        # (IntersectionObserver) + chaque play lançait un process yt-dlp avec le
        # cookie : c'était le principal consommateur du cookie IG (donc la
        # cause des murs de vérification). On lit le fichier local d'abord.
        try:
            _side = INSTA_VIDEOS_DIR / f"{shortcode}.txt"
            if _side.exists():
                _c = _side.read_text(encoding="utf-8").strip()
                if _c:
                    return jsonify({"ok": True, "caption": _c[:1000], "cached": True})
        except Exception:
            pass
        # cache mémoire (persisté aussi en sidecar dès qu'on trouve la caption)
        if not hasattr(insta_fetch_caption, "_cap_cache"):
            insta_fetch_caption._cap_cache = {}
        _cap_hit = insta_fetch_caption._cap_cache.get(shortcode)
        if _cap_hit:
            return jsonify({"ok": True, "caption": _cap_hit[:1000], "cached": True})

        def _remember(cap: str):
            """Mémorise la caption trouvée : mémoire + sidecar disque (partagé
            avec la Veille) pour ne plus jamais relancer yt-dlp dessus."""
            try:
                insta_fetch_caption._cap_cache[shortcode] = cap
                _sf = INSTA_VIDEOS_DIR / f"{shortcode}.txt"
                if not _sf.exists():
                    _sf.parent.mkdir(parents=True, exist_ok=True)
                    _sf.write_text(cap, encoding="utf-8")
            except Exception:
                pass
        # yt-dlp + cookie IG : recupere la VRAIE description (fiable). Tente en
        # PREMIER si un cookie est configure (la page publique est souvent bloquee
        # par Instagram). skip_download -> rapide (metadonnees seules).
        try:
            import veille_telegram as _vt
            _ck = _vt._find_ig_cookies()
            if _ck:
                import yt_dlp as _ytdl
                with _ytdl.YoutubeDL({"quiet": True, "no_warnings": True,
                                      "skip_download": True, "cookiefile": _ck}) as _yd:
                    _info = _yd.extract_info(url, download=False)
                _desc = (_info.get("description") or "").strip()
                if _desc:
                    _remember(_desc)
                    return jsonify({"ok": True, "caption": _desc[:1000]})
        except Exception:
            pass
        # Combine plusieurs URLs + UAs (fallback no-cookie)
        urls = [
            f"https://www.instagram.com/p/{shortcode}/",
            f"https://www.instagram.com/reel/{shortcode}/",
            f"https://www.instagram.com/p/{shortcode}/embed/captioned/",
            f"https://www.instagram.com/p/{shortcode}/embed/",
        ]
        uas = [
            "facebookexternalhit/1.1 (+http://www.facebook.com/externalhit_uatext.php)",
            "Mozilla/5.0 (compatible; Twitterbot/1.0)",
            "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) "
            "AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1",
        ]
        patterns = [
            r'<meta\s+property="og:description"\s+content="([^"]+)"',
            r'<meta\s+name="description"\s+content="([^"]+)"',
            r'<meta\s+property="og:title"\s+content="([^"]+)"',
            r'<meta\s+name="twitter:description"\s+content="([^"]+)"',
            r'"caption"\s*:\s*\{\s*"text"\s*:\s*"([^"]+)"',
            r'"caption"\s*:\s*"([^"]*?)"',
            r'"accessibility_caption"\s*:\s*"([^"]+)"',
            r'"edge_media_to_caption"\s*:\s*\{\s*"edges"\s*:\s*\[\s*\{\s*"node"\s*:\s*\{\s*"text"\s*:\s*"([^"]+)"',
            r'<title>([^<]+)</title>',
        ]
        tried = []
        for url_try in urls:
            for ua in uas:
                try:
                    r = _rq.get(url_try, headers={
                        "User-Agent": ua,
                        "Accept": "text/html,application/xhtml+xml",
                        "Accept-Language": "fr-FR,fr;q=0.9,en;q=0.8",
                    }, timeout=8)
                    tried.append(f"{url_try.split('/')[-2]}/{ua[:20]}={r.status_code}")
                    if r.status_code != 200:
                        continue
                    html = r.text
                    for pat in patterns:
                        mm = _re.search(pat, html)
                        if mm:
                            cap = mm.group(1)
                            try:
                                cap = cap.encode().decode("unicode_escape")
                            except Exception:
                                pass
                            cap = _unescape(cap)
                            # NETTOYAGE des prefixes typiques d'og:description IG :
                            # "1,234 likes, 56 comments - username on May 28, 2026: 'CAPTION'"
                            # "1,234 likes, 56 comments - username le 28 mai 2026: 'CAPTION'"
                            # Format avec quotes : on extrait le contenu entre quotes
                            quote_match = _re.search(r'[:][\s\"“]+([^"”]+?)["”]\s*\.?\s*$', cap)
                            if quote_match:
                                cap = quote_match.group(1)
                            elif ":" in cap and ("likes" in cap.lower() or "comments" in cap.lower()
                                                  or "on Instagram" in cap):
                                # Prend tout ce qui est apres le DERNIER ":" (la caption)
                                cap = cap.rsplit(":", 1)[1].strip()
                                cap = cap.strip('"“”').strip()
                            cap = cap.strip().strip('.')
                            # Skip si c'est juste le titre/username sans contenu utile
                            if cap and len(cap) > 5 and not cap.startswith("Instagram"):
                                _remember(cap)
                                return jsonify({"ok": True, "caption": cap[:1000]})
                except Exception:
                    continue
        return jsonify({"ok": False, "error": "caption introuvable", "tried": tried[:10]})

    @app.route("/insta/debug_rapidapi", methods=["GET"])
    def insta_debug_rapidapi():
        """Affiche la reponse RapidAPI brute pour debug d'un reel donne.
        Query : ?owner=username&shortcode=SHORTCODE
        Renvoie le reel matched avec TOUTES les keys/values en JSON."""
        if not is_auth():
            from flask import jsonify
            return jsonify({"ok": False, "error": "unauth"}), 401
        from flask import jsonify
        owner = (request.args.get("owner") or "").strip()
        shortcode = (request.args.get("shortcode") or "").strip()
        if not (owner and shortcode):
            return jsonify({"ok": False, "error": "owner + shortcode requis"})
        try:
            from insta_scraper import scrape_profile
            result = scrape_profile(owner, limit=500)
            if "error" in result:
                return jsonify({"ok": False, "error": result["error"]})
            for reel in result.get("reels", []):
                if reel.get("shortcode") == shortcode:
                    return jsonify({"ok": True, "reel": reel,
                                    "nb_reels_total": len(result.get("reels", []))})
            return jsonify({"ok": False, "error": f"shortcode pas trouve parmi {len(result.get('reels', []))}"})
        except Exception as e:
            return jsonify({"ok": False, "error": f"{type(e).__name__}: {e}"})

    @app.route("/insta/proxy_video", methods=["GET"])
    def insta_proxy_video():
        """Proxy SIMPLE : utilise UNIQUEMENT RapidAPI pour recup le video_url
        (pas d'instaloader/cookies). Stream le contenu CDN IG vers le browser.

        Query : ?url=<permalink>&owner=<username>
        """
        if not is_auth():
            return ("unauth", 401)
        from flask import Response, stream_with_context
        import requests as _rq
        import time as _t
        import re as _re
        post_url = (request.args.get("url") or "").strip()
        direct_vurl = (request.args.get("vurl") or "").strip()
        owner = (request.args.get("owner") or "").strip()
        if not post_url and not direct_vurl:
            return ("url ou vurl requise", 400)
        # Anti-SSRF : le proxy ne doit streamer QUE des vidéos Instagram / CDN
        # Meta. Sans ça, ?vurl=http://169.254.169.254/… ou une URL interne était
        # fetché et renvoyé au navigateur (fuite de métadonnées cloud, scan du
        # réseau interne). On valide l'hôte des deux paramètres d'URL.
        def _host_ok(u: str) -> bool:
            try:
                from urllib.parse import urlparse as _up
                pr = _up(u)
                if pr.scheme not in ("http", "https"):
                    return False
                h = (pr.hostname or "").lower().rstrip(".")
                # Le hostname vu par urlparse n'est PAS forcément celui que
                # urllib3 va joindre : « 169.254.169.254\.instagram.com » a un
                # hostname qui FINIT par .instagram.com (donc validé) mais
                # urllib3 traite le « \ » comme séparateur de chemin et se
                # connecte à 169.254.169.254 (SSRF). On rejette donc tout host
                # contenant un caractère hors [a-z0-9.-] AVANT l'allowlist.
                if not h or _re.fullmatch(r"[a-z0-9.-]+", h) is None:
                    return False
                # Ancré sur une frontière de point : « evil-instagram.com » ou
                # « attacker-facebook.com » ne doivent PLUS passer.
                _ok_dom = ("instagram.com", "cdninstagram.com", "fbcdn.net", "facebook.com")
                return any(h == d or h.endswith("." + d) for d in _ok_dom)
            except Exception:
                return False
        for _u in (post_url, direct_vurl):
            if _u and not _host_ok(_u):
                return ("URL non autorisée (Instagram uniquement)", 403)
        ig_headers = {
            "User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 "
                          "(KHTML, like Gecko) Chrome/120.0 Safari/537.36",
            "Referer": "https://www.instagram.com/",
        }
        # Cache memoire des resolutions instaloader (50 min)
        if not hasattr(insta_proxy_video, "_cache"):
            insta_proxy_video._cache = {}
        cache = insta_proxy_video._cache
        now = _t.time()
        CACHE_TTL = 7 * 24 * 60 * 60  # 1 semaine
        def try_stream(video_url, fast=False):
            """Tente de stream depuis video_url. Retourne Response ou None si echec.
            fast=True : timeout 4s pour la HEAD initiale (detection URL morte rapide).
            """
            # Défense en profondeur : point de contrôle UNIQUE. On ne streame QUE des
            # hôtes Instagram / CDN Meta, y compris pour une URL résolue via RapidAPI
            # ou le scrape de page (pas seulement les paramètres url/vurl de l'appelant).
            if not _host_ok(video_url or ""):
                return None
            # requests suit les 30x par défaut SANS re-valider l'hôte final : un
            # 302 vers 169.254.169.254 serait suivi et streamé (SSRF). On suit
            # donc les redirections À LA MAIN en re-validant chaque saut.
            from urllib.parse import urljoin as _urljoin
            try:
                cur = video_url
                upstream = None
                for _hop in range(4):
                    upstream = _rq.get(
                        cur, headers=ig_headers, stream=True,
                        timeout=(4 if fast else 30), allow_redirects=False,
                    )
                    if upstream.status_code in (301, 302, 303, 307, 308):
                        loc = upstream.headers.get("Location") or ""
                        upstream.close()
                        nxt = _urljoin(cur, loc)     # relatif -> même hôte (déjà validé)
                        if not _host_ok(nxt):
                            return None               # redirection hors allowlist : STOP
                        cur = nxt
                        upstream = None
                        continue
                    break
            except Exception:
                return None
            if upstream is None or upstream.status_code != 200:
                if upstream is not None:
                    upstream.close()
                return None
            content_type = upstream.headers.get("Content-Type", "video/mp4")
            content_length = upstream.headers.get("Content-Length")
            def generate():
                try:
                    for chunk in upstream.iter_content(chunk_size=64 * 1024):
                        if chunk:
                            yield chunk
                finally:
                    upstream.close()
            resp = Response(stream_with_context(generate()), mimetype=content_type)
            if content_length:
                resp.headers["Content-Length"] = content_length
            # Les URLs CDN Instagram restent valides des heures -> 1h de cache
            # navigateur (evite de re-streamer la meme video a chaque re-clic).
            resp.headers["Cache-Control"] = "private, max-age=3600"
            return resp
        # Extraction shortcode pour cache disque
        m_sc = _re.search(r'/(?:p|reel|reels)/([A-Za-z0-9_-]+)', post_url or '')
        sc = m_sc.group(1) if m_sc else ''
        # ETAPE 0 : fichier disque (telecharge par le daemon ou DL on-demand)
        if sc:
            from pathlib import Path as _P
            disk_file = _P("data/insta/videos") / f"{sc}.mp4"
            if disk_file.exists() and disk_file.stat().st_size > 1024:
                from flask import send_file
                return send_file(str(disk_file), mimetype="video/mp4", conditional=True)
        # ETAPE 0.5 : yt-dlp + cookie IG (la meme methode que la Veille). FIABLE pour
        # TOUS les reels (l'API ne donne pas la video). On ne tente que si un cookie
        # est configure. Telecharge -> cache disque -> sert (les prochains clics =
        # instantanes via l'ETAPE 0).
        if sc and post_url:
            try:
                import veille_telegram as _vt
                if _vt._find_ig_cookies():
                    _yi = {}
                    _yb = _vt.download_via_ytdlp(post_url, timeout=25, info=_yi)
                    if _yb:
                        from pathlib import Path as _P2
                        _vd = _P2("data/insta/videos"); _vd.mkdir(parents=True, exist_ok=True)
                        (_vd / f"{sc}.mp4").write_bytes(_yb)
                        # sauve AUSSI la description -> dispo pour la Veille (cache hit)
                        if _yi.get("description"):
                            try:
                                (_vd / f"{sc}.txt").write_text(_yi["description"], encoding="utf-8")
                            except Exception:
                                pass
                        from flask import send_file
                        return send_file(str(_vd / f"{sc}.mp4"), mimetype="video/mp4", conditional=True)
            except Exception:
                pass
        # ETAPE 1 : essaie URL directe (cas reel fresh)
        if direct_vurl:
            res = try_stream(direct_vurl)
            if res is not None:
                # Sauvegarde sur disque pour future plays instantanes
                if sc:
                    import threading as _th
                    _th.Thread(target=_download_reel_video,
                               args=(sc, direct_vurl), daemon=True).start()
                return res
        # ETAPE 2 : cache memoire des fresh URLs scrapees precedemment
        if post_url:
            cached = cache.get(post_url)
            if cached and (now - cached["ts"]) < CACHE_TTL:
                res = try_stream(cached["video_url"])
                if res is not None:
                    if sc:
                        import threading as _th
                        _th.Thread(target=_download_reel_video,
                                   args=(sc, cached["video_url"]), daemon=True).start()
                    return res
                cache.pop(post_url, None)
        # ETAPE 3 : RapidAPI UNIQUEMENT - pas d'instaloader, pas de cookies IG.
        m = _re.search(r'/(?:p|reel|reels)/([A-Za-z0-9_-]+)', post_url or '')
        shortcode = m.group(1) if m else ''
        if not (owner and shortcode):
            return ("owner + shortcode requis pour refresh RapidAPI", 400)
        try:
            from insta_scraper import scrape_profile, get_cached
            # 3a : check cache disque (peut deja avoir un fresh URL)
            cached_data = get_cached(owner)
            if cached_data:
                for reel in cached_data.get("reels", []):
                    if reel.get("shortcode") == shortcode:
                        video_url = (reel.get("video_url") or "").strip()
                        if video_url:
                            res = try_stream(video_url)
                            if res is not None:
                                cache[post_url] = {"ts": now, "video_url": video_url}
                                return res
                        break
            # 3b : fresh scrape RapidAPI - limit 500 pour couvrir les vieux reels
            result = scrape_profile(owner, limit=500)
            if "error" in result:
                return (f"RapidAPI: {result['error'][:200]}", 502)
            nb_reels = len(result.get("reels", []))
            for reel in result.get("reels", []):
                if reel.get("shortcode") == shortcode:
                    video_url = (reel.get("video_url") or "").strip()
                    if not video_url:
                        # Tente endpoint RapidAPI single-post
                        try:
                            from insta_scraper import _scrape_via_rapidapi_single_post
                            single = _scrape_via_rapidapi_single_post(shortcode)
                            if single and single.get("video_url"):
                                video_url = single["video_url"]
                        except Exception:
                            pass
                    if not video_url:
                        # Scrape la page Instagram directement (/p/ et /embed/)
                        video_url = _scrape_ig_page_for_video(shortcode)
                    if not video_url:
                        return ("Reel public mais URL video introuvable apres RapidAPI + scraping page. Bug API.", 404)
                    cache[post_url] = {"ts": now, "video_url": video_url}
                    res = try_stream(video_url)
                    if res is not None:
                        if shortcode:
                            import threading as _th
                            _th.Thread(target=_download_reel_video,
                                       args=(shortcode, video_url), daemon=True).start()
                        return res
                    return ("URL RapidAPI mais CDN refuse stream", 502)
            return (f"@{owner} : reel {shortcode} introuvable parmi {nb_reels} reels scrapes", 404)
        except Exception as e:
            return (f"RapidAPI error: {type(e).__name__}: {str(e)[:200]}", 500)

    @app.route("/insta/refresh_video_url", methods=["POST"])
    def insta_refresh_video_url():
        """Re-fetch un video_url frais pour un reel donne (les URLs IG expirent).
        Body : url (permalink du reel/post)
        Returns : {ok, video_url, caption?}

        Cache memoire 50 min (les URLs CDN IG durent qq heures, on prend marge).
        """
        if not is_auth():
            from flask import jsonify
            return jsonify({"ok": False, "error": "unauth"}), 401
        from flask import jsonify
        import time as _t
        try:
            import veille_telegram
        except Exception as e:
            return jsonify({"ok": False, "error": f"module indispo: {e}"})
        url = (request.form.get("url") or "").strip()
        if not url:
            return jsonify({"ok": False, "error": "url manquante"})
        # Cache hit ?
        if not hasattr(insta_refresh_video_url, "_cache"):
            insta_refresh_video_url._cache = {}
        cache = insta_refresh_video_url._cache
        now = _t.time()
        CACHE_TTL = 50 * 60  # 50 minutes
        # Purge stale entries (lazy)
        if len(cache) > 200:
            for k in list(cache.keys()):
                if now - cache[k]["ts"] > CACHE_TTL:
                    del cache[k]
        cached = cache.get(url)
        if cached and (now - cached["ts"]) < CACHE_TTL:
            return jsonify({
                "ok": True,
                "video_url": cached["video_url"],
                "caption": cached.get("caption", ""),
                "cached": True,
            })
        try:
            fresh = veille_telegram.refresh_post_data(url)
        except Exception as e:
            return jsonify({"ok": False, "error": f"refresh: {e}"})
        if not fresh.get("video_url"):
            debug_info = fresh.get("_debug") or "raison inconnue"
            return jsonify({
                "ok": False,
                "error": f"video_url introuvable ({debug_info})",
                "debug": debug_info,
            })
        # Save cache
        cache[url] = {
            "ts": now,
            "video_url": fresh["video_url"],
            "caption": fresh.get("caption", ""),
        }
        return jsonify({
            "ok": True,
            "video_url": fresh["video_url"],
            "caption": fresh.get("caption", ""),
            "cached": False,
        })

